import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: dict mapping agent_id -> reputation score
        # Initialize everyone with neutral score 0.5
        self.reputation = {}
        # Track cooperation counts for each agent (optional, but useful)
        self.coop_count = {}
        self.defect_count = {}
        # Track my own history for pattern recognition
        self.my_actions = []
        self.my_partners = []
        # Track recent outcomes with each partner
        self.partner_history = {}  # partner_id -> list of (my_action, their_action)
        # Simple trust threshold
        self.trust_threshold = 0.4
        # Track generation number if needed, but not required

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            # No opponent info, default to cooperate
            return True

        # Get reputation of opponent, default to neutral 0.5
        opp_rep = self.reputation.get(opponent, 0.5)

        # If we have history with this partner, use it
        if opponent in self.partner_history:
            history = self.partner_history[opponent]
            if len(history) >= 3:
                # Check recent cooperation rate
                recent = history[-3:]
                coop_rate = sum(1 for my, their in recent if their == 'cooperate') / len(recent)
                # If they've been cooperative recently, cooperate
                if coop_rate >= 0.5:
                    return True
                else:
                    # If they've been defecting, defect
                    return False

        # Otherwise use reputation
        if opp_rep >= self.trust_threshold:
            return True
        else:
            return False

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation based on observed actions
        # Simple rule: cooperate +1, defect -0.5, with bounds
        try:
            # Update donor reputation
            if donor_id != self.agent_id:
                # Donor's action reflects on them
                if donor_action == 'cooperate':
                    self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + 0.1
                else:
                    self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - 0.15
                # Clamp to [0,1]
                self.reputation[donor_id] = max(0.0, min(1.0, self.reputation[donor_id]))

            # Update recipient reputation
            if recipient_id != self.agent_id:
                if recipient_action == 'cooperate':
                    self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + 0.1
                else:
                    self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - 0.15
                self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation[recipient_id]))

            # If I am involved, update my personal history
            if donor_id == self.agent_id:
                self.my_actions.append(donor_action)
                self.my_partners.append(recipient_id)
                # Update partner history
                if recipient_id not in self.partner_history:
                    self.partner_history[recipient_id] = []
                self.partner_history[recipient_id].append((donor_action, recipient_action))
            elif recipient_id == self.agent_id:
                self.my_actions.append(recipient_action)
                self.my_partners.append(donor_id)
                if donor_id not in self.partner_history:
                    self.partner_history[donor_id] = []
                self.partner_history[donor_id].append((recipient_action, donor_action))
        except Exception:
            # Fail safe: do nothing on error
            pass

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_counts = {}
        self.defect_counts = {}
        self.own_coop = 0
        self.own_defect = 0
        self.round_num = 0
        self._ctx_opponent_id = None
        self.opponent_histories = {}

    def decide(self) -> bool:
        self.round_num += 1
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        opp_coop = self.coop_counts.get(opp, 0)
        opp_def = self.defect_counts.get(opp, 0)
        opp_total = opp_coop + opp_def
        if opp_total == 0:
            return True
        coop_ratio = opp_coop / opp_total
        # Be more cooperative with cooperative opponents, but add slight randomness
        threshold = 0.5 + 0.1 * math.sin(self.round_num / 3)
        if coop_ratio >= threshold:
            return random.random() < 0.9
        else:
            return random.random() < 0.3

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_defect += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_defect += 1
        # Track opponent behavior
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation, update both
            if donor_action == 'cooperate':
                self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + 1
            else:
                self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + 1
            if recipient_action == 'cooperate':
                self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + 1
            else:
                self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + 1
        elif donor_id == self.agent_id:
            # We are donor, observe recipient
            if recipient_action == 'cooperate':
                self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + 1
            else:
                self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + 1
        elif recipient_id == self.agent_id:
            # We are recipient, observe donor
            if donor_action == 'cooperate':
                self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + 1
            else:
                self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + 1

