class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each other agent, track cooperation count and defect count
        self.reputation = {}  # agent_id -> [coop_count, defect_count]
        # Track my own actions and outcomes
        self.my_coop_count = 0
        self.my_defect_count = 0
        # Track pairwise interactions: (my_id, other_id) -> [my_coop, my_defect, other_coop, other_defect]
        self.pair_stats = {}
        # Track recent behavior to detect changes
        self.recent_actions = []  # list of (other_id, action) from observations
        # Strategy parameters
        self.trust_threshold = 0.4
        self.forgiveness = 0.2
        self.exploration_rate = 0.05
        self.round_count = 0
        self.generation = 0
        self.opponent_id = None
        # Initialize reputation for all possible agents (0-14)
        for i in range(15):
            self.reputation[i] = [0, 0]

    def decide(self) -> bool:
        # Increment round count
        self.round_count += 1
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.opponent_id = opponent

        # If no opponent, default to cooperate
        if opponent is None:
            return True

        # Get reputation of opponent
        coop, defect = self.reputation.get(opponent, [0, 0])
        total = coop + defect
        if total == 0:
            # No info - start with cooperate to build trust
            return True

        coop_ratio = coop / total

        # Check our past interactions with this opponent
        pair_key = (self.agent_id, opponent) if self.agent_id < opponent else (opponent, self.agent_id)
        my_coop, my_defect, other_coop, other_defect = self.pair_stats.get(pair_key, [0, 0, 0, 0])
        my_total = my_coop + my_defect

        # Adaptive strategy based on opponent's reputation and our history
        if my_total < 3:
            # Early phase: be trusting but not naive
            if coop_ratio > self.trust_threshold:
                return True
            else:
                # If opponent has defected a lot, be cautious
                return random.random() > 0.3
        else:
            # Established relationship
            my_ratio = my_coop / my_total if my_total > 0 else 0.5
            # Tit-for-tat with forgiveness based on reputation
            if other_defect > 0 and my_coop > 0:
                # If they've defected recently, respond with defect unless they have good reputation
                if coop_ratio < 0.3:
                    return False
                elif coop_ratio < 0.5:
                    # Be cautious with moderate reputation
                    return random.random() > 0.5
                else:
                    # Good reputation - cooperate with forgiveness
                    return True
            else:
                # They haven't defected - cooperate
                return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents involved
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                # Track my own actions
                if action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            else:
                # Update reputation for others
                if agent_id in self.reputation:
                    if action == 'cooperate':
                        self.reputation[agent_id][0] += 1
                    else:
                        self.reputation[agent_id][1] += 1

        # Update pairwise stats if this involves me
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action

            pair_key = (self.agent_id, other_id) if self.agent_id < other_id else (other_id, self.agent_id)
            if pair_key not in self.pair_stats:
                self.pair_stats[pair_key] = [0, 0, 0, 0]

            stats = self.pair_stats[pair_key]
            if my_action == 'cooperate':
                stats[0] += 1
            else:
                stats[1] += 1
            if other_action == 'cooperate':
                stats[2] += 1
            else:
                stats[3] += 1

        # Keep recent actions for pattern detection (limit to last 50)
        if donor_id != self.agent_id:
            self.recent_actions.append((donor_id, donor_action))
        if recipient_id != self.agent_id:
            self.recent_actions.append((recipient_id, recipient_action))
        if len(self.recent_actions) > 50:
            self.recent_actions = self.recent_actions[-50:]

