class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation: mapping from agent id to a score in [0, 1]
        self.reputation = {}
        # Track cooperation rate per agent (for potential forgiveness)
        self.coop_count = {}
        self.total_count = {}
        # Track self behavior
        self.self_coop = 0
        self.self_total = 0
        # Current opponent id set by framework
        self._ctx_opponent_id = None
        # Deterministc but with a tiny bit of randomness to avoid deadlock
        self.noise = 0.05

    def _init_rep(self, agent_id: int) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if agent_id not in self.coop_count:
            self.coop_count[agent_id] = 0
        if agent_id not in self.total_count:
            self.total_count[agent_id] = 0

    def decide(self) -> bool:
        # If no opponent info, default to cooperate
        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id
        self._init_rep(opp)
        rep = self.reputation[opp]
        # Simple threshold: cooperate if reputation >= 0.5
        # Add slight noise to break ties
        if rep >= 0.5:
            return random.random() > self.noise
        else:
            return random.random() < self.noise

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Initialize if needed
        self._init_rep(donor_id)
        self._init_rep(recipient_id)

        # Update counts for donor and recipient
        self.total_count[donor_id] += 1
        self.total_count[recipient_id] += 1
        if donor_action == 'cooperate':
            self.coop_count[donor_id] += 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] += 1

        # Update reputations based on observed actions
        # For donor: cooperating is good, defecting is bad
        if donor_action == 'cooperate':
            self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + 0.1)
        else:
            self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - 0.15)

        # For recipient: how they respond matters
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + 0.1)
        else:
            self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - 0.15)

        # Self-judgment: adjust self-reputation based on own actions
        if donor_id == self.agent_id:
            self.self_total += 1
            if donor_action == 'cooperate':
                self.self_coop += 1
        if recipient_id == self.agent_id:
            self.self_total += 1
            if recipient_action == 'cooperate':
                self.self_coop += 1

        # Occasionally decay reputation to avoid permanent grudges
        # Decay all reputations slightly toward 0.5 every observation
        decay = 0.001
        for aid in self.reputation:
            self.reputation[aid] += (0.5 - self.reputation[aid]) * decay

        # Also use overall cooperation rate to modulate reputation
        # If an agent has a high cooperation rate, boost them slightly
        for aid in self.total_count:
            if self.total_count[aid] > 0:
                rate = self.coop_count[aid] / self.total_count[aid]
                # Blend: 30% from rate, 70% from existing reputation
                self.reputation[aid] = 0.7 * self.reputation[aid] + 0.3 * rate

