class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> running score (positive for cooperate, negative for defect)
        self.encounters = {}  # agent_id -> list of (my_action, their_action)
        self.round_num = 0
        self.opponent_history = {}  # agent_id -> list of actions they did to others

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Get reputation score of opponent
        score = self.reputation.get(opponent, 0)

        # If we have history with this opponent, use it
        if opponent in self.encounters and len(self.encounters[opponent]) >= 1:
            my_actions = [a[0] for a in self.encounters[opponent]]
            their_actions = [a[1] for a in self.encounters[opponent]]
            # Tit-for-tat: cooperate if they cooperated last time, defect if they defected
            if their_actions[-1] == 'cooperate':
                return True
            else:
                return False

        # No history: base on reputation
        # Strong reputation -> cooperate, bad reputation -> defect
        if score > 2:
            return True
        elif score < -2:
            return False
        else:
            # Neutral: use a simple strategy based on round number
            # Cooperate more early, defect more late
            return self.round_num < 15

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round counter when we observe ourselves as donor
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_num += 1

        # Update reputation of both agents based on their actions
        # Cooperate gives +1, defect gives -1
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 1
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 1

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + 1
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) - 1

        # Record encounter if we are involved
        if donor_id == self.agent_id:
            self.encounters.setdefault(recipient_id, []).append((donor_action, recipient_action))
        elif recipient_id == self.agent_id:
            self.encounters.setdefault(donor_id, []).append((recipient_action, donor_action))

        # Track opponent behavior toward others (for future predictions)
        if donor_id != self.agent_id:
            self.opponent_history.setdefault(donor_id, []).append(donor_action)
        if recipient_id != self.agent_id:
            self.opponent_history.setdefault(recipient_id, []).append(recipient_action)

