import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores for all other agents (positive = good, negative = bad)
        self.reputations = {}
        # Track cooperation rates per opponent
        self.coop_counts = {}
        self.total_counts = {}
        # Track own history for adaptation
        self.my_defections = 0
        self.my_cooperations = 0
        # Memory of recent interactions for pattern detection
        self.recent_partners = []
        self.recent_action_taken = []
        # Baseline cooperation threshold
        self.coop_threshold = 0.5
        # Track observed reciprocity: if others cooperate with cooperators, higher trust
        self.reciprocity_scores = {}
        # Number of observations for each agent
        self.observation_counts = {}
        # Store last opponent id for decision context
        self._ctx_opponent_id = None

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True  # Shouldn't happen, but safe
        opp = self._ctx_opponent_id
        # Get reputation of opponent (default 0.0 if unknown)
        rep = self.reputations.get(opp, 0.0)
        # Get cooperation rate if known, else assume 0.5
        coop_rate = 0.5
        if opp in self.total_counts and self.total_counts[opp] > 0:
            coop_rate = self.coop_counts.get(opp, 0) / self.total_counts[opp]
        # Adjust threshold based on own recent behavior: if self defects often, lower threshold
        own_rate = 0.5
        total_own = self.my_cooperations + self.my_defections
        if total_own > 0:
            own_rate = self.my_cooperations / total_own
        threshold = self.coop_threshold
        # If I've been cooperating a lot and others don't reciprocate, be more cautious
        if own_rate > 0.7 and coop_rate < 0.3:
            threshold += 0.1
        # If opponent has high reputation, cooperate more
        if rep > 0.3:
            threshold -= 0.2
        elif rep < -0.3:
            threshold += 0.2
        # Combine reputation and observed cooperation rate
        expected_coop = 0.5 * (1 + rep) * 0.5 + 0.5 * coop_rate
        # Decide: cooperate if expected cooperation is high enough
        return expected_coop >= threshold

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        # Update observations for all agents involved
        try:
            # Update reputation for donor based on action
            if donor_id != self.agent_id:
                self._update_reputation(donor_id, donor_action)
            # Update reputation for recipient based on action
            if recipient_id != self.agent_id:
                self._update_reputation(recipient_id, recipient_action)
            # Track cooperation rates for opponent (if it's me, track own)
            if donor_id == self.agent_id:
                # Self action
                if donor_action == 'cooperate':
                    self.my_cooperations += 1
                else:
                    self.my_defections += 1
                # Track how recipient responded
                if recipient_id != self.agent_id:
                    self._track_opponent(recipient_id, recipient_action)
            elif recipient_id == self.agent_id:
                # Self is recipient
                if recipient_action == 'cooperate':
                    self.my_cooperations += 1
                else:
                    self.my_defections += 1
                # Track how donor behaved toward me
                if donor_id != self.agent_id:
                    self._track_opponent(donor_id, donor_action)
            else:
                # Third party: track both agents' behavior
                self._track_opponent(donor_id, donor_action)
                self._track_opponent(recipient_id, recipient_action)
                # Also update reciprocity: if donor cooperates and recipient cooperates, that's good
                if donor_action == 'cooperate' and recipient_action == 'cooperate':
                    self._update_reciprocity(donor_id, recipient_id, 1)
                elif donor_action == 'defect' and recipient_action == 'defect':
                    self._update_reciprocity(donor_id, recipient_id, -0.5)
                elif donor_action == 'cooperate' and recipient_action == 'defect':
                    self._update_reciprocity(donor_id, recipient_id, -1)
                elif donor_action == 'defect' and recipient_action == 'cooperate':
                    self._update_reciprocity(donor_id, recipient_id, -0.5)
        except Exception:
            pass  # Safety: never crash

    def _update_reputation(self, agent_id: int, action: str) -> None:
        # Reputation update: cooperate +1, defect -1, with decay toward 0
        current = self.reputations.get(agent_id, 0.0)
        if action == 'cooperate':
            current += 0.2
        else:
            current -= 0.2
        # Decay toward 0 to prevent runaway values
        current *= 0.95
        # Clamp to [-1, 1]
        current = max(-1.0, min(1.0, current))
        self.reputations[agent_id] = current

    def _track_opponent(self, agent_id: int, action: str) -> None:
        # Track total and coop counts
        if agent_id not in self.total_counts:
            self.total_counts[agent_id] = 0
            self.coop_counts[agent_id] = 0
        self.total_counts[agent_id] += 1
        if action == 'cooperate':
            self.coop_counts[agent_id] += 1

    def _update_reciprocity(self, donor_id: int, recipient_id: int, value: float) -> None:
        # Simple update: store a reciprocity score for the pair
        key = (donor_id, recipient_id)
        if key not in self.reciprocity_scores:
            self.reciprocity_scores[key] = 0.0
        self.reciprocity_scores[key] = self.reciprocity_scores[key] * 0.9 + value * 0.1

