class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation: key = agent_id, value = list of recent cooperation rates
        self.reputation = {}
        self.recent_scores = {}
        self.cooperation_history = {}
        self.defection_history = {}
        # Track my own recent actions and outcomes
        self.my_actions = []
        self.my_rewards = []
        # Track opponent tendencies for direct interaction
        self.opponent_tendency = {}
        # Memory of last action against each opponent
        self.last_action = {}
        self.last_opponent_action = {}
        # Simple model parameters
        self.epsilon = 0.05  # exploration probability
        self.generosity = 0.1  # sometimes cooperate even if opponent defected
        self.trust_threshold = 0.6  # reputation threshold to cooperate
        self.history_length = 20  # how many recent observations to keep
        # Initialize reputation for all possible agents (we don't know N, but we can grow)
        # We'll use dynamic growth

    def _get_rep(self, agent_id: int) -> float:
        """Get current reputation (average recent cooperation rate)"""
        if agent_id not in self.reputation:
            return 0.5  # neutral initial reputation
        scores = self.reputation[agent_id]
        if not scores:
            return 0.5
        return sum(scores) / len(scores)

    def _update_rep(self, agent_id: int, action: str) -> None:
        """Update reputation based on observed action"""
        if agent_id not in self.reputation:
            self.reputation[agent_id] = []
        # Append 1 for cooperate, 0 for defect
        self.reputation[agent_id].append(1.0 if action == 'cooperate' else 0.0)
        # Keep only recent history
        if len(self.reputation[agent_id]) > self.history_length:
            self.reputation[agent_id] = self.reputation[agent_id][-self.history_length:]

    def _update_opponent_tendency(self, opponent_id: int, action: str) -> None:
        """Update the tendency of a specific opponent based on their action"""
        if opponent_id not in self.opponent_tendency:
            self.opponent_tendency[opponent_id] = []
        self.opponent_tendency[opponent_id].append(1.0 if action == 'cooperate' else 0.0)
        if len(self.opponent_tendency[opponent_id]) > self.history_length:
            self.opponent_tendency[opponent_id] = self.opponent_tendency[opponent_id][-self.history_length:]

    def _get_opponent_tendency(self, opponent_id: int) -> float:
        """Get probability opponent cooperates based on direct observations"""
        if opponent_id not in self.opponent_tendency:
            return 0.5
        scores = self.opponent_tendency[opponent_id]
        if not scores:
            return 0.5
        return sum(scores) / len(scores)

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        # Get opponent's reputation
        opp_rep = self._get_rep(opponent_id)
        # Get direct tendency from interactions with this opponent
        direct_tendency = self._get_opponent_tendency(opponent_id)
        # Combine reputation and direct tendency (weight direct more if we have data)
        if opponent_id in self.opponent_tendency and len(self.opponent_tendency[opponent_id]) > 0:
            # Weighted average: 60% direct, 40% reputation
            combined = 0.6 * direct_tendency + 0.4 * opp_rep
        else:
            combined = opp_rep

        # If we have interacted before, check last opponent action
        if opponent_id in self.last_opponent_action:
            last_opp = self.last_opponent_action[opponent_id]
            if last_opp == 'defect':
                # If they defected last time, be more cautious
                combined *= 0.7
            else:
                # If they cooperated last time, be more trusting
                combined = min(1.0, combined * 1.2)

        # Decide based on threshold
        cooperate = combined >= self.trust_threshold

        # Exploration: occasionally try cooperation even if likely to defect
        if random.random() < self.epsilon:
            cooperate = True

        # Sometimes be generous and cooperate even if opponent has bad reputation
        if random.random() < self.generosity:
            cooperate = True

        # Store our action for later
        self.last_action[opponent_id] = 'cooperate' if cooperate else 'defect'
        return cooperate

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both actors
        self._update_rep(donor_id, donor_action)
        self._update_rep(recipient_id, recipient_action)

        # Update direct tendency if we are involved
        if donor_id == self.agent_id:
            # I was the donor
            self.last_opponent_action[recipient_id] = recipient_action
            if recipient_id in self.opponent_tendency:
                self.opponent_tendency[recipient_id].append(1.0 if recipient_action == 'cooperate' else 0.0)
                if len(self.opponent_tendency[recipient_id]) > self.history_length:
                    self.opponent_tendency[recipient_id] = self.opponent_tendency[recipient_id][-self.history_length:]
            else:
                self.opponent_tendency[recipient_id] = [1.0 if recipient_action == 'cooperate' else 0.0]
        elif recipient_id == self.agent_id:
            # I was the recipient
            self.last_opponent_action[donor_id] = donor_action
            if donor_id in self.opponent_tendency:
                self.opponent_tendency[donor_id].append(1.0 if donor_action == 'cooperate' else 0.0)
                if len(self.opponent_tendency[donor_id]) > self.history_length:
                    self.opponent_tendency[donor_id] = self.opponent_tendency[donor_id][-self.history_length:]
            else:
                self.opponent_tendency[donor_id] = [1.0 if donor_action == 'cooperate' else 0.0]
        else:
            # Third-party observation - just update reputation (already done)
            pass

        # Track my own actions and outcomes for learning (optional)
        if donor_id == self.agent_id:
            self.my_actions.append(donor_action)
            # Track reward based on recipient action
            if recipient_action == 'cooperate':
                self.my_rewards.append(1 if donor_action == 'cooperate' else 0)
            else:
                self.my_rewards.append(0)
            if len(self.my_actions) > 100:
                self.my_actions = self.my_actions[-100:]
                self.my_rewards = self.my_rewards[-100:]

