        # Initialize cooperation score for new opponents
        if opp not in self.cooperation_scores:
            self.cooperation_scores[opp] = 0.5
        if opp not in self.reputation:
            self.reputation[opp] = 0.5

        # Get opponent's generosity and reputation
        opp_coop = self.cooperation_scores.get(opp, 0.5)
        opp_rep = self.reputation.get(opp, 0.5)

        # My own generosity based on my history
        total_actions = self.my_coop_count + self.my_defect_count
        my_gen = self.my_coop_count / total_actions if total_actions > 0 else 0.5

        # Base strategy: cooperate if opponent is generous or trustworthy enough
        # and adjust based on my own generosity
        threshold = 0.4 + 0.2 * (1 - my_gen)  # more generous when I'm less generous
        if opp_coop > threshold or opp_rep > 0.6:
            self.current_round_coop = True
        else:
            # If opponent seems untrustworthy, occasionally defect to test
            if opp_rep < 0.3 and random.random() < 0.3:
                self.current_round_coop = False
            else:
                self.current_round_coop = True

        # Store opponent for observation update
        self.round_opponent = opp
        return self.current_round_coop

    def observe(
        self,
