                        self.cooperation_scores[self.round_opponent] = max(
                            0.0, self.cooperation_scores.get(self.round_opponent, 0.5) - 0.1
                        )

            if recipient_id == self.agent_id:
                if recipient_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
                if self.round_opponent is not None:
                    self.last_opponent_action = donor_action
                    self.my_last_action = recipient_action
                    self.opponent_interactions.setdefault(self.round_opponent, []).append(
                        (recipient_action, donor_action)
                    )
                    if donor_action == 'cooperate':
                        self.cooperation_scores[self.round_opponent] = min(
                            1.0, self.cooperation_scores.get(self.round_opponent, 0.5) + 0.1
                        )
