                        )

            # Third-party observations: update reputation of both agents
            self.total_observations += 1
            # Update donor's reputation based on their action
            if donor_action == 'cooperate':
                self.reputation[donor_id] = min(
                    1.0, self.reputation.get(donor_id, 0.5) + 0.05
                )
