                )
            else:
                self.reputation[recipient_id] = max(
                    0.0, self.reputation.get(recipient_id, 0.5) - 0.05
                )

            # Occasionally adjust generosity based on overall population trends
            if self.total_observations % 20 == 0:
                # If I'm being too generous, become less generous
                total_actions = self.my_coop_count + self.my_defect_count
                if total_actions > 0:
                    my_coop_rate = self.my_coop_count / total_actions
                    # Adjust toward a target cooperation rate of ~0.7
                    if my_coop_rate > 0.75:
                        self.generosity_adjustment = -0.02
                        self.current_round_coop = False
                    elif my_coop_rate < 0.65:
                        self.generosity_adjustment = 0.02
                        self.current_round_coop = True
                    else:
                        self.generosity_adjustment = 0.0
        except Exception:
            pass

