        self.max_memory = 50
        # Forgiving parameter to smooth out noise
        self.forgiveness = 0.1
        # Minimum observations before trusting reputation
        self.min_obs = 3

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If no opponent, default to cooperate (shouldn't happen but safe)
        if opponent is None:
            return True

        # If we have direct interaction history, use it
        if opponent in self.interactions and len(self.interactions[opponent]) > 0:
            history = self.interactions[opponent]
            # Count how many times opponent cooperated in direct interactions
            opp_coops = sum(1 for _, opp_a in history if opp_a == 'cooperate')
            opp_defects = len(history) - opp_coops
            # If opponent cooperated at least 60% of the time, cooperate
            if len(history) >= 3:
                coop_ratio = opp_coops / len(history)
                if coop_ratio > 0.6:
                    return True
                elif coop_ratio < 0.4:
                    return False
                # Otherwise fall through to reputation

        # Use reputation from observations
        if opponent in self.reputation:
            coops, defs = self.reputation[opponent]
            total = coops + defs
            if total >= self.min_obs:
                coop_ratio = coops / total
                # Add forgiveness to avoid being too harsh
                coop_ratio += self.forgiveness
                if coop_ratio > 0.5:
                    return True
                else:
                    return False

        # If no information, default to cooperate (optimistic start)
        return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents based on their actions
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:  # don't track our own reputation
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = [0, 0]
                if action == 'cooperate':
                    self.reputation[agent_id][0] += 1
                else:
                    self.reputation[agent_id][1] += 1

        # Update recent actions memory for pattern detection
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
