class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation/defection history per opponent
        self.history = {}  # opponent_id -> list of (my_action, their_action)
        # Track observed behavior of all agents
        self.reputation = {}  # agent_id -> {'coop': int, 'defect': int, 'total': int}
        # Track my own recent behavior to detect if I'm being exploited
        self.my_actions = []  # list of my actions over all rounds
        self.generation = 0
        self.round_in_generation = 0
        # Parameters for strategy
        self.coop_threshold = 0.6  # reputation threshold to cooperate with strangers
        self.forgiveness = 0.1  # chance to forgive defections
        self.exploit_threshold = 0.3  # if opponent defects more than this, retaliate
        # Track how many times I've been defected against in a row
        self.consecutive_defections_against_me = 0

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            # Fallback: cooperate if unknown
            return True

        # If I have history with this opponent, use it
        if opponent_id in self.history and len(self.history[opponent_id]) > 0:
            my_history, their_history = zip(*self.history[opponent_id])
            # My recent actions (last 5)
            my_recent = my_history[-5:] if len(my_history) >= 5 else my_history
            their_recent = their_history[-5:] if len(their_history) >= 5 else their_history

            # Count defections in recent history
            my_defects = sum(1 for a in my_recent if a == 'defect')
            their_defects = sum(1 for a in their_recent if a == 'defect')

            # If they've been cooperative recently, cooperate
            if their_defects == 0:
                # But if I've been defecting, maybe continue defecting to avoid exploitation
                if my_defects == 0:
                    return True
                else:
                    # I've been defecting, they've been cooperating - they're forgiving, keep defecting
                    return False
            else:
                # They've defected at least once recently
                defect_rate = their_defects / len(their_recent) if len(their_recent) > 0 else 0
                if defect_rate > self.exploit_threshold:
                    # They're defecting too much - retaliate
                    return False
                else:
                    # They're mostly cooperating, occasional defections - maybe forgive
                    # Use a probabilistic forgiveness based on my recent behavior
                    if my_defects > 0:
                        # I've been defecting, they've been mostly cooperative - continue defecting
                        return False
                    else:
                        # Both mostly cooperative, occasional defections - forgive occasionally
                        return random.random() > self.forgiveness
        else:
            # No history with this opponent, use reputation
            if opponent_id in self.reputation and self.reputation[opponent_id]['total'] > 0:
                coop_ratio = self.reputation[opponent_id]['coop'] / self.reputation[opponent_id]['total']
                # Cooperate if reputation is good enough
                if coop_ratio >= self.coop_threshold:
                    return True
                else:
                    # Bad reputation, defect
                    return False
            else:
                # No info, cooperate initially (tit-for-tat start)
                return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'defect': 0, 'total': 0}
            self.reputation[agent_id]['total'] += 1
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
            else:
                self.reputation[agent_id]['defect'] += 1

        # Update history if I'm involved
        if donor_id == self.agent_id:
            # I'm the donor
            opponent_id = recipient_id
            if opponent_id not in self.history:
                self.history[opponent_id] = []
            self.history[opponent_id].append((donor_action, recipient_action))
            self.my_actions.append(donor_action)
            if donor_action == 'defect':
                self.consecutive_defections_against_me = 0
            else:
                # I cooperated, but they defected - that's being exploited
                if recipient_action == 'defect':
                    self.consecutive_defections_against_me += 1
        elif recipient_id == self.agent_id:
            # I'm the recipient
            opponent_id = donor_id
            if opponent_id not in self.history:
                self.history[opponent_id] = []
            self.history[opponent_id].append((recipient_action, donor_action))
            self.my_actions.append(recipient_action)
            if donor_action == 'defect':
                self.consecutive_defections_against_me += 1
            else:
                self.consecutive_defections_against_me = 0

        # Occasionally adjust thresholds based on overall behavior (simple adaptation)
        # This is done every 10 observations to avoid frequent changes
        if len(self.my_actions) % 10 == 0 and len(self.my_actions) > 0:
            # If I'm being exploited a lot, be more aggressive
            if self.consecutive_defections_against_me >= 3:
                self.exploit_threshold = 0.4
            else:
                self.exploit_threshold = 0.3
            # If I'm cooperating a lot and being taken advantage of, lower forgiveness
            if self.consecutive_defections_against_me >= 2:
                self.forgiveness = 0.05
            else:
                self.forgiveness = 0.1

