        self.my_coop_rate = 0.5  # initial guess
        self.adaptation_rate = 0.05  # how fast to adjust coop_threshold

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            # Fallback: cooperate if unknown
            return True

        # If I have history with this opponent, use it
        if opponent_id in self.history and len(self.history[opponent_id]) > 0:
            my_history, their_history = zip(*self.history[opponent_id])
            # My recent actions (last 5)
            my_recent = my_history[-5:] if len(my_history) >= 5 else my_history
            their_recent = their_history[-5:] if len(their_history) >= 5 else their_history

            # Count defections in recent history
            my_defects = sum(1 for a in my_recent if a == 'defect')
            their_defects = sum(1 for a in their_recent if a == 'defect')

            # If they've been cooperative recently, cooperate
            if their_defects == 0:
                # But if I've been defecting, maybe continue defecting to avoid exploitation
                if my_defects == 0:
                    return True
                else:
                    # I've been defecting, they've been cooperating - they're forgiving, keep defecting
                    return False
            else:
                # They've defected at least once recently
                defect_rate = their_defects / len(their_recent) if len(their_recent) > 0 else 0
                if defect_rate > self.exploit_threshold:
                    # They're defecting too much - retaliate
                    return False
                else:
                    # They're mostly cooperating, occasional defections - maybe forgive
                    # Use a probabilistic forgiveness based on my recent behavior
                    if my_defects > 0:
                        # I've been defecting, they've been mostly cooperative - continue defecting
                        return False
                    else:
                        # Both mostly cooperative, occasional defections - forgive occasionally
                        return random.random() > self.forgiveness
