            # No history with this opponent, use reputation
            if opponent_id in self.reputation and self.reputation[opponent_id]['total'] > 0:
                coop_ratio = self.reputation[opponent_id]['coop'] / self.reputation[opponent_id]['total']
                # Cooperate if reputation is good enough
