        if opp is None:
            return True
        # Use only recent history (last `memory_length` observations)
        history = self.recent_outcomes.get(opp, [])
        if not history:
            return True
        coop_count = sum(history)
        coop_ratio = coop_count / len(history)
        # More aggressive threshold: cooperate only if recent ratio is high
        threshold = 0.7
        if coop_ratio >= threshold:
            return random.random() < 0.9
        else:
            return random.random() < 0.1

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_defect += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_defect += 1
        # Update recent outcomes for relevant agents
        # Only update for direct interactions (donor or recipient is self) and third-party with limited visibility
        # But we'll update for all observed actions, but only keep recent entries
        agents_to_update = []
        if donor_id != self.agent_id:
            agents_to_update.append((donor_id, donor_action == 'cooperate'))
        if recipient_id != self.agent_id and recipient_id != donor_id:
            agents_to_update.append((recipient_id, recipient_action == 'cooperate'))
        for agent_id, is_coop in agents_to_update:
