class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.recent_outcomes = {}  # opponent_id -> deque of bools
        self.own_coop = 0
        self.own_defect = 0
        self.round_num = 0
        self._ctx_opponent_id = None
        self.opponent_histories = {}
        self.memory_length = 5  # longer memory for more stable judgments
        self.recent_own_actions = deque(maxlen=5)
        # Track public reputation: agent_id -> float (0 to 1)
        self.public_reputation = {}
        # Track how much we trust our own observations vs public reputation
        self.trust_public = 0.7  # weight given to public info

    def decide(self) -> bool:
        self.round_num += 1
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        history = self.recent_outcomes.get(opp, deque())
        if not history:
            # No direct history - use public reputation if available
            if opp in self.public_reputation:
                rep = self.public_reputation[opp]
                return random.random() < rep
            return random.random() < 0.8

        coop_count = sum(history)
        coop_ratio = coop_count / len(history)

        # Blend direct observation with public reputation
        if opp in self.public_reputation:
            rep = self.public_reputation[opp]
            blended = self.trust_public * rep + (1 - self.trust_public) * coop_ratio
        else:
            blended = coop_ratio

        # Adaptive threshold based on own recent behavior
        if self.recent_own_actions:
            own_coop_ratio = sum(self.recent_own_actions) / len(self.recent_own_actions)
            base_threshold = 0.5
            adjustment = (own_coop_ratio - 0.5) * 0.3
            threshold = base_threshold + adjustment
        else:
            threshold = 0.5

        # Use a smooth probabilistic response
        diff = blended - threshold
        if diff > 0.3:
            return True
        elif diff < -0.3:
            return False
        else:
            prob = 0.5 + diff * 1.67
            return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own action counts
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id and donor_action == 'cooperate':
                self.own_coop += 1
                self.recent_own_actions.append(True)
            elif donor_id == self.agent_id and donor_action == 'defect':
                self.own_defect += 1
                self.recent_own_actions.append(False)
            if recipient_id == self.agent_id and recipient_action == 'cooperate':
                self.own_coop += 1
                self.recent_own_actions.append(True)
            elif recipient_id == self.agent_id and recipient_action == 'defect':
                self.own_defect += 1
                self.recent_own_actions.append(False)

        # Update public reputation for observed agents (including third-party observations)
        # More weight to direct interactions
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            # Determine if this is a direct interaction (we are donor or recipient)
            is_direct = (donor_id == self.agent_id or recipient_id == self.agent_id)
            coop = action == 'cooperate'
            # Update reputation with a moving average
            if agent_id not in self.public_reputation:
                self.public_reputation[agent_id] = 0.5
            # Direct observations weighted more heavily
            if is_direct:
                weight = 0.3
            else:
                weight = 0.1
            self.public_reputation[agent_id] = (1 - weight) * self.public_reputation[agent_id] + weight * float(coop)

        # Update direct outcome tracking only for our own interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id != self.agent_id:
                other = donor_id
                coop = donor_action == 'cooperate'
            else:
                other = recipient_id
                coop = recipient_action == 'cooperate'
            # Initialize if new
            if other not in self.recent_outcomes:
                self.recent_outcomes[other] = deque(maxlen=self.memory_length)
            self.recent_outcomes[other].append(coop)
            # Also update opponent histories
            if other not in self.opponent_histories:
                self.opponent_histories[other] = deque(maxlen=self.memory_length)
            self.opponent_histories[other].append(coop)

