class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}  # agent_id -> [cooperations, defections] observed
        self.coop_count = 0
        self.defect_count = 0
        self.total_rounds = 0
        self.last_opponent = None
        self.personal_hist = {}  # opponent_id -> list of (my_action, their_action)
        self.forgiveness_threshold = 0.4
        self.trust_threshold = 0.6
        self.explore_rate = 0.05
        self.generation = 0
        self.phase = 0

    def decide(self) -> bool:
        # Simple deterministic strategy with slight exploration
        opp = self._ctx_opponent_id
        self.last_opponent = opp

        # If we have history with this opponent, use it
        if opp in self.personal_hist:
            hist = self.personal_hist[opp]
            # Tit-for-tat with forgiveness
            if len(hist) >= 1:
                last_their_action = hist[-1][1]
                if last_their_action == 'cooperate':
                    return True
                else:
                    # Forgive with some probability based on their overall reputation
                    opp_rep = self.get_reputation(opp)
                    if opp_rep >= self.forgiveness_threshold:
                        return random.random() < 0.8
                    else:
                        return False

        # No history: use reputation
        if opp in self.reputations:
            coop, defect = self.reputations[opp]
            total = coop + defect
            if total > 0:
                trust = coop / total
                if trust >= self.trust_threshold:
                    return True
                elif trust <= 0.3:
                    return False
                else:
                    # Uncertain - cooperate more often early on
                    return random.random() < 0.5 + 0.3 * (1 - self.phase)

        # Default: cooperate initially
        return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for donor and recipient
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.reputations.setdefault(agent_id, [0, 0])[0] += 1
            else:
                self.reputations.setdefault(agent_id, [0, 0])[1] += 1

        # Record personal history if we're involved
        if donor_id == self.agent_id:
            self.coop_count += 1 if donor_action == 'cooperate' else 0
            self.defect_count += 1 if donor_action == 'defect' else 0
            self.personal_hist.setdefault(recipient_id, []).append((donor_action, recipient_action))
        elif recipient_id == self.agent_id:
            self.coop_count += 1 if recipient_action == 'cooperate' else 0
            self.defect_count += 1 if recipient_action == 'defect' else 0
            self.personal_hist.setdefault(donor_id, []).append((recipient_action, donor_action))

        self.total_rounds += 1
        # Update phase based on rounds (30 rounds per generation, 30 generations)
        self.phase = (self.total_rounds // 30) % 30

    def get_reputation(self, agent_id: int) -> float:
        if agent_id in self.reputations:
            coop, defect = self.reputations[agent_id]
            total = coop + defect
            if total > 0:
                return coop / total
        return 0.0

