        self.current_round_coop = True  # default
        self.generosity_adjustment = 0.0
        self.trust_adjustment = 0.0
        self.last_opponent_action = None
        self.my_last_action = None
        self.recent_interactions = {}
        self.initialized = False
        # Exploration: use a longer memory window and a stochastic decision threshold
        self.memory_window = 5
        self.base_threshold = 0.5
        self.threshold_variability = 0.15  # randomness in threshold

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id
        # Initialize cooperation score for new opponents
        if opp not in self.cooperation_scores:
            self.cooperation_scores[opp] = 0.5
        if opp not in self.reputation:
            self.reputation[opp] = 0.5

        # Get opponent's generosity and reputation
        opp_coop = self.cooperation_scores.get(opp, 0.5)
        opp_rep = self.reputation.get(opp, 0.5)

        # My own generosity based on my history
        total_actions = self.my_coop_count + self.my_defect_count
        my_gen = self.my_coop_count / total_actions if total_actions > 0 else 0.5

        # Base strategy: cooperate if opponent is generous or trustworthy enough
        # Exploration: stochastic threshold that varies per decision
        threshold = self.base_threshold + random.uniform(-self.threshold_variability, self.threshold_variability)
        # Adjust threshold based on my own generosity (more generous when I'm less generous)
        threshold += 0.2 * (1 - my_gen)

        # Use longer memory of recent interactions with this opponent
        recent = self.opponent_interactions.get(opp, deque())
        if len(recent) > 0:
            recent_coop = sum(1 for _, their in recent if their == 'cooperate') / len(recent)
            # If recent cooperation is high, lower threshold (more forgiving); if low, raise threshold
            threshold -= 0.1 * recent_coop

        # Decision: cooperate if opponent's generosity or reputation exceeds threshold
        if opp_coop > threshold or opp_rep > 0.7:
            self.current_round_coop = True
        else:
            # When opponent is untrustworthy, sometimes defect but with a probabilistic element
            if opp_rep < 0.4 and random.random() < 0.6:
                self.current_round_coop = False
            else:
                self.current_round_coop = True

        # Store opponent for observation update
        self.round_opponent = opp
        return self.current_round_coop

