        self.generation_num = 0
        self.my_cooperation_count = 0
        self.my_defection_count = 0
        self.total_observations = 0
        self.recent_actions = {}  # agent_id -> deque of last 5 actions
        self.trust_bias = 0.5  # initial bias, updated over time

    def decide(self) -> bool:
        if self.opponent_id is None:
            return True

        opponent_id = self.opponent_id
        coop = self.cooperation_scores.get(opponent_id, 0)
        defect = self.defection_scores.get(opponent_id, 0)
        total = coop + defect

        if total == 0:
            # Use a more optimistic initial stance with randomness
            return random.random() < 0.6

        coop_ratio = coop / total if total > 0 else 0.5

        # Use a dynamic threshold that shifts with trust bias
        coop_threshold = 0.5 + self.trust_bias * 0.2
        defect_threshold = 0.5 - self.trust_bias * 0.2

        if coop_ratio > coop_threshold:
            return True
        elif coop_ratio < defect_threshold:
            return False
        else:
            # Check recent interaction history with this opponent
            recent = self.recent_actions.get(opponent_id, deque())
            if len(recent) > 0:
                # Use majority of recent actions
                coop_count = sum(1 for a in recent if a == 'cooperate')
                if coop_count > len(recent) / 2:
                    return True
                else:
                    return False
            # If no recent, use probabilistic with current trust bias
            return random.random() < self.trust_bias

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        try:
            # Update donor's stats
            if donor_action == 'cooperate':
                self.cooperation_scores[donor_id] = self.cooperation_scores.get(donor_id, 0) + 1
            else:
                self.defection_scores[donor_id] = self.defection_scores.get(donor_id, 0) + 1

            # Update recipient's stats
