        self.recent_interactions = {}
        # Generosity factor - increased to be more forgiving
        self.generosity = 0.15
        # Track opponent defection streak to detect persistent defectors
        self.opponent_defect_streak = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        # If we have no history with this opponent, use reputation
        if opp not in self.history:
            # Use global reputation if available, else cooperate initially
            if opp in self.reputation:
                # Cooperate if reputation is decent, but be more lenient
                return self.reputation[opp] >= -2
            else:
                return True
        # Check for persistent defector - if they've defected 3+ times in a row, defect
        defect_streak = self.opponent_defect_streak.get(opp, 0)
        if defect_streak >= 3:
            return False
        # Use history to decide based on reciprocity
        history = self.history[opp]
        if not history:
            return True
        # Look at last 3 interactions
        recent = history[-3:]
        coop_count = sum(1 for a, b in recent if a)  # our actions
        # If we've been cooperating and they defected, maybe defect
        if coop_count >= 2:
            # Check their last action
            if not recent[-1][1]:
                # With higher generosity, sometimes forgive
                if random.random() < self.generosity:
                    return True
                return False
            else:
                return True
        else:
            # If we've been defecting, maybe cooperate to test
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both participants
        # Simple: cooperate gives +1, defect gives -1 to reputation
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.reputation[agent] = self.reputation.get(agent, 0) + 1
            else:
                self.reputation[agent] = self.reputation.get(agent, 0) - 1

        # Update observed cooperation rates
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            self.observed_total[agent] = self.observed_total.get(agent, 0) + 1
            if action == 'cooperate':
                self.observed_coop[agent] = self.observed_coop.get(agent, 0) + 1

