class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation: dict mapping agent_id to a score
        self.reputation = {}
        # Track cooperation history with each opponent
        self.history = {}
        # Track own cooperation rate
        self.my_coop_count = 0
        self.my_total_count = 0
        # Track observed cooperation rates
        self.observed_coop = {}
        self.observed_total = {}
        # Track recent interactions for pattern detection
        self.recent_interactions = {}
        # Generosity factor
        self.generosity = 0.05

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        # If we have no history with this opponent, use reputation
        if opp not in self.history:
            # Use global reputation if available, else cooperate initially
            if opp in self.reputation:
                # Cooperate if reputation is decent
                return self.reputation[opp] >= -1
            else:
                return True
        # Use history to decide based on reciprocity
        history = self.history[opp]
        if not history:
            return True
        # Look at last 3 interactions
        recent = history[-3:]
        coop_count = sum(1 for a, b in recent if a)  # our actions
        # If we've been cooperating and they defected, maybe defect
        if coop_count >= 2:
            # Check their last action
            if not recent[-1][1]:
                return False
            else:
                return True
        else:
            # If we've been defecting, maybe cooperate to test
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both participants
        # Simple: cooperate gives +1, defect gives -1 to reputation
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.reputation[agent] = self.reputation.get(agent, 0) + 1
            else:
                self.reputation[agent] = self.reputation.get(agent, 0) - 1

        # Update observed cooperation rates
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            self.observed_total[agent] = self.observed_total.get(agent, 0) + 1
            if action == 'cooperate':
                self.observed_coop[agent] = self.observed_coop.get(agent, 0) + 1

        # If this is our own interaction, update our history and counts
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent and our/their actions
            if donor_id == self.agent_id:
                opp = recipient_id
                my_action = donor_action == 'cooperate'
                their_action = recipient_action == 'cooperate'
            else:
                opp = donor_id
                my_action = recipient_action == 'cooperate'
                their_action = donor_action == 'cooperate'

            # Update own counts
            self.my_total_count += 1
            if my_action:
                self.my_coop_count += 1

            # Update history
            if opp not in self.history:
                self.history[opp] = []
            self.history[opp].append((my_action, their_action))
            # Keep last 20 interactions
            if len(self.history[opp]) > 20:
                self.history[opp] = self.history[opp][-20:]

            # Update recent interactions for pattern detection
            if opp not in self.recent_interactions:
                self.recent_interactions[opp] = []
            self.recent_interactions[opp].append((my_action, their_action))
            if len(self.recent_interactions[opp]) > 10:
                self.recent_interactions[opp] = self.recent_interactions[opp][-10:]

