        self.recent_own_actions = deque(maxlen=10)
        self.reputation = {}
        self.betrayal_count = {}
        self.forgiveness = 0.3
        self.tit_for_tat_memory = {}
        self.reputation_decay = 0.02  # Added decay factor for reputation
        self.confidence = {}  # Track confidence in reputation estimates

    def decide(self) -> bool:
