        self.reputation_decay = 0.95

    def decide(self) -> bool:
        if self.opponent_id is None:
            return True

        opponent_id = self.opponent_id

        # Use continuous reputation score
        rep = self.reputation.get(opponent_id, 0.5)

        # If no info, cooperate
        if self.cooperation_scores.get(opponent_id, 0) + self.defection_scores.get(opponent_id, 0) == 0:
            return True

        # Thresholds shifted: cooperate if rep > 0.65, defect if rep < 0.35
        if rep > 0.65:
            return True
        elif rep < 0.35:
            return False
        else:
            # Use last interaction with this opponent from deque
            for interaction in reversed(self.interactions):
                if interaction[0] == opponent_id:
                    return interaction[2] == 'cooperate'
            # Fallback with decreasing cooperation bias
            cooperation_bias = 0.5 + (0.15 * (1 - self.round_num / 30))
            return random.random() < cooperation_bias

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation with decay and weighted updates
        donor_val = 1.0 if donor_action == 'cooperate' else -1.0
        recipient_val = 1.0 if recipient_action == 'cooperate' else -1.0

        # Update donor reputation
        prev_donor = self.reputation.get(donor_id, 0.5)
        new_donor = prev_donor * self.reputation_decay + 0.1 * donor_val
        self.reputation[donor_id] = max(0.0, min(1.0, new_donor))

        # Update recipient reputation
        prev_recipient = self.reputation.get(recipient_id, 0.5)
        new_recipient = prev_recipient * self.reputation_decay + 0.1 * recipient_val
        self.reputation[recipient_id] = max(0.0, min(1.0, new_recipient))

        # Update the same counts as parent
        if donor_action == 'cooperate':
            self.cooperation_scores[donor_id] = self.cooperation_scores.get(donor_id, 0) + 1
        else:
            self.defection_scores[donor_id] = self.defection_scores.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.cooperation_scores[recipient_id] = self.cooperation_scores.get(recipient_id, 0) + 1
        else:
            self.defection_scores[recipient_id] = self.defection_scores.get(recipient_id, 0) + 1

        self.total_observations += 1

        if donor_id == self.agent_id:
            self.interactions.append((recipient_id, donor_action, recipient_action))
            if donor_action == 'cooperate':
                self.my_cooperation_count += 1
            else:
                self.my_defection_count += 1
        elif recipient_id == self.agent_id:
            self.interactions.append((donor_id, recipient_action, donor_action))
            if recipient_action == 'cooperate':
                self.my_cooperation_count += 1
            else:
                self.my_defection_count += 1

        # Simplified round/generation tracking using same constants
        if self.total_observations % 3150 == 0:
            self.generation_num += 1
            self.round_num = 0
        elif self.total_observations % 105 == 0:
            self.round_num += 1

