                self.mood = min(1.0, self.mood + 0.2)
                self.generosity = min(1.0, self.generosity + 0.1)
            else:
                self.mood = max(-1.0, self.mood - 0.4)
                self.generosity = max(0.0, self.generosity - 0.2)
        elif recipient_id == self.agent_id:
            self.my_history.append(recipient_coop)
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = deque(maxlen=10)
            self.opponent_history[donor_id].append(donor_coop)
            # Modified: Mood changes are more reactive
            if donor_coop:
                self.mood = min(1.0, self.mood + 0.2)
                self.generosity = min(1.0, self.generosity + 0.1)
            else:
                self.mood = max(-1.0, self.mood - 0.4)
                self.generosity = max(0.0, self.generosity - 0.2)

        if self.round_count % 10 == 0:
            self.mood *= 0.8  # Slower decay to keep mood more stable

        if self.round_count % 30 == 0:
            self.forgiveness = min(0.9, self.forgiveness + 0.1)

        if self.round_count % 10 == 0:
            for agent_id in self.suspicion:
                self.suspicion[agent_id] *= 0.9  # Slower decay

