class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_count = {}
        self.defect_count = {}
        self.my_coops = 0
        self.my_defects = 0
        self.my_donor_outcomes = []
        self.my_recipient_outcomes = []
        self.agent_coop_rate = {}
        self.recent_interactions = {}
        self.reputation = {}
        self._ctx_opponent_id = None
        self.round_count = 0
        self.betrayal_count = {}
        # New: Track forgiveness level per opponent
        self.forgiveness = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        opp_coops = self.coop_count.get(opponent, 0)
        opp_defects = self.defect_count.get(opponent, 0)
        total = opp_coops + opp_defects
        coop_rate = opp_coops / total if total > 0 else 0.5

        my_total = self.my_coops + self.my_defects
        my_coop_rate = self.my_coops / my_total if my_total > 0 else 0.5

        opp_reputation = self.reputation.get(opponent, 0.5)

        # If we've never interacted, cooperate
        if total == 0:
            return True

        # Retaliation: if opponent has betrayed me a lot, defect
        betrayals = self.betrayal_count.get(opponent, 0)
        if betrayals >= 3:
            return False

        # If opponent has defected recently, defect
        recent = self.recent_interactions.get(opponent, [])
        recent_defects = sum(1 for a in recent if a == 'defect')
        if len(recent) >= 3 and recent_defects / len(recent) > 0.7:
            return False

        # If opponent's coop rate is very low, defect
        if coop_rate < 0.2 and total >= 3:
            return False

        # If opponent's reputation is very bad, defect
        if opp_reputation < 0.1 and total >= 2:
            return False

        # Otherwise, cooperate with probability based on various factors
        # But keep it mostly deterministic for stability
        base = 0.5 + 0.3 * coop_rate + 0.1 * opp_reputation + 0.1 * my_coop_rate
        # Slight forgiveness: if opponent has been good recently, boost cooperation
        if recent and recent[-1] == 'cooperate':
            base += 0.1

        # NEW: Add forgiveness mechanism - if opponent has a high forgiveness score, boost cooperation
        forg = self.forgiveness.get(opponent, 0.5)
        base += 0.05 * (forg - 0.5)

        # Clamp and round to get deterministic-ish behavior
        base = max(0, min(1, base))
        # Use a deterministic threshold based on round number and agent id
        threshold = 0.5 + 0.1 * math.sin(self.round_count * 0.5 + self.agent_id)
        return base > threshold

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update round count if this is my own action
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_count += 1

        # Update stats for donor and recipient
        self._update_agent_stats(donor_id, donor_action)
        self._update_agent_stats(recipient_id, recipient_action)

        # Track my own actions and outcomes
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.my_coops += 1
            else:
                self.my_defects += 1
            self.my_donor_outcomes.append((donor_action, recipient_action))
            if len(self.my_donor_outcomes) > 20:
                self.my_donor_outcomes.pop(0)
            # Track betrayals - when I cooperated and recipient defected
            if donor_action == 'cooperate' and recipient_action == 'defect':
                self.betrayal_count[recipient_id] = self.betrayal_count.get(recipient_id, 0) + 1
                # NEW: Decrease forgiveness when betrayed
                self.forgiveness[recipient_id] = max(0, self.forgiveness.get(recipient_id, 0.5) - 0.1)
            elif donor_action == 'cooperate' and recipient_action == 'cooperate':
                # NEW: Increase forgiveness when mutual cooperation
                self.forgiveness[recipient_id] = min(1, self.forgiveness.get(recipient_id, 0.5) + 0.05)
        elif recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.my_coops += 1
            else:
                self.my_defects += 1
            self.my_recipient_outcomes.append((donor_action, recipient_action))
            if len(self.my_recipient_outcomes) > 20:
                self.my_recipient_outcomes.pop(0)
            # Track betrayals - when donor defected and I cooperated
            if recipient_action == 'cooperate' and donor_action == 'defect':
                self.betrayal_count[donor_id] = self.betrayal_count.get(donor_id, 0) + 1
                # NEW: Decrease forgiveness when betrayed
                self.forgiveness[donor_id] = max(0, self.forgiveness.get(donor_id, 0.5) - 0.1)
            elif recipient_action == 'cooperate' and donor_action == 'cooperate':
                # NEW: Increase forgiveness when mutual cooperation
                self.forgiveness[donor_id] = min(1, self.forgiveness.get(donor_id, 0.5) + 0.05)

        # Track recent interactions with donor and recipient
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation: update reputation
            self._update_reputation(donor_id, donor_action)
            self._update_reputation(recipient_id, recipient_action)
        else:
            # My interaction: track recent behavior of the other party
            other_id = donor_id if recipient_id == self.agent_id else recipient_id
            other_action = donor_action if donor_id == other_id else recipient_action
            recent = self.recent_interactions.setdefault(other_id, [])
            recent.append(other_action)
            if len(recent) > 10:
                recent.pop(0)
            # Also update reputation for the other
            self._update_reputation(other_id, other_action)

    def _update_agent_stats(self, agent_id: int, action: str):
        if action == 'cooperate':
            self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
        else:
            self.defect_count[agent_id] = self.defect_count.get(agent_id, 0) + 1

    def _update_reputation(self, agent_id: int, action: str):
        # Simple moving average reputation
        current = self.reputation.get(agent_id, 0.5)
        if action == 'cooperate':
            new = current * 0.9 + 0.1 * 1.0
        else:
            new = current * 0.9 + 0.1 * 0.0
        self.reputation[agent_id] = new

