        if self.recent_own_actions:
            own_coop_ratio = sum(self.recent_own_actions) / len(self.recent_own_actions)
            base_threshold = 0.55
            adjustment = (own_coop_ratio - 0.5) * 0.2
            threshold = base_threshold + adjustment
        else:
            threshold = 0.55

        # New: volatility-based randomness in decision
        diff = combined - threshold
        if diff > 0.1 + self.volatility:
            return True
        elif diff < -0.1 - self.volatility:
            return random.random() < self.generosity
        else:
            # Adjust probability based on volatility to make decisions more unpredictable
            prob = 0.5 + diff * 2.0
            prob = (1 - self.volatility) * prob + self.volatility * 0.5
