                action_score = 1.0 if action_coop else -1.0
                old_rep = self.reputation.get(agent_id, 0.0)
                count = self.observed_counts.get(agent_id, 0)
                # Modified: Even faster decay for reputation, even more responsive to recent actions
                alpha = 0.4 if count < 10 else 0.2
                new_rep = old_rep * (1 - alpha) + action_score * alpha
                new_rep = max(-1.0, min(1.0, new_rep))
                self.reputation[agent_id] = new_rep
                self.observed_counts[agent_id] = count + 1
                # Modified: Trust updates faster, more volatile
                old_trust = self.trust.get(agent_id, 0.0)
                beta = 0.4 if count < 5 else 0.2
                new_trust = old_trust * (1 - beta) + action_score * beta
                new_trust = max(-1.0, min(1.0, new_trust))
                self.trust[agent_id] = new_trust
                # Modified: Suspicion decays faster, shorter grudges
                old_suspicion = self.suspicion.get(agent_id, 0.0)
                if action_coop:
                    new_suspicion = old_suspicion * 0.7
                else:
                    new_suspicion = old_suspicion + 0.3 * (1 + old_suspicion)
                new_suspicion = max(0.0, min(1.0, new_suspicion))
                self.suspicion[agent_id] = new_suspicion
                # New: Update cooperation streak
                if action_coop:
                    self.cooperation_streak[agent_id] = self.cooperation_streak.get(agent_id, 0) + 1
                else:
                    self.cooperation_streak[agent_id] = 0

        if donor_id == self.agent_id:
            self.my_history.append(donor_coop)
            if recipient_id not in self.opponent_history:
                self.opponent_history[recipient_id] = deque(maxlen=10)
            self.opponent_history[recipient_id].append(recipient_coop)
            # New: Record the last interaction with this opponent
            self.last_interaction[recipient_id] = recipient_action
            # Modified: Mood changes are even more reactive
            if recipient_coop:
                self.mood = min(1.0, self.mood + 0.3)
                self.generosity = min(1.0, self.generosity + 0.15)
            else:
                self.mood = max(-1.0, self.mood - 0.5)
                self.generosity = max(0.0, self.generosity - 0.3)
        elif recipient_id == self.agent_id:
            self.my_history.append(recipient_coop)
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = deque(maxlen=10)
            self.opponent_history[donor_id].append(donor_coop)
            # New: Record the last interaction with this opponent
            self.last_interaction[donor_id] = donor_action
            # Modified: Mood changes are even more reactive
            if donor_coop:
                self.mood = min(1.0, self.mood + 0.3)
                self.generosity = min(1.0, self.generosity + 0.15)
            else:
                self.mood = max(-1.0, self.mood - 0.5)
                self.generosity = max(0.0, self.generosity - 0.3)

        if self.round_count % 10 == 0:
            self.mood *= 0.6  # Faster decay to make mood less stable

        if self.round_count % 30 == 0:
            # Modified: Forgiveness adapts based on our own generosity - if we're generous, we forgive more, if not, less
            self.forgiveness = max(0.1, min(0.5, self.base_forgiveness + (self.generosity - 0.5) * 0.2))

        if self.round_count % 10 == 0:
            for agent_id in self.suspicion:
                self.suspicion[agent_id] *= 0.7  # Faster decay

