        self.partner_rep_history = deque(maxlen=20)
        # New: track long-term reputation trend for opponent to predict future behavior
        self.rep_trend = {i: 0.0 for i in range(15)}  # positive = improving, negative = declining
        self.last_rep = {i: 0.5 for i in range(15)}

    def decide(self) -> bool:
        self.round += 1
        if self.round % 30 == 0:
            self.gen += 1
            self.round = 0
        opp = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.opponent_id = opp
        if opp is None:
            return True
        trust = self.trust.get(opp, 0.5)
        rep = self.reputation.get(opp, 0.5)
        my_rep = self.my_rep
        # Use trust, reputation, and trend to decide
        score = trust * 0.6 + rep * 0.3 + self.rep_trend.get(opp, 0.0) * 0.1
        # If my reputation is low, cooperate more to build it
        if my_rep < 0.3:
            score += 0.2
        # If opponent has low rep, be cautious
        if rep < 0.3:
            score -= 0.2
        # If opponent's reputation is trending down, be more cautious
        if self.rep_trend.get(opp, 0.0) < -0.05:
            score -= 0.1
        # If opponent's reputation is trending up, be more cooperative
        if self.rep_trend.get(opp, 0.0) > 0.05:
            score += 0.1
        # New: adjust based on my recent cooperation rate - if I've been defecting a lot, cooperate more
        if self.recent_my_outcomes:
            my_coop_rate = sum(self.recent_my_outcomes) / len(self.recent_my_outcomes)
            if my_coop_rate < 0.4:
                score += 0.15
        # New: if I've been observed defecting more than cooperating, I should cooperate to repair reputation
        if self.observed_defects > self.observed_coops:
            score += 0.1 * (self.observed_defects - self.observed_coops)
