            self.recent_my_outcomes.append(1 if donor_action == 'cooperate' else 0)

        # Track all observed outcomes to detect general cooperation trends
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            self.recent_outcomes.append(1)
        elif donor_action == 'defect' and recipient_action == 'defect':
            self.recent_outcomes.append(0)
        else:
            self.recent_outcomes.append(0.5)

        # Track how often I am observed cooperating vs defecting (third-party observations)
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.observed_coops += 1
            else:
                self.observed_defects += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.observed_coops += 1
            else:
                self.observed_defects += 1

        # Track partner reputation for adaptive threshold - only for opponents I've interacted with
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'cooperate':
                self.partner_rep_history.append(self.reputation[donor_id])
            else:
                self.partner_rep_history.append(self.reputation[donor_id])
        elif donor_id == self.agent_id:
            self.partner_rep_history.append(self.reputation[recipient_id])
        elif recipient_id == self.agent_id:
            self.partner_rep_history.append(self.reputation[donor_id])

        # Update my own reputation based on my actions
        if donor_id == self.agent_id:
            self.my_rep = self.reputation[self.agent_id]

