        my_rep = self.my_rep
        # Cooperation probability based on trust and reputation
        score = trust * 0.7 + rep * 0.3
        # If my reputation is low, I need to cooperate more to build it
        if my_rep < 0.3:
            score += 0.2
        # If opponent has low rep, be cautious
        if rep < 0.3:
            score -= 0.2
        # New: adjust based on my recent cooperation rate - if I've been defecting a lot, cooperate more
        if self.recent_my_outcomes:
            my_coop_rate = sum(self.recent_my_outcomes) / len(self.recent_my_outcomes)
            if my_coop_rate < 0.4:
                score += 0.15
        # New: if I've been observed defecting more than cooperating, I should cooperate to repair reputation
        if self.observed_defects > self.observed_coops:
            score += 0.1 * (self.observed_defects - self.observed_coops)
        # New: adaptive threshold based on past partner reputation - if partners have been unreliable, be more cautious
        if self.partner_rep_history:
            avg_partner_rep = sum(self.partner_rep_history) / len(self.partner_rep_history)
            if avg_partner_rep < 0.5:
                score -= 0.1
            else:
                score += 0.1
        # New: momentum adjustment - if my reputation is rising, be more confident; if falling, be more cautious
        if self.rep_momentum > 0:
            score += 0.1
        elif self.rep_momentum < 0:
            score -= 0.1
        # Randomness for exploration
        if random.random() < 0.05:
            return random.random() < 0.5
        return score >= 0.5

