        if self.round_count % 30 == 0:
            # Modified: Forgiveness adapts based on our own generosity - if we're generous, we forgive more, if not, less
            self.forgiveness = max(0.1, min(0.5, self.base_forgiveness + (self.generosity - 0.5) * 0.2))

