            if my_coop_rate < 0.4:
                score += 0.15
        # New: if I've been observed defecting more than cooperating, I should cooperate to repair reputation
        if self.observed_defects > self.observed_coops:
            score += 0.1 * (self.observed_defects - self.observed_coops)
        # New: adaptive threshold based on past partner reputation - if partners have been unreliable, be more cautious
