            # I was donor, track recipient's reputation
            self.partner_rep_history.append(self.reputation[recipient_id])
        elif recipient_id == self.agent_id:
            # I was recipient, track donor's reputation
            self.partner_rep_history.append(self.reputation[donor_id])

        # Update my own reputation based on my actions
        if donor_id == self.agent_id:
            old_rep = self.my_rep
            self.my_rep = self.reputation[self.agent_id]
            # New: compute reputation momentum based on change
            self.rep_momentum = self.my_rep - old_rep
        elif recipient_id == self.agent_id:
            # Also update if I'm the recipient? The parent only updates when donor_id == self.agent_id
            # But to be consistent, we'll also update my_rep when I'm recipient
            old_rep = self.my_rep
            self.my_rep = self.reputation[self.agent_id]
            self.rep_momentum = self.my_rep - old_rep

import random
