        self.retaliation = {}
        # New: Track a "reputation_memory" to prioritize recent observations
        self.reputation_memory = {}
        # New: Track a "tit_for_tat_count" to enforce stricter reciprocal behavior
        self.tit_for_tat_count = {}
        # New: Track the last opponent interaction to use a more sophisticated tit-for-tat
        self.last_interaction = {}
        # New: Track a "cooperation_streak" to reward consistent cooperation
        self.cooperation_streak = {}

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        if self.round_count == 0:
            return True

        opp_rep = self.reputation.get(opponent_id, 0.0)
        opp_history = self.opponent_history.get(opponent_id, deque())
        opp_suspicion = self.suspicion.get(opponent_id, 0.0)

        # Modified: Use a weighted average of trust and reputation, but with a dynamic weight based on our own mood
        opp_trust = self.trust.get(opponent_id, 0.0)
        mood_weight = 0.5 + 0.2 * self.mood  # Mood influences how much we rely on trust vs reputation
        combined_score = mood_weight * opp_trust + (1 - mood_weight) * opp_rep

        # If opponent has very low combined score, defect
        if combined_score < -0.2:
            return False

        # If opponent has very high combined score, cooperate
        if combined_score > 0.2:
            return True

        # Direct reciprocity with less forgiveness (lower threshold)
        # But also consider retaliation count and tit-for-tat count
        recent_defections = [not a for a in opp_history if not a]
        if recent_defections:
            total_weight = 0.0
            for i, defected in enumerate(recent_defections):
                if defected:
                    total_weight += (1 - self.forgiveness) ** i
            # Lower threshold: less forgiving, defect more readily
            if total_weight > 0.3:
                # Check retaliation counter: if already retaliating, continue
                if self.retaliation.get(opponent_id, 0) > 0:
                    self.retaliation[opponent_id] -= 1
                    return False
                # Initiate retaliation for more rounds
                if opp_rep > 0.1:
                    return True
                self.retaliation[opponent_id] = 5
                return False

        # Stricter tit-for-tat: defect if opponent defected last time, cooperate only if they cooperated
        if opp_history and not opp_history[-1]:
            return False

        # New: Check if we have a recent interaction with this opponent - if so, use a more sophisticated tit-for-tat
        if opponent_id in self.last_interaction:
            last_opponent_action = self.last_interaction[opponent_id]
            if last_opponent_action == 'defect':
                # If they defected last time, we defect but with a chance to forgive if they have a good streak
                coop_streak = self.cooperation_streak.get(opponent_id, 0)
                if coop_streak >= 3 and random.random() < self.forgiveness:
                    return True
                return False
            else:
                # If they cooperated last time, we cooperate but with a chance to defect if suspicious
                if opp_suspicion > 0.6:
                    return False
                return True

        # Modified: Suspicion threshold lower, defect more often under suspicion
        if opp_suspicion > 0.4:
            return False

        # Modified: Use generosity to make cooperation more likely, but with lower base probability
        base_prob = 0.3 + 0.3 * opp_rep + 0.2 * self.generosity
