class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.observed_counts = {}
        self.my_history = deque(maxlen=30)
        self.opponent_history = {}
        self.round_count = 0
        self.mood = 0.0
        # Exploration: Use a more nuanced forgiveness that adapts based on recent interactions
        self.base_forgiveness = 0.3
        self.forgiveness = self.base_forgiveness
        self.trust = {}
        self.suspicion = {}
        # New: Track a "generosity" parameter that increases with cooperation and decreases with defection
        self.generosity = 0.5
        # New: Track a "retaliation" counter for persistent defectors
        self.retaliation = {}
        # New: Track a "reputation_memory" to prioritize recent observations
        self.reputation_memory = {}
        # New: Track a "tit_for_tat_count" to enforce stricter reciprocal behavior
        self.tit_for_tat_count = {}
        # New: Track the last opponent interaction to use a more sophisticated tit-for-tat
        self.last_interaction = {}
        # New: Track a "cooperation_streak" to reward consistent cooperation
        self.cooperation_streak = {}

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        if self.round_count == 0:
            return True

        opp_rep = self.reputation.get(opponent_id, 0.0)
        opp_history = self.opponent_history.get(opponent_id, deque())
        opp_suspicion = self.suspicion.get(opponent_id, 0.0)

        # Modified: Use a weighted average of trust and reputation, but with a dynamic weight based on our own mood
        opp_trust = self.trust.get(opponent_id, 0.0)
        mood_weight = 0.5 + 0.2 * self.mood  # Mood influences how much we rely on trust vs reputation
        combined_score = mood_weight * opp_trust + (1 - mood_weight) * opp_rep

        # If opponent has very low combined score, defect
        if combined_score < -0.2:
            return False

        # If opponent has very high combined score, cooperate
        if combined_score > 0.2:
            return True

        # Direct reciprocity with less forgiveness (lower threshold)
        # But also consider retaliation count and tit-for-tat count
        recent_defections = [not a for a in opp_history if not a]
        if recent_defections:
            total_weight = 0.0
            for i, defected in enumerate(recent_defections):
                if defected:
                    total_weight += (1 - self.forgiveness) ** i
            # Lower threshold: less forgiving, defect more readily
            if total_weight > 0.3:
                # Check retaliation counter: if already retaliating, continue
                if self.retaliation.get(opponent_id, 0) > 0:
                    self.retaliation[opponent_id] -= 1
                    return False
                # Initiate retaliation for more rounds
                if opp_rep > 0.1:
                    return True
                self.retaliation[opponent_id] = 5
                return False

        # Stricter tit-for-tat: defect if opponent defected last time, cooperate only if they cooperated
        if opp_history and not opp_history[-1]:
            return False

        # New: Check if we have a recent interaction with this opponent - if so, use a more sophisticated tit-for-tat
        if opponent_id in self.last_interaction:
            last_opponent_action = self.last_interaction[opponent_id]
            if last_opponent_action == 'defect':
                # If they defected last time, we defect but with a chance to forgive if they have a good streak
                coop_streak = self.cooperation_streak.get(opponent_id, 0)
                if coop_streak >= 3 and random.random() < self.forgiveness:
                    return True
                return False
            else:
                # If they cooperated last time, we cooperate but with a chance to defect if suspicious
                if opp_suspicion > 0.6:
                    return False
                return True

        # Modified: Suspicion threshold lower, defect more often under suspicion
        if opp_suspicion > 0.4:
            return False

        # Modified: Use generosity to make cooperation more likely, but with lower base probability
        base_prob = 0.3 + 0.3 * opp_rep + 0.2 * self.generosity
        return base_prob >= 0.5

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.round_count += 1

        donor_coop = donor_action == 'cooperate'
        recipient_coop = recipient_action == 'cooperate'

        for agent_id, action_coop in [(donor_id, donor_coop), (recipient_id, recipient_coop)]:
            if agent_id != self.agent_id:
                action_score = 1.0 if action_coop else -1.0
                old_rep = self.reputation.get(agent_id, 0.0)
                count = self.observed_counts.get(agent_id, 0)
                # Modified: Even faster decay for reputation, even more responsive to recent actions
                alpha = 0.4 if count < 10 else 0.2
                new_rep = old_rep * (1 - alpha) + action_score * alpha
                new_rep = max(-1.0, min(1.0, new_rep))
                self.reputation[agent_id] = new_rep
                self.observed_counts[agent_id] = count + 1
                # Modified: Trust updates faster, more volatile
                old_trust = self.trust.get(agent_id, 0.0)
                beta = 0.4 if count < 5 else 0.2
                new_trust = old_trust * (1 - beta) + action_score * beta
                new_trust = max(-1.0, min(1.0, new_trust))
                self.trust[agent_id] = new_trust
                # Modified: Suspicion decays faster, shorter grudges
                old_suspicion = self.suspicion.get(agent_id, 0.0)
                if action_coop:
                    new_suspicion = old_suspicion * 0.7
                else:
                    new_suspicion = old_suspicion + 0.3 * (1 + old_suspicion)
                new_suspicion = max(0.0, min(1.0, new_suspicion))
                self.suspicion[agent_id] = new_suspicion
                # New: Update cooperation streak
                if action_coop:
                    self.cooperation_streak[agent_id] = self.cooperation_streak.get(agent_id, 0) + 1
                else:
                    self.cooperation_streak[agent_id] = 0

        if donor_id == self.agent_id:
            self.my_history.append(donor_coop)
            if recipient_id not in self.opponent_history:
                self.opponent_history[recipient_id] = deque(maxlen=10)
            self.opponent_history[recipient_id].append(recipient_coop)
            # New: Record the last interaction with this opponent
            self.last_interaction[recipient_id] = recipient_action
            # Modified: Mood changes are even more reactive
            if recipient_coop:
                self.mood = min(1.0, self.mood + 0.3)
                self.generosity = min(1.0, self.generosity + 0.15)
            else:
                self.mood = max(-1.0, self.mood - 0.5)
                self.generosity = max(0.0, self.generosity - 0.3)
        elif recipient_id == self.agent_id:
            self.my_history.append(recipient_coop)
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = deque(maxlen=10)
            self.opponent_history[donor_id].append(donor_coop)
            # New: Record the last interaction with this opponent
            self.last_interaction[donor_id] = donor_action
            # Modified: Mood changes are even more reactive
            if donor_coop:
                self.mood = min(1.0, self.mood + 0.3)
                self.generosity = min(1.0, self.generosity + 0.15)
            else:
                self.mood = max(-1.0, self.mood - 0.5)
                self.generosity = max(0.0, self.generosity - 0.3)

        if self.round_count % 10 == 0:
            self.mood *= 0.6  # Faster decay to make mood less stable

        if self.round_count % 30 == 0:
            # Modified: Forgiveness adapts based on our own generosity - if we're generous, we forgive more, if not, less
            self.forgiveness = max(0.1, min(0.5, self.base_forgiveness + (self.generosity - 0.5) * 0.2))

        if self.round_count % 10 == 0:
            for agent_id in self.suspicion:
                self.suspicion[agent_id] *= 0.7  # Faster decay

