        # Reputation scores: agent_id -> (cooperate_count, defect_count)
        self.reputation = {}
        # Track own performance: rounds played, total cooperate, total defect
        self.rounds_played = 0
        self.total_cooperate = 0
        self.total_defect = 0
        # Track recent outcomes for adaptive behavior
        self.recent_actions = deque(maxlen=20)  # list of (opponent_id, my_action, opponent_action)
        # Cooperation threshold: will cooperate if opponent's expected cooperation rate >= this
        self.coop_threshold = 0.5
        # Memory of own last action against each opponent
        self.last_action = {}
        # Exploration factor (small random chance to deviate)
        self.exploration_rate = 0.05
        # Track forgiveness level: how many recent defections forgiven
        self.forgiveness = 0.3
        # Track own recent cooperate count for adaptive forgiveness
        self.own_recent_coop = deque(maxlen=10)

    def decide(self) -> bool:
        # Occasionally explore
        if random.random() < self.exploration_rate:
            return random.random() < 0.5

        opponent = self._ctx_opponent_id
        # Get opponent's reputation stats
        coop, defect = self.reputation.get(opponent, (0, 0))
        total = coop + defect
        if total == 0:
            # Unknown opponent: default to cooperate initially
            expected_coop = 0.5
        else:
            expected_coop = coop / total

        # Adaptive threshold: if we've been exploited a lot, raise threshold
        if self.recent_actions:
            exploit_count = sum(1 for _, my, opp in self.recent_actions if my and not opp)
            if exploit_count >= 2:
                self.coop_threshold = min(0.8, self.coop_threshold + 0.05)
            elif exploit_count == 0:
                self.coop_threshold = max(0.2, self.coop_threshold - 0.02)

        # Forgiveness mechanism: lower threshold for recent cooperators
        if opponent in self.last_action:
            last_opp_action = self.last_action[opponent]
            if last_opp_action == 'cooperate':
                expected_coop = min(1.0, expected_coop + self.forgiveness)

        # Cooperate if opponent's reputation is good enough
        return expected_coop >= self.coop_threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:  # Don't judge ourselves (but still track own actions below)
                coop, defect = self.reputation.get(agent_id, (0, 0))
                if action == 'cooperate':
                    coop += 1
                else:
                    defect += 1
                self.reputation[agent_id] = (coop, defect)

        # Handle self-judgment: track own actions and outcomes
        if donor_id == self.agent_id:
            self.rounds_played += 1
            self.total_cooperate += (donor_action == 'cooperate')
            self.total_defect += (donor_action == 'defect')
