                self.own_recent_coop.append(1)
            else:
                self.own_recent_coop.append(0)

        # Update forgiveness based on own recent cooperation
        if self.own_recent_coop:
            coop_frac = sum(self.own_recent_coop) / len(self.own_recent_coop)
