        # Modified: add a "reputation_volatility" to track how much reputation fluctuates
        self.reputation_volatility = {}  # agent_id -> volatility measure (0-1)
        self.volatility_decay = 0.1
        self.volatility_increase = 0.05
        # Modified: add a "risk_tolerance" parameter that changes based on own streak
        self.risk_tolerance = 0.5  # base risk tolerance
        self.risk_adaptation = 0.1  # how much streak affects risk tolerance

    def decide(self) -> bool:
        self.round_num += 1
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        history = self.recent_outcomes.get(opp, deque())
        if not history:
            base_prob = 0.7 + self.emotional_state * 0.1
            return random.random() < base_prob

        coop_count = sum(history)
        coop_ratio = coop_count / len(history)

        direct_score = coop_ratio
        rep = self.reputation.get(opp, 0.5)
        rep_score = rep
        combined = self.reciprocity_weight * direct_score + (1 - self.reciprocity_weight) * rep_score

        last_action = self.tit_for_tat_memory.get(opp)
        if last_action is not None:
            if last_action == 'cooperate':
                combined += 0.1
            else:
                combined -= 0.1

        betrayals = self.betrayal_count.get(opp, 0)
        if betrayals >= 3:
            combined -= 0.1

        combined += self.emotional_state * self.emotional_impact

        context = self.context_memory.get(opp, deque(maxlen=self.context_window))
        if context:
            context_coop_ratio = sum(context) / len(context)
            if context_coop_ratio > 0.7:
                combined += 0.15
            elif context_coop_ratio < 0.3:
                combined -= 0.15

        conf = self.confidence.get(opp, 0.5)
        social_component = (rep - 0.5) * (conf - 0.3)
        combined += self.social_learning_weight * social_component

        # Modified: volatility-based adjustment - if opponent's reputation is volatile, be more cautious
        volatility = self.reputation_volatility.get(opp, 0.0)
        if volatility > 0.6:
            combined -= 0.15  # reduce cooperation when reputation is unstable

        # Modified: streak-based adjustment with lower threshold and higher boost
        streak_info = self.streak_memory.get(opp)
        if streak_info is not None:
            streak_length, last_is_coop = streak_info
            if last_is_coop and streak_length >= self.streak_threshold:
                # More generous reward for longer streaks, capped
                combined += self.streak_boost * min(streak_length / 4.0, 1.5)
            elif not last_is_coop and streak_length >= self.streak_threshold:
                combined -= self.streak_boost * min(streak_length / 4.0, 1.5)

