            if last_is_coop and streak_length >= self.streak_threshold:
                combined += self.streak_boost * min(streak_length / 5, 1.0)  # reward sustained cooperation
            elif not last_is_coop and streak_length >= self.streak_threshold:
                combined -= self.streak_boost * min(streak_length / 5, 1.0)  # punish sustained defection

        if self.recent_own_actions:
            own_coop_ratio = sum(self.recent_own_actions) / len(self.recent_own_actions)
            base_threshold = 0.55
            adjustment = (own_coop_ratio - 0.5) * 0.2
