import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.recent_outcomes = {}
        self.own_coop = 0
        self.own_defect = 0
        self.round_num = 0
        self._ctx_opponent_id = None
        self.opponent_histories = {}
        self.memory_length = 5
        self.recent_own_actions = deque(maxlen=10)
        self.reputation = {}
        self.betrayal_count = {}
        self.forgiveness = 0.3
        self.tit_for_tat_memory = {}
        self.reputation_decay = 0.02
        self.confidence = {}
        self.generosity = 0.1
        self.reciprocity_weight = 0.5
        self.emotional_state = 0.0
        self.emotional_decay = 0.1
        self.emotional_impact = 0.2
        self.context_memory = {}
        self.context_window = 3
        self.social_learning_weight = 0.3
        self.social_learning_rate = 0.01
        # New: track recent cooperative actions per agent to adjust reciprocity dynamically
        self.reciprocity_history = {}
        self.reciprocity_adapt_rate = 0.05
        self.base_reciprocity = 0.5
        # New: track recent defections to adjust forgiveness threshold
        self.recent_defections = {}
        self.forgiveness_threshold = 2
        # New: track the number of times an agent has been observed acting
        self.observation_count = {}
        # New: track the mean cooperation of each agent over all observations
        self.mean_cooperation = {}
        # New: context window length for this agent
        self.context_window = 3

    def decide(self) -> bool:
        self.round_num += 1
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        history = self.recent_outcomes.get(opp, deque())
        if not history:
            base_prob = 0.7 + self.emotional_state * 0.1
            return random.random() < base_prob

        coop_count = sum(history)
        coop_ratio = coop_count / len(history)

        # Dynamic reciprocity weight based on recent interactions
        dyn_weight = self.base_reciprocity
        if opp in self.reciprocity_history:
            recent = self.reciprocity_history[opp]
            if recent:
                recent_ratio = sum(recent) / len(recent)
                # Increase weight if opponent is cooperative, decrease if not
                dyn_weight += (recent_ratio - 0.5) * self.reciprocity_adapt_rate * 10
                dyn_weight = max(0.0, min(1.0, dyn_weight))

        direct_score = coop_ratio
        rep = self.reputation.get(opp, 0.5)
        rep_score = rep

        combined = dyn_weight * direct_score + (1 - dyn_weight) * rep_score

        last_action = self.tit_for_tat_memory.get(opp)
        if last_action is not None:
            if last_action == 'cooperate':
                combined += 0.1
            else:
                combined -= 0.1

        betrayals = self.betrayal_count.get(opp, 0)
        if betrayals >= 3:
            combined -= 0.1

        # Modified: adjust forgiveness based on recent defections
        recent_defs = self.recent_defections.get(opp, 0)
        if recent_defs >= self.forgiveness_threshold:
            combined -= 0.2
        elif recent_defs == 0:
            combined += 0.05

        combined += self.emotional_state * self.emotional_impact

        context = self.context_memory.get(opp, deque(maxlen=self.context_window))
        if context:
            context_coop_ratio = sum(context) / len(context)
            if context_coop_ratio > 0.7:
                combined += 0.15
            elif context_coop_ratio < 0.3:
                combined -= 0.15

        conf = self.confidence.get(opp, 0.5)
        social_component = (rep - 0.5) * (conf - 0.3)
        combined += self.social_learning_weight * social_component

        if self.recent_own_actions:
            own_coop_ratio = sum(self.recent_own_actions) / len(self.recent_own_actions)
            base_threshold = 0.55
            adjustment = (own_coop_ratio - 0.5) * 0.2
            threshold = base_threshold + adjustment
        else:
            threshold = 0.55

        # New: incorporate uncertainty in reputation if few observations
        if opp in self.observation_count:
            obs_count = self.observation_count[opp]
            if obs_count < 5:
                # Scale down the effect of reputation when uncertain
                combined *= 0.8 + 0.04 * obs_count
                # Also scale down the effect of confidence
                combined -= (1 - conf) * 0.2

        diff = combined - threshold
        if diff > 0.1:
            return True
        elif diff < -0.1:
            return random.random() < self.generosity
        else:
            prob = 0.5 + diff * 2.0
            return random.random() < prob

