                    conf = min(1.0, conf + 0.04)
                else:
                    conf = max(0.0, conf - 0.01)
                self.confidence[obs_id] = conf

                # New: update observation count and mean cooperation
                self.observation_count[obs_id] = self.observation_count.get(obs_id, 0) + 1
                if obs_id not in self.mean_cooperation:
                    self.mean_cooperation[obs_id] = 0.0
                self.mean_cooperation[obs_id] = (self.mean_cooperation[obs_id] * (self.observation_count[obs_id] - 1) + (1.0 if action == 'cooperate' else 0.0)) / self.observation_count[obs_id]

        for obs_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if obs_id != self.agent_id:
                if action == 'cooperate':
