            if agent_id in self.recent_outcomes:
                self.recent_outcomes[agent_id].append(is_coop)
            else:
                self.recent_outcomes[agent_id] = deque([0.5 > 0], maxlen=self.memory_length)
                self.recent_outcomes[agent_id].append(is_coop)

        # Update reciprocity history for observed agents
        for agent_id, is_coop in agents_to_update:
            if agent_id not in self.reciprocity_history:
                self.reciprocity_history[agent_id] = deque(maxlen=5)
            self.reciprocity_history[agent_id].append(is_coop)

        # New: update recent defections tracking
        for agent_id, is_coop in agents_to_update:
            if not is_coop:
                self.recent_defections[agent_id] = self.recent_defections.get(agent_id, 0) + 1
            else:
                # Reset if cooperative action (forgiving)
                if agent_id in self.recent_defections:
                    del self.recent_defections[agent_id]

