import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = {}
        self.personal_history = []
        self.opponent_id = None
        self.round_num = 0
        self.generation = 0
        self.gen_memory = []
        self.tolerance = 0.2
        self.alpha = 0.05
        self.beta = 0.1
        self.gamma = 0.05
        self.delta = 0.1
        self.epsilon = 0.05
        self.trust_bias = 0.5
        self.strategy = "tit_for_tat"
        self.defection_threshold = 0.6

    def decide(self) -> bool:
        self.round_num += 1
        self.opponent_id = getattr(self, '_ctx_opponent_id', None)
        if self.opponent_id is None:
            return True

        # Update strategy based on performance every 5 rounds
        if self.round_num % 5 == 0:
            self._update_strategy()

        # Personal last interaction with this opponent
        last_opp_actions = self.interaction_history.get(self.opponent_id, [])
        if last_opp_actions:
            last_action = last_opp_actions[-1]
        else:
            last_action = None

        # Reputation-based adjustment
        opp_rep = self.reputation.get(self.opponent_id, 0.5)

        # Decide based on current strategy
        if self.strategy == "tit_for_tat":
            if last_action is None:
                return True
            return last_action == 'cooperate'
        elif self.strategy == "generous_tit_for_tat":
            if last_action is None:
                return True
            if last_action == 'defect':
                return random.random() > 0.1
            return True
        elif self.strategy == "forgiving":
            if opp_rep > 0.7:
                return True
            if last_action is None:
                return True
            return last_action == 'cooperate' or random.random() < 0.3
        elif self.strategy == "suspicious":
            if opp_rep < 0.3:
                return False
            if last_action is None:
                return opp_rep > 0.5
            return last_action == 'cooperate'
        elif self.strategy == "pavlov":
            if len(self.personal_history) < 2:
                return True
            last_round = self.personal_history[-1]
            if last_round[0] and last_round[1]:  # both cooperated
                return True
            elif not last_round[0] and not last_round[1]:  # both defected
                return False
            else:
                return True
        else:  # adaptive
            if last_action is None:
                return opp_rep > 0.5
            if last_action == 'cooperate':
                return True
            else:
                return random.random() > self.defection_threshold * (1 - opp_rep)

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputations for both participants
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if pid not in self.reputation:
                self.reputation[pid] = 0.5
            # Update reputation based on action and role
            if action == 'cooperate':
                self.reputation[pid] += self.alpha
            else:
                self.reputation[pid] -= self.beta
            self.reputation[pid] = max(0.0, min(1.0, self.reputation[pid]))

        # Record interactions involving this agent
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            if other_id not in self.interaction_history:
                self.interaction_history[other_id] = []
            self.interaction_history[other_id].append(other_action)
            self.personal_history.append((my_action == 'cooperate', other_action == 'cooperate'))

            # Update trust bias based on outcome
            if my_action == 'cooperate' and other_action == 'cooperate':
                self.trust_bias = min(1.0, self.trust_bias + self.gamma)
            elif my_action == 'defect' and other_action == 'defect':
                self.trust_bias = max(0.0, self.trust_bias - self.gamma)
            elif my_action == 'cooperate' and other_action == 'defect':
                self.trust_bias = max(0.0, self.trust_bias - self.delta)
            elif my_action == 'defect' and other_action == 'cooperate':
                self.trust_bias = min(1.0, self.trust_bias + self.delta)

        # Update generation memory periodically
        self.gen_memory.append((donor_id, donor_action, recipient_id, recipient_action))
        if len(self.gen_memory) > 500:
            self.gen_memory.pop(0)

    def _update_strategy(self):
        if not self.personal_history:
            return
        # Analyze recent performance
        recent = self.personal_history[-10:] if len(self.personal_history) >= 10 else self.personal_history
        coop_count = sum(1 for my, opp in recent if my and opp)
        defect_count = sum(1 for my, opp in recent if not my and not opp)
        mixed_count = len(recent) - coop_count - defect_count

        coop_rate = coop_count / len(recent) if recent else 0.5

        # Switch strategies based on environment
        if coop_rate > 0.8:
            # High cooperation - be more generous
            self.strategy = "generous_tit_for_tat"
        elif coop_rate < 0.3:
            # Low cooperation - be more suspicious
            self.strategy = "suspicious"
        elif mixed_count > len(recent) * 0.5:
            # Lots of mixed interactions - use pavlov
            self.strategy = "pavlov"
        else:
            # Default to adaptive
            self.strategy = "adaptive"

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {i: 0.0 for i in range(15)}
        self.round = 0
        self.generation = 0
        self.my_history = {}
        self.opponent_history = {}
        self.trust = {i: 0.0 for i in range(15)}
        self.witnessed = {}
        self.coop_count = 0
        self.total_interactions = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        # If no data, cooperate initially
        if opp not in self.opponent_history:
            return True

        # Calculate trust based on opponent's behavior
        hist = self.opponent_history.get(opp, [])
        if not hist:
            return True

        coop_rate = sum(1 for a in hist if a == 'cooperate') / len(hist)

        # Reputation from third-party observations
        rep = self.reputation.get(opp, 0.0)

        # Combine signals: trust = 0.4*coop_rate + 0.6*normalized reputation
        normalized_rep = max(-1, min(1, rep)) 
        trust = 0.4 * coop_rate + 0.6 * (normalized_rep + 1) / 2

        # Adaptive threshold based on round
        threshold = 0.5
        if self.round < 10:
            threshold = 0.3  # More forgiving early
        elif self.round < 20:
            threshold = 0.5
        else:
            threshold = 0.7  # Stricter late

        # Slight randomness to avoid predictability
        if random.random() < 0.05:
            return True

        return trust >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round/generation counters if needed (framework does this, but we track roughly)
        if donor_id == -1:  # Sentinel for new round (if any)
            self.round = (self.round + 1) % 30
            if self.round == 0:
                self.generation += 1
            self.my_history = {}
            self.opponent_history = {}
            return

        # Update own history if involved
        if donor_id == self.agent_id:
            self.my_history[recipient_id] = donor_action
            self.total_interactions += 1
            if donor_action == 'cooperate':
                self.coop_count += 1
        if recipient_id == self.agent_id:
            self.my_history[donor_id] = recipient_action
            self.total_interactions += 1
            if recipient_action == 'cooperate':
                self.coop_count += 1

        # Update opponent history if we were involved
        if donor_id == self.agent_id:
            self.opponent_history.setdefault(recipient_id, []).append(recipient_action)
        if recipient_id == self.agent_id:
            self.opponent_history.setdefault(donor_id, []).append(donor_action)

        # Third-party observations: update reputation for donor and recipient
        # Reputation updates based on actions
        # Cooperation increases reputation, defection decreases
        if donor_id != self.agent_id:
            # Donor's action reflects on donor
            delta = 1.0 if donor_action == 'cooperate' else -1.0
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 0.1 * delta
        if recipient_id != self.agent_id:
            # Recipient's action reflects on recipient
            delta = 1.0 if recipient_action == 'cooperate' else -1.0
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 0.1 * delta

        # Also consider mutual cooperation/defection as stronger signal
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.reputation[donor_id] += 0.05
                self.reputation[recipient_id] += 0.05
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.reputation[donor_id] -= 0.05
                self.reputation[recipient_id] -= 0.05
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                # Donor defected against cooperator: heavy penalty
                self.reputation[donor_id] -= 0.15
                self.reputation[recipient_id] += 0.05
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.reputation[donor_id] += 0.05
                self.reputation[recipient_id] -= 0.15

        # Clamp reputation to [-2, 2] to avoid extremes
        for key in list(self.reputation.keys()):
            if self.reputation[key] > 2.0:
                self.reputation[key] = 2.0
            elif self.reputation[key] < -2.0:
                self.reputation[key] = -2.0

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.recent_outcomes = {}
        self.own_coop = 0
        self.own_defect = 0
        self.round_num = 0
        self._ctx_opponent_id = None
        self.opponent_histories = {}
        self.memory_length = 5
        self.recent_own_actions = deque(maxlen=10)
        self.reputation = {}
        self.betrayal_count = {}
        self.forgiveness = 0.3
        self.tit_for_tat_memory = {}
        self.reputation_decay = 0.02
        self.confidence = {}
        self.generosity = 0.1
        self.reciprocity_weight = 0.5
        self.emotional_state = 0.0
        self.emotional_decay = 0.1
        self.emotional_impact = 0.2
        self.context_memory = {}
        self.context_window = 3
        self.social_learning_weight = 0.3
        self.social_learning_rate = 0.01
        # New: track recent cooperative actions per agent to adjust reciprocity dynamically
        self.reciprocity_history = {}
        self.reciprocity_adapt_rate = 0.05
        self.base_reciprocity = 0.5
        # New: track recent defections to adjust forgiveness threshold
        self.recent_defections = {}
        self.forgiveness_threshold = 2
        # New: track the number of times an agent has been observed acting
        self.observation_count = {}
        # New: track the mean cooperation of each agent over all observations
        self.mean_cooperation = {}
        # New: context window length for this agent
        self.context_window = 3

    def decide(self) -> bool:
        self.round_num += 1
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        history = self.recent_outcomes.get(opp, deque())
        if not history:
            base_prob = 0.7 + self.emotional_state * 0.1
            return random.random() < base_prob

        coop_count = sum(history)
        coop_ratio = coop_count / len(history)

        # Dynamic reciprocity weight based on recent interactions
        dyn_weight = self.base_reciprocity
        if opp in self.reciprocity_history:
            recent = self.reciprocity_history[opp]
            if recent:
                recent_ratio = sum(recent) / len(recent)
                # Increase weight if opponent is cooperative, decrease if not
                dyn_weight += (recent_ratio - 0.5) * self.reciprocity_adapt_rate * 10
                dyn_weight = max(0.0, min(1.0, dyn_weight))

        direct_score = coop_ratio
        rep = self.reputation.get(opp, 0.5)
        rep_score = rep

        combined = dyn_weight * direct_score + (1 - dyn_weight) * rep_score

        last_action = self.tit_for_tat_memory.get(opp)
        if last_action is not None:
            if last_action == 'cooperate':
                combined += 0.1
            else:
                combined -= 0.1

        betrayals = self.betrayal_count.get(opp, 0)
        if betrayals >= 3:
            combined -= 0.1

        # Modified: adjust forgiveness based on recent defections
        recent_defs = self.recent_defections.get(opp, 0)
        if recent_defs >= self.forgiveness_threshold:
            combined -= 0.2
        elif recent_defs == 0:
            combined += 0.05

        combined += self.emotional_state * self.emotional_impact

        context = self.context_memory.get(opp, deque(maxlen=self.context_window))
        if context:
            context_coop_ratio = sum(context) / len(context)
            if context_coop_ratio > 0.7:
                combined += 0.15
            elif context_coop_ratio < 0.3:
                combined -= 0.15

        conf = self.confidence.get(opp, 0.5)
        social_component = (rep - 0.5) * (conf - 0.3)
        combined += self.social_learning_weight * social_component

        if self.recent_own_actions:
            own_coop_ratio = sum(self.recent_own_actions) / len(self.recent_own_actions)
            base_threshold = 0.55
            adjustment = (own_coop_ratio - 0.5) * 0.2
            threshold = base_threshold + adjustment
        else:
            threshold = 0.55

        # New: incorporate uncertainty in reputation if few observations
        if opp in self.observation_count:
            obs_count = self.observation_count[opp]
            if obs_count < 5:
                # Scale down the effect of reputation when uncertain
                combined *= 0.8 + 0.04 * obs_count
                # Also scale down the effect of confidence
                combined -= (1 - conf) * 0.2

        diff = combined - threshold
        if diff > 0.1:
            return True
        elif diff < -0.1:
            return random.random() < self.generosity
        else:
            prob = 0.5 + diff * 2.0
            return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            expected = self.reputation.get(donor_id, 0.5)
            actual = 1.0 if donor_action == 'cooperate' else 0.0
            error = abs(expected - actual)
            self.social_learning_weight = max(0.1, min(0.5, self.social_learning_weight + self.social_learning_rate * (0.5 - error)))

        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.own_coop += 1
                self.recent_own_actions.append(True)
                self.emotional_state = min(1.0, self.emotional_state + 0.1)
            else:
                self.own_defect += 1
                self.recent_own_actions.append(False)
                self.emotional_state = max(-1.0, self.emotional_state - 0.1)
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.own_coop += 1
                self.recent_own_actions.append(True)
                self.emotional_state = min(1.0, self.emotional_state + 0.1)
            else:
                self.own_defect += 1
                self.recent_own_actions.append(False)
                self.emotional_state = max(-1.0, self.emotional_state - 0.1)

        self.emotional_state *= (1 - self.emotional_decay)

        if donor_id != self.agent_id:
            self.tit_for_tat_memory[donor_id] = donor_action
        if recipient_id != self.agent_id and recipient_id != donor_id:
            self.tit_for_tat_memory[recipient_id] = recipient_action

        for obs_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if obs_id != self.agent_id:
                current = self.reputation.get(obs_id, 0.5)
                current += (0.5 - current) * self.reputation_decay
                if action == 'cooperate':
                    new_rep = current + 0.05 * (1 - current)
                else:
                    new_rep = current - 0.05 * current
                    self.betrayal_count[obs_id] = self.betrayal_count.get(obs_id, 0) + 1
                self.reputation[obs_id] = max(0.0, min(1.0, new_rep))

                conf = self.confidence.get(obs_id, 0.5)
                if (action == 'cooperate' and current > 0.5) or (action == 'defect' and current < 0.5):
                    conf = min(1.0, conf + 0.04)
                else:
                    conf = max(0.0, conf - 0.01)
                self.confidence[obs_id] = conf

                # New: update observation count and mean cooperation
                self.observation_count[obs_id] = self.observation_count.get(obs_id, 0) + 1
                if obs_id not in self.mean_cooperation:
                    self.mean_cooperation[obs_id] = 0.0
                self.mean_cooperation[obs_id] = (self.mean_cooperation[obs_id] * (self.observation_count[obs_id] - 1) + (1.0 if action == 'cooperate' else 0.0)) / self.observation_count[obs_id]

        for obs_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if obs_id != self.agent_id:
                if action == 'cooperate':
                    self.emotional_state = min(1.0, self.emotional_state + 0.05)
                else:
                    self.emotional_state = max(-1.0, self.emotional_state - 0.05)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = donor_id if donor_id != self.agent_id else recipient_id
            other_action = donor_action if donor_id != self.agent_id else recipient_action
            if other_id != self.agent_id:
                if other_id not in self.context_memory:
                    self.context_memory[other_id] = deque(maxlen=self.context_window)
                self.context_memory[other_id].append(other_action == 'cooperate')

        agents_to_update = []
        if donor_id != self.agent_id:
            agents_to_update.append((donor_id, donor_action == 'cooperate'))
        if recipient_id != self.agent_id and recipient_id != donor_id:
            agents_to_update.append((recipient_id, recipient_action == 'cooperate'))

        for agent_id, is_coop in agents_to_update:
            if agent_id not in self.recent_outcomes:
                if len(self.recent_outcomes) < 5 or agent_id in self.opponent_histories:
                    self.recent_outcomes[agent_id] = deque(maxlen=self.memory_length)
                else:
                    continue
            if agent_id in self.recent_outcomes:
                self.recent_outcomes[agent_id].append(is_coop)
            else:
                self.recent_outcomes[agent_id] = deque([0.5 > 0], maxlen=self.memory_length)
                self.recent_outcomes[agent_id].append(is_coop)

        # Update reciprocity history for observed agents
        for agent_id, is_coop in agents_to_update:
            if agent_id not in self.reciprocity_history:
                self.reciprocity_history[agent_id] = deque(maxlen=5)
            self.reciprocity_history[agent_id].append(is_coop)

        # New: update recent defections tracking
        for agent_id, is_coop in agents_to_update:
            if not is_coop:
                self.recent_defections[agent_id] = self.recent_defections.get(agent_id, 0) + 1
            else:
                # Reset if cooperative action (forgiving)
                if agent_id in self.recent_defections:
                    del self.recent_defections[agent_id]

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        # New: reputation is more heavily weighted, and we use a decay factor
        self.rep_weight = 0.8  # increased from 0.6
        self.trust_weight = 0.2  # decreased from 0.4
        self.rep_decay = 0.98  # reputation decays slightly over time
        self.observation_trust_update = 0.03  # stronger trust updates from observations
        self.defect_penalty_obs = 0.08  # stronger penalty for observed defection

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        # More weight on reputation, less on direct trust
        combined = self.rep_weight * opp_rep + self.trust_weight * trust

        if opponent in self.interactions:
            recent = self.interactions[opponent][-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                # Still use direct experience but with slightly lower weight
                combined = 0.2 * combined + 0.8 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = self.interactions[opponent][-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation

        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)

        # New: Decay all reputations slightly each observation to forget stale info
        for agent in list(self.reputation.keys()):
            self.reputation[agent] = self.reputation[agent] * self.rep_decay

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = []
        self.interactions[opp_id].append((my_action, opp_action))

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        self.total_interactions += 1

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        # Stronger trust updates from observations
        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - self.defect_penalty_obs)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + self.observation_trust_update)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - self.defect_penalty_obs)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + self.observation_trust_update)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.partner_reputation:
            self.partner_reputation[recipient_id] = {'coop': 0, 'defect': 0}

        if donor_action == 'cooperate':
            self.partner_reputation[donor_id]['coop'] += 1
        else:
            self.partner_reputation[donor_id]['defect'] += 1

        if recipient_action == 'cooperate':
            self.partner_reputation[recipient_id]['coop'] += 1
        else:
            self.partner_reputation[recipient_id]['defect'] += 1

        if donor_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1
        if recipient_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> reputation score
        self.interactions = {}  # agent_id -> deque of outcomes (my_action, opp_action)
        self.my_scores = []  # scores from my own interactions
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}  # opponent_id -> list of my actions vs them
        self.trust = {}  # agent_id -> trust value
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10  # how many recent interactions to consider
        self.streak = {}  # agent_id -> current streak of cooperative/defective actions
        self.streak_bonus = 0.15  # bonus for high cooperation streaks
        self.streak_threshold = 3  # streak length to trigger bonus
        # New mechanism: uncertainty tracking for each opponent
        self.uncertainty = {}  # agent_id -> uncertainty score (0-1)
        self.uncertainty_decay = 0.9  # decay factor for uncertainty over time
        self.uncertainty_boost = 0.1  # boost when observing inconsistent behavior
        self.uncertainty_threshold = 0.6  # threshold for cautious behavior

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        # If we have no info, cooperate initially
        if opponent is None:
            return True

        # Get opponent's reputation
        opp_rep = self.reputation.get(opponent, 0.5)

