        # If we are highly uncertain about this opponent, be more cautious (tilt toward defection)
        uncertainty = self.uncertainty.get(opponent, 0.0)
        if uncertainty > self.uncertainty_threshold:
            combined -= 0.1 * uncertainty  # subtract proportional to uncertainty

