import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {i: 0.0 for i in range(15)}
        self.round = 0
        self.generation = 0
        self.my_history = {}
        self.opponent_history = {}
        self.trust = {i: 0.0 for i in range(15)}
        self.witnessed = {}
        self.coop_count = 0
        self.total_interactions = 0
        # New: Track recent cooperation events per agent (deque of booleans)
        self.recent_coop = {i: deque(maxlen=10) for i in range(15)}
        # New: Confidence in reputation based on number of observations
        self.obs_count = {i: 0 for i in range(15)}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp not in self.opponent_history:
            # If no direct history, use reputation with uncertainty
            rep = self.reputation.get(opp, 0.0)
            obs = self.obs_count.get(opp, 0)
            if obs < 5:
                return True  # Default cooperate when uncertain
            normalized_rep = max(-1, min(1, rep))
            trust = (normalized_rep + 1) / 2
            threshold = 0.5
            return trust >= threshold

        # Direct history-based trust
        hist = self.opponent_history[opp]
        coop_rate = sum(1 for a in hist if a == 'cooperate') / len(hist)

        # Reputation with confidence weighting
        rep = self.reputation.get(opp, 0.0)
        obs = self.obs_count.get(opp, 0)
        rep_weight = min(1.0, obs / 20)  # Confidence increases with observations
        normalized_rep = max(-1, min(1, rep))
        rep_signal = (normalized_rep + 1) / 2
        trust = (1 - rep_weight) * coop_rate + rep_weight * rep_signal

        # Recent behavior emphasis: use deque average
        recent = self.recent_coop.get(opp, deque(maxlen=10))
        if recent:
            recent_avg = sum(recent) / len(recent)
            trust = 0.7 * trust + 0.3 * recent_avg

        # Adaptive threshold
        threshold = 0.5
        if self.round < 10:
            threshold = 0.4
        elif self.round < 20:
            threshold = 0.6
        else:
            threshold = 0.7

        # Slight randomness
        if random.random() < 0.03:
            return True

        return trust >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == -1:
            self.round = (self.round + 1) % 30
            if self.round == 0:
                self.generation += 1
            self.my_history = {}
            self.opponent_history = {}
            return

