            self.opponent_history.setdefault(donor_id, []).append(donor_action)
            self.recent_coop[donor_id].append(donor_action == 'cooperate')

        # Third-party observations with decay and confidence
        decay = 0.95  # Reputation decays over time to forget old behavior
        if donor_id != self.agent_id:
            self.obs_count[donor_id] += 1
            delta = 1.0 if donor_action == 'cooperate' else -1.0
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) * decay + 0.1 * delta
        if recipient_id != self.agent_id:
            self.obs_count[recipient_id] += 1
            delta = 1.0 if recipient_action == 'cooperate' else -1.0
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) * decay + 0.1 * delta

        # Mutual action special cases
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.reputation[donor_id] += 0.05
                self.reputation[recipient_id] += 0.05
