import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {i: 0.0 for i in range(15)}
        self.round = 0
        self.generation = 0
        self.my_history = {}
        self.opponent_history = {}
        self.trust = {i: 0.0 for i in range(15)}
        self.witnessed = {}
        self.coop_count = 0
        self.total_interactions = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        # If no data, cooperate initially
        if opp not in self.opponent_history:
            return True

        # Calculate trust based on opponent's behavior
        hist = self.opponent_history.get(opp, [])
        if not hist:
            return True

        coop_rate = sum(1 for a in hist if a == 'cooperate') / len(hist)

        # Reputation from third-party observations
        rep = self.reputation.get(opp, 0.0)

        # Combine signals: trust = 0.4*coop_rate + 0.6*normalized reputation
        normalized_rep = max(-1, min(1, rep)) 
        trust = 0.4 * coop_rate + 0.6 * (normalized_rep + 1) / 2

        # Adaptive threshold based on round
        threshold = 0.5
        if self.round < 10:
            threshold = 0.3  # More forgiving early
        elif self.round < 20:
            threshold = 0.5
        else:
            threshold = 0.7  # Stricter late

        # Slight randomness to avoid predictability
        if random.random() < 0.05:
            return True

        return trust >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round/generation counters if needed (framework does this, but we track roughly)
        if donor_id == -1:  # Sentinel for new round (if any)
            self.round = (self.round + 1) % 30
            if self.round == 0:
                self.generation += 1
            self.my_history = {}
            self.opponent_history = {}
            return

        # Update own history if involved
        if donor_id == self.agent_id:
            self.my_history[recipient_id] = donor_action
            self.total_interactions += 1
            if donor_action == 'cooperate':
                self.coop_count += 1
        if recipient_id == self.agent_id:
            self.my_history[donor_id] = recipient_action
            self.total_interactions += 1
            if recipient_action == 'cooperate':
                self.coop_count += 1

        # Update opponent history if we were involved
        if donor_id == self.agent_id:
            self.opponent_history.setdefault(recipient_id, []).append(recipient_action)
        if recipient_id == self.agent_id:
            self.opponent_history.setdefault(donor_id, []).append(donor_action)

        # Third-party observations: update reputation for donor and recipient
        # Reputation updates based on actions
        # Cooperation increases reputation, defection decreases
        if donor_id != self.agent_id:
            # Donor's action reflects on donor
            delta = 1.0 if donor_action == 'cooperate' else -1.0
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 0.1 * delta
        if recipient_id != self.agent_id:
            # Recipient's action reflects on recipient
            delta = 1.0 if recipient_action == 'cooperate' else -1.0
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 0.1 * delta

        # Also consider mutual cooperation/defection as stronger signal
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.reputation[donor_id] += 0.05
                self.reputation[recipient_id] += 0.05
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.reputation[donor_id] -= 0.05
                self.reputation[recipient_id] -= 0.05
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                # Donor defected against cooperator: heavy penalty
                self.reputation[donor_id] -= 0.15
                self.reputation[recipient_id] += 0.05
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.reputation[donor_id] += 0.05
                self.reputation[recipient_id] -= 0.15

        # Clamp reputation to [-2, 2] to avoid extremes
        for key in list(self.reputation.keys()):
            if self.reputation[key] > 2.0:
                self.reputation[key] = 2.0
            elif self.reputation[key] < -2.0:
                self.reputation[key] = -2.0

