        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        # Exploration: Use a weighted average of reputation and trust,
        # but with a "reputation momentum" term that makes the agent
        # more cautious when reputation is uncertain (few observations)
        self.rep_weight = 0.7
        self.trust_weight = 0.3
        self.rep_decay = 0.98
        self.observation_trust_update = 0.03
        self.defect_penalty_obs = 0.08
        self.observation_count = {}  # track how many times we've seen each agent
        self.momentum_factor = 0.1  # how much momentum affects decision

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        combined = self.rep_weight * opp_rep + self.trust_weight * trust

        # Add momentum: if we have few observations, lean toward recent trend
        obs = self.observation_count.get(opponent, 0)
        if obs > 0:
            recent_actions = [a for a, b in self.interactions.get(opponent, [])[-5:]]
            if recent_actions:
                recent_coop_rate = sum(1 for a in recent_actions if a == 'cooperate') / len(recent_actions)
                momentum = (recent_coop_rate - 0.5) * self.momentum_factor
                combined += momentum

        if opponent in self.interactions:
            recent = self.interactions[opponent][-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = self.interactions[opponent][-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation

        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # Additional caution: if reputation is very low and trust is low, defect more often
        if opp_rep < 0.3 and trust < 0.3:
            combined -= 0.1

        return combined > threshold

