from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {i: 0.0 for i in range(15)}
        self.round = 0
        self.generation = 0
        self.my_history = {}
        self.opponent_history = {}
        self.trust = {i: 0.0 for i in range(15)}
        self.witnessed = {}
        self.coop_count = 0
        self.total_interactions = 0
        # New: track recent actions with a deque (maxlen=5) for each opponent
        self.recent_actions = {i: deque(maxlen=5) for i in range(15)}
        # New: track a "momentum" factor that influences decision volatility
        self.momentum = 0.0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        # If no data, cooperate initially
        if opp not in self.opponent_history:
            return True

        # Calculate trust based on opponent's behavior
        hist = self.opponent_history.get(opp, [])
        if not hist:
            return True

        coop_rate = sum(1 for a in hist if a == 'cooperate') / len(hist)

        # Reputation from third-party observations
        rep = self.reputation.get(opp, 0.0)

        # Combine signals: trust = 0.4*coop_rate + 0.6*normalized reputation
        normalized_rep = max(-1, min(1, rep))
        trust = 0.4 * coop_rate + 0.6 * (normalized_rep + 1) / 2

        # New: incorporate recent actions (more weight to recent behavior)
        recent = self.recent_actions.get(opp, deque())
        if len(recent) > 0:
            recent_coop = sum(1 for a in recent if a == 'cooperate') / len(recent)
            trust = 0.7 * trust + 0.3 * recent_coop

        # Adaptive threshold based on round and momentum
        threshold = 0.5
        if self.round < 10:
            threshold = 0.3  # More forgiving early
        elif self.round < 20:
            threshold = 0.5
        else:
            threshold = 0.7  # Stricter late

        # New: adjust threshold based on momentum (if we've been cooperating a lot, be more cautious)
        threshold += self.momentum * 0.2
        threshold = max(0.0, min(1.0, threshold))

        # Slight randomness to avoid predictability, but reduced when momentum is high
        if random.random() < 0.05 * (1 - self.momentum):
            return True

        return trust >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round/generation counters if needed (framework does this, but we track roughly)
        if donor_id == -1:  # Sentinel for new round (if any)
            self.round = (self.round + 1) % 30
            if self.round == 0:
                self.generation += 1
            self.my_history = {}
            self.opponent_history = {}
            # Reset recent actions each round? Keep them but could decay
            # Keep momentum but dampen it
            self.momentum *= 0.9
            return

        # Update own history if involved
        if donor_id == self.agent_id:
            self.my_history[recipient_id] = donor_action
            self.total_interactions += 1
            if donor_action == 'cooperate':
                self.coop_count += 1
            # Update recent actions for opponent
            self.recent_actions[recipient_id].append(recipient_action)
            # Update momentum: cooperate increases positive momentum, defect decreases
            if donor_action == 'cooperate':
                self.momentum = min(1.0, self.momentum + 0.1)
            else:
                self.momentum = max(-1.0, self.momentum - 0.1)
        if recipient_id == self.agent_id:
            self.my_history[donor_id] = recipient_action
            self.total_interactions += 1
            if recipient_action == 'cooperate':
                self.coop_count += 1
            self.recent_actions[donor_id].append(donor_action)
            # Update momentum based on opponent's action? Or own? Own action is the one we chose.
            # Let's base momentum on our own actions (donor_action if we are recipient? Actually we are recipient here)
            # We can use the recipient_action but that's what we did? No, recipient_action is our action in this observation.
            # Let's not update momentum here to avoid double counting; only donor_id == self.agent_id updates.
            # Actually, when we are recipient, we did the recipient_action. But we already update in donor case.
            # To avoid complexity, we skip momentum update for recipient role.

        # Update opponent history if we were involved
        if donor_id == self.agent_id:
            self.opponent_history.setdefault(recipient_id, []).append(recipient_action)
        if recipient_id == self.agent_id:
            self.opponent_history.setdefault(donor_id, []).append(donor_action)

        # Third-party observations: update reputation for donor and recipient
        # Reputation updates based on actions
        # Cooperation increases reputation, defection decreases
        if donor_id != self.agent_id:
            # Donor's action reflects on donor
            delta = 1.0 if donor_action == 'cooperate' else -1.0
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 0.1 * delta
        if recipient_id != self.agent_id:
            # Recipient's action reflects on recipient
            delta = 1.0 if recipient_action == 'cooperate' else -1.0
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 0.1 * delta

        # Also consider mutual cooperation/defection as stronger signal
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.reputation[donor_id] += 0.05
                self.reputation[recipient_id] += 0.05
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.reputation[donor_id] -= 0.05
                self.reputation[recipient_id] -= 0.05
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                # Donor defected against cooperator: heavy penalty
                self.reputation[donor_id] -= 0.15
                self.reputation[recipient_id] += 0.05
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.reputation[donor_id] += 0.05
                self.reputation[recipient_id] -= 0.15

        # Clamp reputation to [-2, 2] to avoid extremes
        for key in list(self.reputation.keys()):
            if self.reputation[key] > 2.0:
                self.reputation[key] = 2.0
            elif self.reputation[key] < -2.0:
                self.reputation[key] = -2.0

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        # Exploration: Replace the static weighted average with a dynamic
        # weight that shifts based on the volatility of the opponent's recent
        # actions.  Also use a sliding window (deque) for recent actions
        # to better capture short-term trends.
        self.base_rep_weight = 0.7
        self.volatility_scale = 0.25  # how much volatility shifts the weight
        self.rep_decay = 0.98
        self.observation_trust_update = 0.03
        self.defect_penalty_obs = 0.08
        self.observation_count = {}
        self.recent_actions = {}  # agent_id -> deque of recent actions
        self.recent_window = 10  # window size for volatility and recent trend

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        # Compute volatility from recent actions
        recent = self.recent_actions.get(opponent, deque())
        if len(recent) > 1:
            # Volatility = standard deviation of binary actions (cooperate=1, defect=0)
            actions = [1 if a == 'cooperate' else 0 for a in recent]
            mean = sum(actions) / len(actions)
            variance = sum((a - mean) ** 2 for a in actions) / len(actions)
            volatility = math.sqrt(variance)
        else:
            volatility = 0.5  # default when not enough data

        # Dynamic weight: more weight to trust when volatility is high
        rep_weight = self.base_rep_weight - self.volatility_scale * volatility
        rep_weight = max(0.0, min(1.0, rep_weight))
        trust_weight = 1.0 - rep_weight

        combined = rep_weight * opp_rep + trust_weight * trust

        # Use recent trend directly from the window
        if len(recent) > 0:
            recent_coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
            combined = 0.3 * combined + 0.7 * recent_coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        # Retaliation based on last few actions in the window
        if len(recent) >= 3:
            last_three = list(recent)[-3:]
            if any(a == 'defect' for a in last_three):
                combined -= self.retaliation

        # Forgiveness if recent window shows high cooperation
        if len(recent) >= 5 and sum(1 for a in recent if a == 'cooperate') >= 4 and combined > 0.4:
            combined += self.forgiveness

        # Additional caution if reputation and trust are both low
        if opp_rep < 0.3 and trust < 0.3:
            combined -= 0.1

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Increment observation counts
        self.observation_count[donor_id] = self.observation_count.get(donor_id, 0) + 1
        self.observation_count[recipient_id] = self.observation_count.get(recipient_id, 0) + 1

        # Track recent actions in sliding window
        if donor_id not in self.recent_actions:
            self.recent_actions[donor_id] = deque(maxlen=self.recent_window)
        if recipient_id not in self.recent_actions:
            self.recent_actions[recipient_id] = deque(maxlen=self.recent_window)
        self.recent_actions[donor_id].append(donor_action)
        self.recent_actions[recipient_id].append(recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)

        # Decay all reputations slightly each observation
        for agent in list(self.reputation.keys()):
            self.reputation[agent] = self.reputation[agent] * self.rep_decay

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if action == 'cooperate':
            obs = self.observation_count.get(agent_id, 0)
            bonus = self.coop_bonus * (1 + 0.1 * min(obs, 5))
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + bonus)
        else:
            obs = self.observation_count.get(agent_id, 0)
            penalty = self.defect_penalty * (1 + 0.1 * min(obs, 5))
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - penalty)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
