            self.learning_rate = max(0.05, self.learning_rate - 0.005)
        elif my_action == 'cooperate' and opp_action == 'defect':
            # Being exploited: decrease learning rate to be more cautious
            self.learning_rate = max(0.05, self.learning_rate - 0.02)
        elif my_action == 'defect' and opp_action == 'cooperate':
            # Exploiting opponent: increase learning rate to reinforce
            self.learning_rate = min(0.2, self.learning_rate + 0.015)

