        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        # Exploration: Replace the static weighted average with a dynamic
        # weight that shifts based on the volatility of the opponent's recent
        # actions.  Also use a sliding window (deque) for recent actions
        # to better capture short-term trends.
        self.base_rep_weight = 0.7
        self.volatility_scale = 0.25  # how much volatility shifts the weight
        self.rep_decay = 0.98
        self.observation_trust_update = 0.03
        self.defect_penalty_obs = 0.08
        self.observation_count = {}
        self.recent_actions = {}  # agent_id -> deque of recent actions
        self.recent_window = 10  # window size for volatility and recent trend

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        # Compute volatility from recent actions
        recent = self.recent_actions.get(opponent, deque())
        if len(recent) > 1:
            # Volatility = standard deviation of binary actions (cooperate=1, defect=0)
            actions = [1 if a == 'cooperate' else 0 for a in recent]
            mean = sum(actions) / len(actions)
            variance = sum((a - mean) ** 2 for a in actions) / len(actions)
            volatility = math.sqrt(variance)
        else:
            volatility = 0.5  # default when not enough data

        # Dynamic weight: more weight to trust when volatility is high
        rep_weight = self.base_rep_weight - self.volatility_scale * volatility
        rep_weight = max(0.0, min(1.0, rep_weight))
        trust_weight = 1.0 - rep_weight

        combined = rep_weight * opp_rep + trust_weight * trust

        # Use recent trend directly from the window
        if len(recent) > 0:
            recent_coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
            combined = 0.3 * combined + 0.7 * recent_coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        # Retaliation based on last few actions in the window
        if len(recent) >= 3:
            last_three = list(recent)[-3:]
            if any(a == 'defect' for a in last_three):
                combined -= self.retaliation

        # Forgiveness if recent window shows high cooperation
        if len(recent) >= 5 and sum(1 for a in recent if a == 'cooperate') >= 4 and combined > 0.4:
            combined += self.forgiveness

        # Additional caution if reputation and trust are both low
        if opp_rep < 0.3 and trust < 0.3:
            combined -= 0.1

        return combined > threshold

