        current = self.baseline_reputation[agent_id]
        if action == 'cooperate':
            target = 1.0
        else:
            target = 0.0
        # Slow update to avoid overreacting
        self.baseline_reputation[agent_id] = current + self.baseline_alpha * (target - current)

    def _update_grudge(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
