        recent_opp_coop = (sum(self.recent_opponent_actions[-10:]) / min(10, len(self.recent_opponent_actions))) if self.recent_opponent_actions else 1.0

        # New mechanism: calculate a grudge score based on recent defections against us
        if len(self.recent_opponent_actions) >= 3:
            recent_defects = sum(1 for action in self.recent_opponent_actions[-3:] if not action)
            grudge = min(1.0, recent_defects / 3)
            # Apply forgiveness: reduce grudge if opponent has cooperated recently
            if recent_opp_coop > 0.5:
                grudge = max(0.0, grudge - self.forgiveness)
            threshold = 0.5 + self.retaliation * grudge
        else:
            threshold = self.coop_threshold

        # Own recent behavior adjustment
        if len(self.recent_own_actions) >= 5:
            own_defect_rate = 1 - (sum(self.recent_own_actions[-5:]) / 5)
            threshold += own_defect_rate * 0.2

        # Bound threshold
        threshold = max(0.2, min(0.8, threshold))

        return combined >= threshold

