import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = 0.0
        self.coop_count = 0
        self.defect_count = 0
        self.observed_coop = {}
        self.observed_defect = {}
        self.round_num = 0
        self.generation = 0
        self.total_rounds = 0
        self.last_action = None
        self.opponent_history = {}
        self.my_history = []
        self.trust_scores = {}
        self.defection_penalty = 0.5
        self.cooperation_bonus = 0.3
        self.memory_size = 50
        self.recent_actions = []
        self.partner_coop_rates = {}
        self.partner_interactions = {}
        self.reputation_threshold = 0.0
        self.exploration_rate = 0.05
        self.alpha = 0.1
        self.beta = 0.05
        self.gamma = 0.1
        self.delta = 0.05

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        self.round_num += 1
        self.total_rounds += 1

        # Update generation estimate (30 rounds per generation)
        if self.round_num > 30:
            self.generation += 1
            self.round_num = 1

        # Initialize trust for new opponents
        if opponent_id not in self.trust_scores:
            self.trust_scores[opponent_id] = 0.0

        # Calculate opponent cooperation rate
        coop_rate = 0.5
        if opponent_id in self.partner_coop_rates:
            interactions = self.partner_interactions.get(opponent_id, 0)
            if interactions > 0:
                coop_rate = self.partner_coop_rates[opponent_id] / interactions

        # Adjust trust based on reputation
        trust = self.trust_scores[opponent_id]
        trust += self.reputation * 0.2
        trust = max(-1.0, min(1.0, trust))

        # Simple strategy: cooperate if trust is positive or early game
        if self.total_rounds <= 30:
            # Early game: explore and build trust
            if random.random() < self.exploration_rate:
                return random.choice([True, False])
            return trust >= -0.1

        if self.generation >= 2:
            # Later generations: more cooperative if reputation is good
            threshold = self.reputation_threshold - self.reputation * 0.3
            if trust > threshold:
                return True
            else:
                # Sometimes defect against untrusted opponents
                if random.random() < 0.2:
                    return False
                return True
        else:
            # Middle game: more strategic
            if trust > 0.2:
                return True
            elif trust < -0.2:
                return False
            else:
                return coop_rate > 0.5

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        try:
            # Update own reputation based on self actions
            if donor_id == self.agent_id:
                if donor_action == 'cooperate':
                    self.coop_count += 1
                    self.reputation += self.cooperation_bonus
                else:
                    self.defect_count += 1
                    self.reputation -= self.defection_penalty
                self.reputation = max(-2.0, min(2.0, self.reputation))
                self.last_action = donor_action
                self.recent_actions.append(donor_action)
                if len(self.recent_actions) > self.memory_size:
                    self.recent_actions.pop(0)

            if recipient_id == self.agent_id:
                if recipient_action == 'cooperate':
                    self.coop_count += 1
                    self.reputation += self.cooperation_bonus
                else:
                    self.defect_count += 1
                    self.reputation -= self.defection_penalty
                self.reputation = max(-2.0, min(2.0, self.reputation))

            # Track observed behavior for other agents
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id != self.agent_id:
                    if action == 'cooperate':
                        self.observed_coop[agent_id] = self.observed_coop.get(agent_id, 0) + 1
                    else:
                        self.observed_defect[agent_id] = self.observed_defect.get(agent_id, 0) + 1

                    total = self.observed_coop.get(agent_id, 0) + self.observed_defect.get(agent_id, 0)
                    if total > 0:
                        coop_ratio = self.observed_coop[agent_id] / total
                        # Update trust based on observed behavior
                        if coop_ratio > 0.7:
                            self.trust_scores[agent_id] = self.trust_scores.get(agent_id, 0.0) + self.alpha
                        elif coop_ratio < 0.3:
                            self.trust_scores[agent_id] = self.trust_scores.get(agent_id, 0.0) - self.alpha
                        self.trust_scores[agent_id] = max(-1.0, min(1.0, self.trust_scores[agent_id]))

            # Update partner-specific stats if this is our opponent
            if donor_id == self._ctx_opponent_id or recipient_id == self._ctx_opponent_id:
                opp_id = self._ctx_opponent_id
                if donor_id == opp_id:
                    opp_action = donor_action
                else:
                    opp_action = recipient_action

                if opp_action == 'cooperate':
                    self.partner_coop_rates[opp_id] = self.partner_coop_rates.get(opp_id, 0) + 1
                self.partner_interactions[opp_id] = self.partner_interactions.get(opp_id, 0) + 1

                # Update trust based on opponent's action in our interaction
                if opp_action == 'cooperate':
                    self.trust_scores[opp_id] = self.trust_scores.get(opp_id, 0.0) + self.beta
                else:
                    self.trust_scores[opp_id] = self.trust_scores.get(opp_id, 0.0) - self.beta
                self.trust_scores[opp_id] = max(-1.0, min(1.0, self.trust_scores[opp_id]))
        except Exception:
            pass

