        self._update_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)
        self._update_opponent_coop_rate(donor_id, donor_action, recipient_id, recipient_action)

        # New mechanism: update suspicion instead of grudge
        self._update_suspicion(donor_id, donor_action, recipient_id, recipient_action)

        # New mechanism: update cooperation momentum based on our own actions
        if donor_id == self.agent_id:
            self._update_cooperation_momentum(donor_action)
        if recipient_id == self.agent_id:
            self._update_cooperation_momentum(recipient_action)

        # Emotional state update (kept from parent)
        self.emotional_state *= self.emotion_decay
        if donor_action == 'cooperate':
            self.emotional_state = min(1.0, self.emotional_state + 0.1)
        else:
            self.emotional_state = max(-1.0, self.emotional_state - 0.15)
        if recipient_action == 'cooperate':
            self.emotional_state = min(1.0, self.emotional_state + 0.05)
        else:
            self.emotional_state = max(-1.0, self.emotional_state - 0.05)

        delta = 0.1 if donor_action == 'cooperate' else -0.15
        self.opponent_emotion[donor_id] = self.opponent_emotion.get(donor_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[donor_id] = max(-1.0, min(1.0, self.opponent_emotion[donor_id]))

        delta = 0.05 if recipient_action == 'cooperate' else -0.05
        self.opponent_emotion[recipient_id] = self.opponent_emotion.get(recipient_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[recipient_id] = max(-1.0, min(1.0, self.opponent_emotion[recipient_id]))

    def _update_suspicion(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay suspicion for all agents periodically (or on each observation)
        for agent in list(self.suspicion.keys()):
            self.suspicion[agent] *= self.suspicion_decay
            if self.suspicion[agent] < 0.01:
                del self.suspicion[agent]

        # Increase suspicion if we are defected against
        if recipient_id == self.agent_id and donor_action == 'defect':
            self.suspicion[donor_id] = self.suspicion.get(donor_id, 0.0) + 0.3
            self.suspicion[donor_id] = min(1.0, self.suspicion[donor_id])
        # Decrease suspicion if we are cooperated with
        if recipient_id == self.agent_id and donor_action == 'cooperate':
            self.suspicion[donor_id] = self.suspicion.get(donor_id, 0.0) - 0.1
            self.suspicion[donor_id] = max(0.0, self.suspicion[donor_id])
        # Also if we are donor and recipient defects against us
        if donor_id == self.agent_id and recipient_action == 'defect':
            self.suspicion[recipient_id] = self.suspicion.get(recipient_id, 0.0) + 0.3
            self.suspicion[recipient_id] = min(1.0, self.suspicion[recipient_id])
        # If recipient cooperates with us, decrease suspicion
        if donor_id == self.agent_id and recipient_action == 'cooperate':
            self.suspicion[recipient_id] = self.suspicion.get(recipient_id, 0.0) - 0.1
            self.suspicion[recipient_id] = max(0.0, self.suspicion[recipient_id])

        # Also update suspicion based on third-party observations: if we see someone
        # defecting against others, we slightly increase suspicion
        if donor_id != self.agent_id and donor_action == 'defect':
            self.suspicion[donor_id] = self.suspicion.get(donor_id, 0.0) + 0.05
            self.suspicion[donor_id] = min(1.0, self.suspicion[donor_id])
        if donor_id != self.agent_id and donor_action == 'cooperate':
            self.suspicion[donor_id] = self.suspicion.get(donor_id, 0.0) - 0.02
            self.suspicion[donor_id] = max(0.0, self.suspicion[donor_id])

    def _update_cooperation_momentum(self, action: str) -> None:
