        self.reciprocity_positive = 0.2
        self.reciprocity_negative = 0.35
        self.reciprocity_threshold = 0.6
        self.reciprocity_impact = 0.5
        # New mechanism: track a "generosity" trait that slowly adapts based on
        # overall cooperation rate, influencing our baseline threshold.
        self.generosity = 0.5
        self.generosity_adapt = 0.05
        self.generosity_floor = 0.2
        self.generosity_ceiling = 0.8

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
