        self.opponent_emotion[donor_id] = self.opponent_emotion.get(donor_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[donor_id] = max(-1.0, min(1.0, self.opponent_emotion[donor_id]))

        delta = 0.05 if recipient_action == 'cooperate' else -0.05
        self.opponent_emotion[recipient_id] = self.opponent_emotion.get(recipient_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[recipient_id] = max(-1.0, min(1.0, self.opponent_emotion[recipient_id]))

    def _update_reciprocity(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay reciprocity for all agents
        for agent in list(self.reciprocity.keys()):
            self.reciprocity[agent] *= self.reciprocity_decay
            if abs(self.reciprocity[agent]) < 0.01:
                del self.reciprocity[agent]

        # Direct interactions have higher weight
        direct_weight = 1.5
        indirect_weight = 0.5

        # Update based on direct interactions
        if recipient_id == self.agent_id:
            if donor_action == 'cooperate':
                self.reciprocity[donor_id] = self.reciprocity.get(donor_id, 0.0) - self.reciprocity_positive * direct_weight
            else:
                self.reciprocity[donor_id] = self.reciprocity.get(donor_id, 0.0) + self.reciprocity_negative * direct_weight
        if donor_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.reciprocity[recipient_id] = self.reciprocity.get(recipient_id, 0.0) - self.reciprocity_positive * direct_weight
            else:
                self.reciprocity[recipient_id] = self.reciprocity.get(recipient_id, 0.0) + self.reciprocity_negative * direct_weight

        # Indirect observations (third-party) have lower weight
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reciprocity[donor_id] = self.reciprocity.get(donor_id, 0.0) - self.reciprocity_positive * indirect_weight
            else:
                self.reciprocity[donor_id] = self.reciprocity.get(donor_id, 0.0) + self.reciprocity_negative * indirect_weight
            if recipient_action == 'cooperate':
                self.reciprocity[recipient_id] = self.reciprocity.get(recipient_id, 0.0) - self.reciprocity_positive * indirect_weight
            else:
                self.reciprocity[recipient_id] = self.reciprocity.get(recipient_id, 0.0) + self.reciprocity_negative * indirect_weight

        # Clamp to [-1, 1]
        for agent in self.reciprocity:
            self.reciprocity[agent] = max(-1.0, min(1.0, self.reciprocity[agent]))

    def _update_generosity(self, action: str) -> None:
        # Adapt generosity toward overall cooperation rate
        if action == 'cooperate':
            self.generosity = min(self.generosity_ceiling, self.generosity + self.generosity_adapt)
        else:
            self.generosity = max(self.generosity_floor, self.generosity - self.generosity_adapt)

    def _update_opponent_coop_rate(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
