        self.reputation_decay = 0.95
        self.recent_observations = deque(maxlen=50)
        self.opponent_coop_rate = {}
        self.threshold_adjustment = 0.0
        self.grudge = {}
        # New mechanism: exponential decay factor for reputation updates
        self.reputation_sensitivity = 0.8  # how strongly reputation updates are applied
        # New mechanism: track a long-term baseline reputation per agent
        self.baseline_reputation = {}  # agent_id -> stable estimate
        self.baseline_alpha = 0.05  # learning rate for baseline updates
        # New mechanism: track frequency of cooperation with each opponent
        self.coop_frequency = {}  # agent_id -> count of my cooperation vs them
        self.defect_frequency = {}  # agent_id -> count of my defection vs them

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        # Use baseline reputation as primary signal
        baseline = self.baseline_reputation.get(opponent, 0.5)
        # Adjust baseline based on recent direct interactions
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if recent:
                coop_rate = sum(1 for a, b in recent if b == 'cooperate') / len(recent)
                # Blend baseline with direct experience
                direct_weight = min(0.5, len(recent) / (self.memory * 2))
                baseline = (1 - direct_weight) * baseline + direct_weight * coop_rate

        # Add small noise
        threshold = 0.5 + (random.random() - 0.5) * 0.05

        # Retaliation if recently defected against
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                baseline -= self.retaliation

        # Forgiveness if opponent generally cooperates
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and baseline > 0.4:
                baseline += self.forgiveness

        # Use grudge to reduce cooperation
        grudge_value = self.grudge.get(opponent, 0.0)
        baseline -= grudge_value * 0.3

        return baseline > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))

        # Update reputation with sensitivity factor
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Update baseline reputation slowly
        self._update_baseline(donor_id, donor_action)
        self._update_baseline(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)
        self._update_opponent_coop_rate(donor_id, donor_action, recipient_id, recipient_action)
        self._update_grudge(donor_id, donor_action, recipient_id, recipient_action)

    def _update_baseline(self, agent_id: int, action: str) -> None:
        # Update a long-term baseline using exponential moving average
        if agent_id not in self.baseline_reputation:
            self.baseline_reputation[agent_id] = 0.5
        current = self.baseline_reputation[agent_id]
        if action == 'cooperate':
            target = 1.0
        else:
            target = 0.0
        # Slow update to avoid overreacting
        self.baseline_reputation[agent_id] = current + self.baseline_alpha * (target - current)

    def _update_grudge(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if recipient_id == self.agent_id and donor_action == 'defect':
            self.grudge[donor_id] = self.grudge.get(donor_id, 0.0) + 0.2
            self.grudge[donor_id] = min(1.0, self.grudge[donor_id])
        if recipient_id == self.agent_id and donor_action == 'cooperate':
            self.grudge[donor_id] = self.grudge.get(donor_id, 0.0) - 0.1
            self.grudge[donor_id] = max(0.0, self.grudge[donor_id])
        if donor_id == self.agent_id and recipient_action == 'defect':
            self.grudge[recipient_id] = self.grudge.get(recipient_id, 0.0) + 0.2
            self.grudge[recipient_id] = min(1.0, self.grudge[recipient_id])
        if donor_id == self.agent_id and recipient_action == 'cooperate':
            self.grudge[recipient_id] = self.grudge.get(recipient_id, 0.0) - 0.1
            self.grudge[recipient_id] = max(0.0, self.grudge[recipient_id])

    def _update_opponent_coop_rate(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.opponent_coop_rate:
                self.opponent_coop_rate[agent_id] = 0.5
            alpha = 0.1
            if action == 'cooperate':
                self.opponent_coop_rate[agent_id] = (1 - alpha) * self.opponent_coop_rate[agent_id] + alpha * 1.0
            else:
                self.opponent_coop_rate[agent_id] = (1 - alpha) * self.opponent_coop_rate[agent_id] + alpha * 0.0

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        # Apply decay and sensitivity
        self.reputation[agent_id] *= self.reputation_decay
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus * self.reputation_sensitivity)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty * self.reputation_sensitivity)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = deque(maxlen=self.memory * 3)
        self.interactions[opp_id].append((my_action, opp_action))

        if my_action == 'cooperate':
            self.cooperation_count += 1
            # Track frequency
            self.coop_frequency[opp_id] = self.coop_frequency.get(opp_id, 0) + 1
        else:
            self.defection_count += 1
            self.defect_frequency[opp_id] = self.defect_frequency.get(opp_id, 0) + 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

