        self.exploration_rate = 0.05
        self.alpha = 0.1
        self.beta = 0.05
        self.gamma = 0.1
        self.delta = 0.05

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        self.round_num += 1
        self.total_rounds += 1

        # Update generation estimate (30 rounds per generation)
        if self.round_num > 30:
            self.generation += 1
            self.round_num = 1

        # Initialize trust for new opponents
        if opponent_id not in self.trust_scores:
            self.trust_scores[opponent_id] = 0.0

        # Calculate opponent cooperation rate
        coop_rate = 0.5
        if opponent_id in self.partner_coop_rates:
            interactions = self.partner_interactions.get(opponent_id, 0)
            if interactions > 0:
                coop_rate = self.partner_coop_rates[opponent_id] / interactions

        # Adjust trust based on reputation
        trust = self.trust_scores[opponent_id]
        trust += self.reputation * 0.2
        trust = max(-1.0, min(1.0, trust))

