        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        self.reputation_decay = 0.95
        self.recent_observations = deque(maxlen=50)
        self.trust_adjustment_rate = 0.05
        # New mechanism: reputation-based decision threshold adaptation
        self.threshold_adaptation = 0.05
        self.recent_self_outcomes = deque(maxlen=20)  # store my recent outcomes (cooperate/defect)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        # Get opponent's reputation with recency weighting
        opp_rep = self.reputation.get(opponent, 0.5)

        # Get trust from direct interactions
        trust = self.trust.get(opponent, self.initial_trust)

        # Combine reputation and trust
        combined = 0.6 * opp_rep + 0.4 * trust

        # If we've had many interactions with this opponent, use more direct experience
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        # Add some randomness to avoid being too predictable, but keep mostly deterministic
        threshold = 0.5 + (random.random() - 0.5) * 0.1

        # If we've been defected against recently by this opponent, retaliate
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation

        # Forgive occasional defections if opponent generally cooperates
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # Check consistency of opponent's recent behavior
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            if len(recent) >= 3:
                coop_actions = [b for a, b in recent if b == 'cooperate']
                defect_actions = [b for a, b in recent if b == 'defect']
                if len(coop_actions) > 0 and len(defect_actions) > 0:
                    combined -= self.trust_adjustment_rate
                elif len(coop_actions) == 0 and len(defect_actions) > 0:
                    combined -= 2 * self.trust_adjustment_rate
                elif len(coop_actions) > 0 and len(defect_actions) == 0:
                    combined += self.trust_adjustment_rate

        # New mechanism: Adaptive threshold based on recent outcomes
        # If I've been cooperating a lot and getting exploited, become more cautious
        # If I've been defecting a lot and getting punished, become more cooperative
        if len(self.recent_self_outcomes) >= 5:
            recent_outcomes = list(self.recent_self_outcomes)
            my_coop_count = recent_outcomes.count('cooperate')
            my_defect_count = recent_outcomes.count('defect')
            if my_defect_count > my_coop_count * 2:
                # I've been defecting too much, lower threshold to cooperate more
                threshold -= self.threshold_adaptation
            elif my_coop_count > my_defect_count * 2:
                # I've been cooperating a lot, maybe I'm being too generous, raise threshold
                threshold += self.threshold_adaptation

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Store observation with timestamp for recency weighting
        self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))

