        self.trust_gate_threshold = 0.6  # Minimum reputation to trust
        self.trust_gate_penalty = 0.15   # Trust reduction for below-threshold reputation
        self.trust_gate_bonus = 0.1      # Trust boost for high reputation
        self.reputation_trust_weight = 0.5  # How much reputation influences trust
        self.recent_self_outcomes = deque(maxlen=20)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
