        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if recent:
                coop_rate = sum(1 for a, b in recent if b == 'cooperate') / len(recent)
                # Blend reputation with direct experience
                direct_weight = min(0.7, len(recent) / (self.memory * 2))
                base = (1 - direct_weight) * base + direct_weight * coop_rate

