        self.consistency_alpha = 0.2
        self.consistency_threshold = 0.2  # if consistency low, be more cautious
        # New mechanism: adaptive forgiveness based on global cooperation level
        self.global_coop_trend = 0.5  # EMA of global cooperation rate
        self.trend_alpha = 0.1
        self.base_threshold = 0.5  # base cooperation threshold

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
