        base = self.reputation.get(opponent, 0.5)

        # Adjust based on recent direct interactions (weighted more heavily)
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if recent:
                coop_rate = sum(1 for a, b in recent if b == 'cooperate') / len(recent)
                # Blend reputation with direct experience
                direct_weight = min(0.7, len(recent) / (self.memory * 2))
                base = (1 - direct_weight) * base + direct_weight * coop_rate

        # Adjust threshold based on global cooperation trend
        # If global cooperation is high, be more cooperative; if low, be more cautious
        threshold = self.base_threshold + (self.global_coop_trend - 0.5) * 0.1
        # Add noise to avoid deterministic behavior
        threshold += (random.random() - 0.5) * 0.05

        # Retaliation with dynamic sensitivity
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                # Scale retaliation based on how often they defect recently
                defect_count = sum(1 for a, b in recent if b == 'defect')
                base -= self.retaliation * self.retaliation_sensitivity * (defect_count / len(recent))

        # Adaptive forgiveness: forgive more if global cooperation is high
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4:
                base += self.forgiveness * (0.5 + self.global_coop_trend)

        # Use consistency to modulate trust
        if opponent in self.consistency:
            if self.consistency[opponent] < self.consistency_threshold:
                base -= 0.1  # be more cautious with inconsistent opponents

        # Grudge adjustment
        grudge_value = self.grudge.get(opponent, 0.0)
        base -= grudge_value * 0.3

