        self.recent_interactions = {}  # opp_id -> list of (my_action, opp_action)
        self.max_history = 10
        # Track observations of others (third-party)
        self.third_party_obs = {}  # (donor, recipient) -> list of actions
        # Track defection patterns
        self.defection_counts = {}
        self.total_obs = 0

    def decide(self) -> bool:
        # Simple deterministic strategy: cooperate unless opponent has defected more than cooperated
        # in our history, or has low reputation
        if self.opponent_id is None:
            return True

        # Get opponent history
        hist = self.history.get(self.opponent_id, [])
        if not hist:
            # No history - check reputation
            rep = self.reputation.get(self.opponent_id, 0.5)
            return rep >= 0.5

        # Count opponent's actions
        opp_coop = sum(1 for _, a in hist if a == 'cooperate')
        opp_defect = len(hist) - opp_coop

        # If opponent defects more than cooperates, defect
        if opp_defect > opp_coop:
            return False

        # If opponent has cooperated at least as much, cooperate
        return True

