        if recipient_id not in self.defection_counts:
            self.defection_counts[recipient_id] = 0
        if recipient_action == 'defect':
            self.defection_counts[recipient_id] += 1

    def _update_history(self, opp_id, my_action, opp_action):
        if opp_id not in self.history:
            self.history[opp_id] = []
        self.history[opp_id].append((my_action, opp_action))
