            opp_action = donor_action

        # Mood updates based on the outcome relative to expectations
        # If I cooperated and opponent cooperated: positive mood (happy)
        # If I cooperated and opponent defected: negative mood (betrayed)
        # If I defected and opponent cooperated: slightly positive (got away)
        # If I defected and opponent defected: neutral to slightly negative
        if my_action == 'cooperate' and opp_action == 'cooperate':
            self.mood = min(1.0, self.mood + 0.2)
        elif my_action == 'cooperate' and opp_action == 'defect':
            self.mood = max(-1.0, self.mood - 0.3)
        elif my_action == 'defect' and opp_action == 'cooperate':
            self.mood = min(1.0, self.mood + 0.1)
        elif my_action == 'defect' and opp_action == 'defect':
            self.mood = max(-1.0, self.mood - 0.1)

        # Mood is bounded
        self.mood = max(-1.0, min(1.0, self.mood))

