        consistency_value = self.consistency.get(opponent, 0.5)
        # If consistency is low, we are more cautious; if high, we are more confident
        combined += (consistency_value - self.consistency_threshold) * 0.3

        # New mechanism: risk tolerance directly modulates threshold
        # Higher risk tolerance means we cooperate even with uncertain opponents
        threshold -= (self.risk_tolerance - 0.5) * 0.25

        # Emotional modulation (kept from parent)
        opp_emotion = self.opponent_emotion.get(opponent, 0.0)
        emotional_bias = self.emotional_state * self.emotion_decay + opp_emotion * 0.5
        emotional_bias = max(-0.5, min(0.5, emotional_bias))
        combined += emotional_bias

        return combined > threshold

