        if action == 'cooperate':
            self.risk_tolerance = min(self.risk_tolerance_max, self.risk_tolerance + self.risk_tolerance_update_rate)
        else:
            self.risk_tolerance = max(self.risk_tolerance_min, self.risk_tolerance - self.risk_tolerance_update_rate)

    def _update_consistency(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay consistency for all agents periodically
        for agent in list(self.consistency.keys()):
            self.consistency[agent] *= self.consistency_decay
            if self.consistency[agent] < 0.01:
