        self.own_outcomes = deque(maxlen=50)

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True

        opponent = self._ctx_opponent_id

        # Use partner-specific trust if available, otherwise reputation
        if opponent in self.trust:
            trust_score = self.trust[opponent]
        else:
            rep = self.reputation.get(opponent, 0.5)
            trust_score = rep

        # Get direct interaction history
        hist = self.interactions.get(opponent, [])
        if hist:
            opp_coop_rate = sum(1 for _, opp in hist if opp) / len(hist)
            # Weighted: trust (0.6) plus direct experience (0.4)
            combined = 0.6 * trust_score + 0.4 * opp_coop_rate
        else:
            combined = trust_score

        # Adaptive threshold based on recent outcomes
        if len(self.own_outcomes) >= 10:
            coop_rate = sum(self.own_outcomes) / len(self.own_outcomes)
            # If we've been cooperating a lot but not getting rewards, raise threshold
            if coop_rate > 0.8:
                threshold = self.coop_threshold + 0.1
            elif coop_rate < 0.3:
                threshold = self.coop_threshold - 0.1
            else:
                threshold = self.coop_threshold
        else:
            threshold = self.coop_threshold

        # Streak penalty: if opponent defected consecutively, be cautious
        if self.opponent_defect_streak >= 2:
            threshold += 0.2

        # Win/loss adjustment
        if self.wins + self.losses > 0:
            win_rate = self.wins / (self.wins + self.losses)
            threshold += 0.15 * (0.5 - win_rate)

        # Exploration
        if random.random() < self.exploration_rate:
