        for agent in list(self.rep_uncertainty.keys()):
            self.rep_uncertainty[agent] = self.rep_uncertainty[agent] * self.uncertainty_decay

        # Update reputation for both agents, with different weights for direct vs observed
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Direct interaction: stronger update
            self._update_reputation(donor_id, donor_action, weight=1.0)
            self._update_reputation(recipient_id, recipient_action, weight=1.0)
        else:
            # Observed interaction: weaker update
            self._update_reputation(donor_id, donor_action, weight=self.observed_weight)
            self._update_reputation(recipient_id, recipient_action, weight=self.observed_weight)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)

        # Update reciprocity window for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reciprocity_window:
                self.reciprocity_window[agent_id] = []
            self.reciprocity_window[agent_id].append(action)
            if len(self.reciprocity_window[agent_id]) > self.window_size:
                self.reciprocity_window[agent_id].pop(0)

        # Adapt trust threshold based on own cooperation rate
        total_actions = self.cooperation_count + self.defection_count
        if total_actions > 0:
            coop_rate = self.cooperation_count / total_actions
            # If we cooperate too much, become more selective; if too little, become more cooperative
            if coop_rate > 0.65:
                self.trust_threshold = min(0.8, self.trust_threshold + self.trust_adapt_rate)
            elif coop_rate < 0.35:
                self.trust_threshold = max(0.2, self.trust_threshold - self.trust_adapt_rate)

    def _update_reputation(self, agent_id: int, action: str, weight: float = 1.0) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
            self.rep_uncertainty[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus * weight)
            self.rep_uncertainty[agent_id] = max(0.0, self.rep_uncertainty[agent_id] - self.uncertainty_increase * weight)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty * weight)
            self.rep_uncertainty[agent_id] = min(1.0, self.rep_uncertainty[agent_id] + self.uncertainty_increase * weight)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = []
        self.interactions[opp_id].append((my_action, opp_action))

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.15)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.15)

        if opp_id not in self.rep_uncertainty:
            self.rep_uncertainty[opp_id] = 0.5
        self.rep_uncertainty[opp_id] = max(0.0, self.rep_uncertainty[opp_id] - 0.2)

        self.total_interactions += 1

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        # Trust updates are stronger for direct interactions
        weight = 1.0 if donor_id == self.agent_id or recipient_id == self.agent_id else self.observed_weight

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - self.defect_penalty_obs * weight)
