        # New: track partner-specific trust with decay
        self.trust = {}
        # New: track personal history of outcomes for adaptive memory
        self.own_outcomes = deque(maxlen=50)
        # New: track a personal reputation (how others see us) - we can't observe directly, but we can infer from our own actions and outcomes
        self.self_reputation = 0.5
        # New: track the average cooperativeness of the population over time
        self.pop_coop_avg = deque(maxlen=30)
        self.pop_coop_sum = 0.0
        self.pop_total_actions = 0
        # New: track a rolling window of recent reputation values for each agent to detect trends
        self.rep_history = {}  # agent_id -> deque of recent reputation values

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True

        opponent = self._ctx_opponent_id

        # Use partner-specific trust if available, otherwise reputation
        if opponent in self.trust:
            trust_score = self.trust[opponent]
        else:
            rep = self.reputation.get(opponent, 0.5)
            trust_score = rep

        # Get direct interaction history
        hist = self.interactions.get(opponent, [])
        if hist:
            opp_coop_rate = sum(1 for _, opp in hist if opp) / len(hist)
            # Weighted: trust (0.6) plus direct experience (0.4) - keep as parent
            combined = 0.6 * trust_score + 0.4 * opp_coop_rate
        else:
            combined = trust_score

        # Adaptive threshold based on recent outcomes - keep but with a twist: use a trend in own outcomes
        if len(self.own_outcomes) >= 10:
            coop_rate = sum(self.own_outcomes) / len(self.own_outcomes)
            # New: if our recent cooperation rate is decreasing, be more cautious (raise threshold)
            if len(self.own_outcomes) >= 20:
                recent_rate = sum(list(self.own_outcomes)[-10:]) / 10
                if recent_rate < coop_rate:
                    threshold = self.coop_threshold + 0.05
                elif recent_rate > coop_rate:
                    threshold = self.coop_threshold - 0.05
                else:
                    threshold = self.coop_threshold
            else:
                if coop_rate > 0.8:
                    threshold = self.coop_threshold + 0.1
                elif coop_rate < 0.3:
                    threshold = self.coop_threshold - 0.1
                else:
                    threshold = self.coop_threshold
        else:
            threshold = self.coop_threshold

        # Streak penalty: if opponent defected consecutively, be cautious
        if self.opponent_defect_streak >= 2:
            threshold += 0.2

        # Win/loss adjustment - keep but scale down to avoid over-adjustment
        if self.wins + self.losses > 0:
            win_rate = self.wins / (self.wins + self.losses)
            threshold += 0.1 * (0.5 - win_rate)

        # New: incorporate population trend - if population is becoming more cooperative, we can be slightly more trusting
        if len(self.pop_coop_avg) >= 5:
            pop_trend = self.pop_coop_avg[-1] - self.pop_coop_avg[0]
            if pop_trend > 0.05:
                threshold -= 0.05
            elif pop_trend < -0.05:
                threshold += 0.05

        # Exploration
        if random.random() < self.exploration_rate:
            return random.random() < 0.5

        return combined >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            donor_coop = donor_action == 'cooperate'
            recipient_coop = recipient_action == 'cooperate'

            # Reputation update with faster decay (less reliance on old info) - keep but also track history
            if donor_id in self.reputation:
                old_rep = self.reputation[donor_id]
                self.reputation[donor_id] = old_rep * 0.8 + (0.2 if donor_coop else 0)
            else:
                old_rep = 0.5 if donor_coop else 0.0
                self.reputation[donor_id] = old_rep

            if recipient_id in self.reputation:
                old_rep_recip = self.reputation[recipient_id]
                self.reputation[recipient_id] = old_rep_recip * 0.8 + (0.2 if recipient_coop else 0)
            else:
                old_rep_recip = 0.5 if recipient_coop else 0.0
                self.reputation[recipient_id] = old_rep_recip

            # Update reputation history for trend detection
            for agent_id, coop in [(donor_id, donor_coop), (recipient_id, recipient_coop)]:
                if agent_id not in self.rep_history:
                    self.rep_history[agent_id] = deque(maxlen=10)
                self.rep_history[agent_id].append(self.reputation[agent_id])

            # Update partner-specific trust with a stronger reaction to defection - keep but add a slight trend effect
            if donor_id != self.agent_id:
                if donor_id in self.trust:
                    # If reputation is rising, give a slight boost to trust update
                    if donor_id in self.rep_history and len(self.rep_history[donor_id]) >= 2:
                        rep_trend = self.rep_history[donor_id][-1] - self.rep_history[donor_id][-2]
                        boost = 0.02 * rep_trend
                    else:
                        boost = 0.0
                    self.trust[donor_id] = self.trust[donor_id] * 0.9 + (0.1 if donor_coop else -0.2) + boost
                else:
                    self.trust[donor_id] = 0.5 if donor_coop else 0.3
                self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))

            if recipient_id != self.agent_id:
                if recipient_id in self.trust:
                    if recipient_id in self.rep_history and len(self.rep_history[recipient_id]) >= 2:
                        rep_trend = self.rep_history[recipient_id][-1] - self.rep_history[recipient_id][-2]
                        boost = 0.02 * rep_trend
                    else:
                        boost = 0.0
                    self.trust[recipient_id] = self.trust[recipient_id] * 0.9 + (0.1 if recipient_coop else -0.2) + boost
                else:
                    self.trust[recipient_id] = 0.5 if recipient_coop else 0.3
                self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

            self.observations.append((donor_id, donor_coop, recipient_id, recipient_coop))

            # Update population cooperation stats
            self.pop_total_actions += 2
            self.pop_coop_sum += (1 if donor_coop else 0) + (1 if recipient_coop else 0)
            # Update rolling average every 10 observations
            if len(self.observations) % 10 == 0:
                avg = self.pop_coop_sum / self.pop_total_actions
                self.pop_coop_avg.append(avg)
                # Reset counters for next window
                self.pop_coop_sum = 0.0
                self.pop_total_actions = 0

            # Handle self-judgment
            if donor_id == self.agent_id:
                self.own_history.append((donor_coop, recipient_id, recipient_coop))
                if len(self.own_history) > self.max_memory:
                    self.own_history = self.own_history[-self.max_memory:]
                self.recent_own_actions.append(donor_coop)
                self.own_outcomes.append(donor_coop and recipient_coop)

                if recipient_id not in self.interactions:
