                    self.opponent_defect_streak += 1
                elif not donor_coop and recipient_coop:
                    self.wins += 1
                    self.opponent_defect_streak = 0
                else:
                    self.opponent_defect_streak = 0

                # Update self-reputation based on outcomes: if we cooperate and get cooperated back, our reputation goes up; if we defect and get cooperation, it goes down
                if donor_coop and recipient_coop:
                    self.self_reputation = self.self_reputation * 0.95 + 0.05 * 1.0
                elif donor_coop and not recipient_coop:
                    self.self_reputation = self.self_reputation * 0.95 + 0.05 * 0.5
