                self.recent_opponent_actions.append(donor_coop)

                if recipient_coop and not donor_coop:
                    self.losses += 1
                    self.opponent_defect_streak += 1
                elif not recipient_coop and donor_coop:
                    self.wins += 1
                    self.opponent_defect_streak = 0
                else:
                    self.opponent_defect_streak = 0

                # Similar self-reputation update for when we are recipient
                if recipient_coop and donor_coop:
                    self.self_reputation = self.self_reputation * 0.95 + 0.05 * 1.0
                elif recipient_coop and not donor_coop:
                    self.self_reputation = self.self_reputation * 0.95 + 0.05 * 0.5
                elif not recipient_coop and donor_coop:
                    self.self_reputation = self.self_reputation * 0.95 + 0.05 * 0.0
                else:
                    self.self_reputation = self.self_reputation * 0.95 + 0.05 * 0.5

            # Adjust threshold based on population behavior but with a slower response - keep but adjust slightly less
            if len(self.observations) % 15 == 0 and len(self.observations) > 0:
                total_actions = len(self.observations) * 2
                coop_actions = sum(1 for _, dc, _, rc in self.observations if dc) + sum(1 for _, _, _, rc in self.observations if rc)
                pop_rate = coop_actions / total_actions if total_actions > 0 else 0.5
                # Only adjust slightly, keep threshold stable - but use a slower factor
                self.coop_threshold = self.coop_threshold * 0.95 + 0.05 * (0.5 - (pop_rate - 0.5) * 0.1)
                self.coop_threshold = max(0.2, min(0.8, self.coop_threshold))

        except Exception:
            pass

