                elif recent[-1][0] == 'defect' and recent[-1][1] == 'cooperate':
                    threshold -= 0.05

        # Child-specific: incorporate trend analysis
        if opponent in self.trend:
            trend_val = self.trend[opponent]
            # If the trend is positive (opponent cooperating more), add to combined
            if trend_val > 0:
                combined += self.trend_weight * trend_val
            # If negative, increase threshold to be more cautious
            else:
                threshold += -self.trend_weight * trend_val

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        self._update_streak(donor_id, donor_action)
        self._update_streak(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)
        self._update_uncertainty(donor_id, donor_action, recipient_id, recipient_action)
        self._update_rep_velocity(donor_id, donor_action)
        self._update_rep_velocity(recipient_id, recipient_action)

        if donor_id == self.agent_id:
            self.recent_actions.append(donor_action)
        elif recipient_id == self.agent_id:
            self.recent_actions.append(recipient_action)

        # Child-specific: update trend for observed agents
        self._update_trend(donor_id, donor_action)
        self._update_trend(recipient_id, recipient_action)

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)

    def _update_streak(self, agent_id: int, action: str) -> None:
        if agent_id not in self.streak:
            self.streak[agent_id] = (action, 1)
        else:
            prev_type, prev_len = self.streak[agent_id]
            if prev_type == action:
                self.streak[agent_id] = (action, prev_len + 1)
            else:
                self.streak[agent_id] = (action, 1)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = deque(maxlen=50)
        self.interactions[opp_id].append((my_action, opp_action))

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        self.total_interactions += 1
        self.recent_outcomes.append((my_action, opp_action))

        if my_action == 'cooperate' and opp_action == 'cooperate':
            self.coop_tendency = min(1.0, self.coop_tendency + 0.05)
        elif my_action == 'defect' and opp_action == 'defect':
            self.coop_tendency = max(0.0, self.coop_tendency - 0.05)

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - 0.05)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + 0.02)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - 0.05)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + 0.02)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.partner_reputation:
            self.partner_reputation[recipient_id] = {'coop': 0, 'defect': 0}

        if donor_action == 'cooperate':
            self.partner_reputation[donor_id]['coop'] += 1
        else:
            self.partner_reputation[donor_id]['defect'] += 1

        if recipient_action == 'cooperate':
            self.partner_reputation[recipient_id]['coop'] += 1
        else:
            self.partner_reputation[recipient_id]['defect'] += 1

        if donor_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1
        if recipient_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1

    def _update_uncertainty(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.uncertainty:
                self.uncertainty[agent_id] = 0.0
            else:
                self.uncertainty[agent_id] *= self.uncertainty_decay

            rep = self.reputation.get(agent_id, 0.5)
            if (action == 'cooperate' and rep < 0.4) or (action == 'defect' and rep > 0.6):
                self.uncertainty[agent_id] = min(1.0, self.uncertainty[agent_id] + self.uncertainty_boost)
            else:
                self.uncertainty[agent_id] = max(0.0, self.uncertainty[agent_id] - 0.02)

            if agent_id in self.streak:
                streak_type, streak_len = self.streak[agent_id]
                if streak_len >= 3:
                    self.uncertainty[agent_id] = max(0.0, self.uncertainty[agent_id] - 0.05)
                elif streak_len >= 5:
                    self.uncertainty[agent_id] = max(0.0, self.uncertainty[agent_id] - 0.1)

    def _update_rep_velocity(self, agent_id: int, action: str) -> None:
        if action == 'cooperate':
            change = self.coop_bonus
        else:
            change = -self.defect_penalty

        if agent_id not in self.rep_velocity:
            self.rep_velocity[agent_id] = change
        else:
            self.rep_velocity[agent_id] = self.velocity_decay * self.rep_velocity[agent_id] + (1 - self.velocity_decay) * change

    # Child-specific method: track a trend of cooperation vs defection for each observed agent
    def _update_trend(self, agent_id: int, action: str) -> None:
        if agent_id not in self.trend:
            self.trend[agent_id] = deque(maxlen=self.trend_window)
        # Convert action to numeric: cooperate=1, defect=-1
        value = 1 if action == 'cooperate' else -1
        self.trend[agent_id].append(value)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        self.reputation_decay = 0.95
        self.recent_observations = deque(maxlen=50)
        self.opponent_coop_rate = {}
        self.threshold_adjustment = 0.0
        self.grudge = {}
        self.emotional_state = 0.0
        self.emotion_decay = 0.9
        self.emotion_threshold = 0.1
        self.opponent_emotion = {}
        # New mechanism: replace reliability with a "forgiveness index" that
        # tracks how quickly we forgive past defections, weighted by recency.
        self.forgiveness_index = {}
        self.forgiveness_decay = 0.9
        self.forgiveness_bonus = 0.15
        self.forgiveness_penalty = 0.25
        self.forgiveness_threshold = 0.5
        # New mechanism: track a "patience" trait that influences how much
        # we are willing to tolerate repeated defections before retaliating.
        self.patience = 0.5
        self.patience_update_rate = 0.05
        self.patience_min = 0.1
        self.patience_max = 0.9
        self.defection_streak = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)
        combined = 0.6 * opp_rep + 0.4 * trust

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # New mechanism: use forgiveness index instead of reliability
        forgiveness_value = self.forgiveness_index.get(opponent, 0.5)
        # If forgiveness is high, we are more willing to cooperate despite past defections
        combined += (forgiveness_value - self.forgiveness_threshold) * 0.4

        # New mechanism: patience directly affects retaliation
        # Higher patience means we tolerate more defections before retaliating
        if opponent in self.defection_streak:
            streak = self.defection_streak[opponent]
            if streak > 0:
                # Reduce retaliation if we are patient
                reduced_retaliation = self.retaliation * (1.0 - (self.patience - self.patience_min) / (self.patience_max - self.patience_min))
                combined -= reduced_retaliation * streak * 0.5

        # Emotional modulation (kept from parent)
        opp_emotion = self.opponent_emotion.get(opponent, 0.0)
        emotional_bias = self.emotional_state * self.emotion_decay + opp_emotion * 0.5
        emotional_bias = max(-0.5, min(0.5, emotional_bias))
        combined += emotional_bias

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))

        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)
        self._update_opponent_coop_rate(donor_id, donor_action, recipient_id, recipient_action)

        # New mechanism: update forgiveness index instead of reliability
        self._update_forgiveness_index(donor_id, donor_action, recipient_id, recipient_action)

        # New mechanism: update patience based on own actions
        if donor_id == self.agent_id:
            self._update_patience(donor_action)
        if recipient_id == self.agent_id:
            self._update_patience(recipient_action)

        # Update defection streaks
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'defect':
                self.defection_streak[agent_id] = self.defection_streak.get(agent_id, 0) + 1
            else:
                self.defection_streak[agent_id] = 0

        # Emotional state update (kept from parent)
        self.emotional_state *= self.emotion_decay
        if donor_action == 'cooperate':
            self.emotional_state = min(1.0, self.emotional_state + 0.1)
        else:
            self.emotional_state = max(-1.0, self.emotional_state - 0.15)
        if recipient_action == 'cooperate':
            self.emotional_state = min(1.0, self.emotional_state + 0.05)
        else:
            self.emotional_state = max(-1.0, self.emotional_state - 0.05)

        delta = 0.1 if donor_action == 'cooperate' else -0.15
        self.opponent_emotion[donor_id] = self.opponent_emotion.get(donor_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[donor_id] = max(-1.0, min(1.0, self.opponent_emotion[donor_id]))

        delta = 0.05 if recipient_action == 'cooperate' else -0.05
        self.opponent_emotion[recipient_id] = self.opponent_emotion.get(recipient_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[recipient_id] = max(-1.0, min(1.0, self.opponent_emotion[recipient_id]))

    def _update_patience(self, action: str) -> None:
        # Adjust patience based on our own actions
        # If we cooperate, we become slightly more patient
        # If we defect, we become slightly less patient
        if action == 'cooperate':
            self.patience = min(self.patience_max, self.patience + self.patience_update_rate)
        else:
            self.patience = max(self.patience_min, self.patience - self.patience_update_rate)

    def _update_forgiveness_index(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay forgiveness for all agents periodically
        for agent in list(self.forgiveness_index.keys()):
            self.forgiveness_index[agent] *= self.forgiveness_decay
            if self.forgiveness_index[agent] < 0.01:
                del self.forgiveness_index[agent]

        # Update forgiveness based on cooperation/defection
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.forgiveness_index:
                self.forgiveness_index[agent_id] = 0.5
            if action == 'cooperate':
                self.forgiveness_index[agent_id] = min(1.0, self.forgiveness_index[agent_id] + self.forgiveness_bonus)
            else:
                self.forgiveness_index[agent_id] = max(0.0, self.forgiveness_index[agent_id] - self.forgiveness_penalty)

    def _update_opponent_coop_rate(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.opponent_coop_rate:
                self.opponent_coop_rate[agent_id] = 0.5
            alpha = 0.1
            if action == 'cooperate':
                self.opponent_coop_rate[agent_id] = (1 - alpha) * self.opponent_coop_rate[agent_id] + alpha * 1.0
            else:
                self.opponent_coop_rate[agent_id] = (1 - alpha) * self.opponent_coop_rate[agent_id] + alpha * 0.0

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        self.reputation[agent_id] *= self.reputation_decay
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = deque(maxlen=self.memory * 3)
        self.interactions[opp_id].append((my_action, opp_action))

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        self.total_interactions += 1

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - 0.05)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + 0.02)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - 0.05)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + 0.02)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.partner_reputation:
            self.partner_reputation[recipient_id] = {'coop': 0, 'defect': 0}

        if donor_action == 'cooperate':
            self.partner_reputation[donor_id]['coop'] += 1
