        self.observation_decay = 0.98
        # New: parameter to weight direct vs observed information
        self.direct_weight = 0.7
        self.observed_weight = 0.3

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        combined = self.rep_weight * opp_rep + self.trust_weight * trust

        uncertainty = self.rep_uncertainty.get(opponent, 0.5)
        combined = combined * (1.0 - uncertainty * 0.25)

        # Use recent interactions with more weight, but mix with long-term reputation
        if opponent in self.interactions:
            recent = self.interactions[opponent][-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                # Blend recent behavior with reputation, emphasize direct observations
                combined = (1 - self.direct_weight) * combined + self.direct_weight * coop_rate

        # Trust-based threshold adaptation
        threshold = self.trust_threshold

        # Retaliation for recent defections
        if opponent in self.interactions:
            recent = self.interactions[opponent][-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation

        # Forgiveness for consistent cooperation
        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # Reciprocity mechanism using a window
        if opponent in self.reciprocity_window:
            window = self.reciprocity_window[opponent]
            if len(window) > 0:
                coop_rate = sum(1 for a in window if a == 'cooperate') / len(window)
                if coop_rate > 0.5:
                    combined += 0.15

        # Penalty for high defect rate
        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            if len(recent) > 0:
                defect_rate = sum(1 for a, b in recent if b == 'defect') / len(recent)
                if defect_rate > 0.6:
                    combined -= 0.2

        # Exploration: add a short-term pattern detection - if the opponent defected last time, be more cautious
        if opponent in self.interactions and self.interactions[opponent]:
