            self._update_reputation(donor_id, donor_action, weight=1.0)
            self._update_reputation(recipient_id, recipient_action, weight=1.0)
        else:
            # Observed interaction: weaker update
            self._update_reputation(donor_id, donor_action, weight=self.observed_weight)
            self._update_reputation(recipient_id, recipient_action, weight=self.observed_weight)

