        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty * weight)
            self.rep_uncertainty[agent_id] = min(1.0, self.rep_uncertainty[agent_id] + self.uncertainty_increase * weight)

