                self.recent_opponent_actions.append(recipient_coop)

                if donor_coop and not recipient_coop:
                    self.losses += 1
                    self.opponent_defect_streak += 1
                elif not donor_coop and recipient_coop:
                    self.wins += 1
                    self.opponent_defect_streak = 0
                else:
                    self.opponent_defect_streak = 0

            elif recipient_id == self.agent_id:
                self.own_history.append((recipient_coop, donor_id, donor_coop))
                if len(self.own_history) > self.max_memory:
                    self.own_history = self.own_history[-self.max_memory:]
                self.recent_own_actions.append(recipient_coop)
                self.own_outcomes.append(recipient_coop and donor_coop)

                if donor_id not in self.interactions:
                    self.interactions[donor_id] = []
                self.interactions[donor_id].append((recipient_coop, donor_coop))
                if len(self.interactions[donor_id]) > 20:
                    self.interactions[donor_id] = self.interactions[donor_id][-20:]

                self.recent_opponent_actions.append(donor_coop)

                if recipient_coop and not donor_coop:
                    self.losses += 1
                    self.opponent_defect_streak += 1
                elif not recipient_coop and donor_coop:
                    self.wins += 1
                    self.opponent_defect_streak = 0
                else:
                    self.opponent_defect_streak = 0

            # Adjust threshold based on population behavior but with a slower response
            if len(self.observations) % 15 == 0 and len(self.observations) > 0:
                total_actions = len(self.observations) * 2
                coop_actions = sum(1 for _, dc, _, rc in self.observations if dc) + sum(1 for _, _, _, rc in self.observations if rc)
                pop_rate = coop_actions / total_actions if total_actions > 0 else 0.5
                # Only adjust slightly, keep threshold stable
                self.coop_threshold = self.coop_threshold * 0.9 + 0.1 * (0.5 - (pop_rate - 0.5) * 0.2)
                self.coop_threshold = max(0.2, min(0.8, self.coop_threshold))

        except Exception:
            pass

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        self.streak = {}
        self.streak_bonus = 0.15
        self.streak_threshold = 3
        # Child-specific: use a different uncertainty mechanism based on variance of recent actions
        self.action_history = {}  # agent_id -> deque of recent actions
        self.action_history_len = 10  # window for variance calculation
        self.variance_threshold = 0.25  # high variance threshold
        self.variance_penalty = 0.15  # penalty when variance is high
        self.variance_bonus = 0.1  # bonus when variance is low
        self.uncertainty = {}  # simplified uncertainty based on variance
        # Child-specific: add a "reputation trend" that uses linear regression slope over history
        self.rep_history = {}  # agent_id -> deque of (timestamp, reputation)
        self.rep_history_len = 8  # window for slope calculation
        self.slope_amplification = 0.2  # how much slope affects decisions
        # Child-specific: adjust retaliation to be more forgiving if opponent's reputation is improving
        self.retaliation_adjustment = 0.1  # reduction in retaliation when reputation improving
        # Child-specific: add a "recent_own_outcomes" deque for reactive adjustments
        self.recent_own_outcomes = deque(maxlen=5)
        # Child-specific: add a "cooperation_momentum" that increases after mutual cooperation
        self.cooperation_momentum = 0.0
        self.momentum_increment = 0.05
        self.momentum_decay = 0.9
        # Child-specific: add a trend-based credit assignment that rewards cooperation when reputation is rising
        self.trend_credit = {}  # agent_id -> float, positive when reputation improving

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        combined = 0.6 * opp_rep + 0.4 * trust

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        # Child-specific: use variance-based uncertainty to adjust threshold
        if opponent in self.action_history:
            actions = list(self.action_history[opponent])
            if len(actions) >= 4:
                coop_count = sum(1 for a in actions if a == 'cooperate')
                p = coop_count / len(actions)
                variance = p * (1 - p)
                if variance > self.variance_threshold:
                    threshold += self.variance_penalty  # more cautious with unpredictable opponents
                else:
                    threshold -= self.variance_bonus  # more willing with predictable opponents
                self.uncertainty[opponent] = variance
            else:
                self.uncertainty[opponent] = 0.5  # default moderate uncertainty

        # Child-specific: use linear regression slope of reputation history to detect trends
        if opponent in self.rep_history:
            history = list(self.rep_history[opponent])
            if len(history) >= 3:
                # Compute slope using simple linear regression
                n = len(history)
                x_mean = sum(t for t, r in history) / n
                y_mean = sum(r for t, r in history) / n
                numerator = sum((t - x_mean) * (r - y_mean) for t, r in history)
                denominator = sum((t - x_mean) ** 2 for t, r in history)
                if denominator > 0:
                    slope = numerator / denominator
                    # If reputation improving, be more cooperative; if declining, be more cautious
                    combined += self.slope_amplification * slope

        # Child-specific: adjust retaliation based on reputation trend
        if opponent in self.rep_history:
            history = list(self.rep_history[opponent])
            if len(history) >= 3:
                n = len(history)
                x_mean = sum(t for t, r in history) / n
                y_mean = sum(r for t, r in history) / n
                numerator = sum((t - x_mean) * (r - y_mean) for t, r in history)
                denominator = sum((t - x_mean) ** 2 for t, r in history)
                if denominator > 0:
                    slope = numerator / denominator
                    if slope > 0:
                        # If reputation improving, reduce retaliation
                        self.retaliation_adjustment = max(0.0, self.retaliation_adjustment - 0.01)
                    else:
                        self.retaliation_adjustment = min(0.2, self.retaliation_adjustment + 0.01)

        # Retaliation logic with adjustment
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation * (1 - self.retaliation_adjustment)

        # Forgiveness logic (same as parent)
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # Streak logic (same as parent)
        if opponent in self.streak:
            streak_type, streak_len = self.streak[opponent]
            if streak_type == 'cooperate' and streak_len >= self.streak_threshold:
                combined += self.streak_bonus
            elif streak_type == 'defect' and streak_len >= self.streak_threshold:
                combined -= self.streak_bonus

        # Child-specific: incorporate cooperation momentum
        combined += self.cooperation_momentum

        # Child-specific: use recent own outcomes to adjust threshold
        if len(self.recent_own_outcomes) >= 3:
            defections = sum(1 for a, b in self.recent_own_outcomes if b == 'defect')
            if defections >= 2:
                threshold += 0.1
            else:
                threshold -= 0.05

        # Child-specific: incorporate trend credit - if opponent's reputation is rising, boost cooperation
        if opponent in self.trend_credit:
            combined += self.trend_credit[opponent]

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        self._update_streak(donor_id, donor_action)
        self._update_streak(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)

        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)

        # Child-specific: update action history for variance calculation
        if donor_id not in self.action_history:
            self.action_history[donor_id] = deque(maxlen=self.action_history_len)
        self.action_history[donor_id].append(donor_action)
        if recipient_id not in self.action_history:
            self.action_history[recipient_id] = deque(maxlen=self.action_history_len)
        self.action_history[recipient_id].append(recipient_action)

        # Child-specific: update reputation history for slope calculation
        self._update_rep_history(donor_id, donor_action)
        self._update_rep_history(recipient_id, recipient_action)

        # Child-specific: update cooperation momentum based on own interactions
        if donor_id == self.agent_id and recipient_action == 'cooperate':
            self.cooperation_momentum = min(1.0, self.cooperation_momentum + self.momentum_increment)
        elif recipient_id == self.agent_id and donor_action == 'cooperate':
            self.cooperation_momentum = min(1.0, self.cooperation_momentum + self.momentum_increment)
        else:
            self.cooperation_momentum *= self.momentum_decay

        # Child-specific: update trend credit based on reputation slope
        self._update_trend_credit(donor_id)
        self._update_trend_credit(recipient_id)

    def _update_reputation(self, agent_id: int, action: str) -> None:
