        history = list(self.rep_history[agent_id])
        if len(history) < 3:
            return
        n = len(history)
        x_mean = sum(t for t, r in history) / n
        y_mean = sum(r for t, r in history) / n
        numerator = sum((t - x_mean) * (r - y_mean) for t, r in history)
        denominator = sum((t - x_mean) ** 2 for t, r in history)
        if denominator == 0:
            slope = 0.0
        else:
            slope = numerator / denominator
        # Credit is positive if slope positive, negative otherwise; scale by amplification
        self.trend_credit[agent_id] = self.slope_amplification * slope

