                    # Action changed, increase volatility
                    self.volatility[agent_id] = min(1.0, self.volatility[agent_id] + self.volatility_increase)
                else:
                    # Same action, decrease volatility
                    self.volatility[agent_id] = max(0.0, self.volatility[agent_id] - self.volatility_decrease)
            self.last_known_actions[agent_id] = action

    def _update_opponent_coop_rate(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
