        if (action == 'cooperate' and current_rep > 0.5) or (action == 'defect' and current_rep < 0.5):
            # Action is consistent with reputation, increase confidence
            self.reputation_confidence[agent_id] = min(1.0, self.reputation_confidence[agent_id] + self.confidence_increment)
        else:
            # Action contradicts reputation, decrease confidence
            self.reputation_confidence[agent_id] = max(0.0, self.reputation_confidence[agent_id] - self.confidence_penalty * self.confidence_increment)

