        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        self.rep_weight = 0.9
        self.trust_weight = 0.1
        self.rep_decay = 0.95
        self.observation_trust_update = 0.05
        self.defect_penalty_obs = 0.12
        self.rep_uncertainty = {}
        self.uncertainty_decay = 0.9
        self.uncertainty_increase = 0.1
        # New: reciprocity memory to track how often we cooperate with each opponent
        self.reciprocity = {}
        self.reciprocity_threshold = 0.6
        # New: decay factor for reciprocity to make it more recent-focused
        self.reciprocity_decay = 0.9
        # New: add a sliding window for reputation updates to be more responsive
        self.reputation_window = {}
        self.window_size = 5
        self.window_decay = 0.8

        # NEW MECHANISM: A "generosity" trait that reduces the threshold for cooperation
        # but also makes the agent more forgiving of defections, at the cost of being
        # more likely to be exploited.
        self.generosity = 0.2  # Added to threshold baseline
        self.generosity_boost = 0.1  # Added to combined score before threshold
        self.generosity_forgiveness = 0.1  # Extra forgiveness for recent defections
        self.generosity_penalty = 0.05  # Extra penalty for opponents who defect a lot

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        combined = self.rep_weight * opp_rep + self.trust_weight * trust

        uncertainty = self.rep_uncertainty.get(opponent, 0.5)
        combined = combined * (1.0 - uncertainty * 0.3)

        if opponent in self.interactions:
            recent = self.interactions[opponent][-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.2 * combined + 0.8 * coop_rate

        # Generosity: increase the baseline threshold (making cooperation slightly less likely)
        threshold = 0.5 + self.generosity + (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = self.interactions[opponent][-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation
                # Generosity: extra forgiveness for recent defections
                combined += self.generosity_forgiveness

        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # New: reciprocity mechanism - if we've cooperated with this opponent a lot, boost cooperation
        if opponent in self.reciprocity:
            if self.reciprocity[opponent] >= self.reciprocity_threshold:
                combined += 0.15

        # New: add a penalty for opponents who defect often in recent memory, but with a softer touch
        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            if len(recent) > 0:
                defect_rate = sum(1 for a, b in recent if b == 'defect') / len(recent)
                if defect_rate > 0.6:
                    combined -= 0.1
                    # Generosity: extra penalty for chronic defectors
                    combined -= self.generosity_penalty

        # New: adjust based on reputation window - if recent reputation is significantly different, adapt
        if opponent in self.reputation_window:
            window = self.reputation_window[opponent]
            if len(window) > 0:
                avg_window = sum(window) / len(window)
                if avg_window < opp_rep - 0.2:
                    combined -= 0.1
                elif avg_window > opp_rep + 0.2:
                    combined += 0.1

        # Generosity: boost the combined score slightly, making cooperation more likely
        combined += self.generosity_boost

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)

        for agent in list(self.reputation.keys()):
            self.reputation[agent] = self.reputation[agent] * self.rep_decay
        for agent in list(self.rep_uncertainty.keys()):
            self.rep_uncertainty[agent] = self.rep_uncertainty[agent] * self.uncertainty_decay
        # New: decay reciprocity values to emphasize recent interactions
        for agent in list(self.reciprocity.keys()):
            self.reciprocity[agent] = self.reciprocity[agent] * self.reciprocity_decay
        # New: decay reputation window values
        for agent in list(self.reputation_window.keys()):
            self.reputation_window[agent] = [x * self.window_decay for x in self.reputation_window[agent]]

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
            self.rep_uncertainty[agent_id] = 0.5
            self.reputation_window[agent_id] = []
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
            self.rep_uncertainty[agent_id] = max(0.0, self.rep_uncertainty[agent_id] - self.uncertainty_increase)
            # New: add to reputation window
            self.reputation_window[agent_id].append(1.0)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)
            self.rep_uncertainty[agent_id] = min(1.0, self.rep_uncertainty[agent_id] + self.uncertainty_increase)
            # New: add to reputation window
            self.reputation_window[agent_id].append(0.0)
        # New: keep window size bounded
        if len(self.reputation_window[agent_id]) > self.window_size:
            self.reputation_window[agent_id] = self.reputation_window[agent_id][-self.window_size:]

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = []
        self.interactions[opp_id].append((my_action, opp_action))

        # New: track reciprocity - count how many times we cooperated with this opponent
        if opp_id not in self.reciprocity:
            self.reciprocity[opp_id] = 0
        if my_action == 'cooperate':
            self.reciprocity[opp_id] += 1

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        if opp_id not in self.rep_uncertainty:
            self.rep_uncertainty[opp_id] = 0.5
        self.rep_uncertainty[opp_id] = max(0.0, self.rep_uncertainty[opp_id] - 0.2)

        self.total_interactions += 1

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - self.defect_penalty_obs)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + self.observation_trust_update)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - self.defect_penalty_obs)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + self.observation_trust_update)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.partner_reputation:
            self.partner_reputation[recipient_id] = {'coop': 0, 'defect': 0}

        if donor_action == 'cooperate':
            self.partner_reputation[donor_id]['coop'] += 1
        else:
            self.partner_reputation[donor_id]['defect'] += 1

        if recipient_action == 'cooperate':
            self.partner_reputation[recipient_id]['coop'] += 1
        else:
            self.partner_reputation[recipient_id]['defect'] += 1

        if donor_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1
        if recipient_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round = 0
        self.generation = 1
        self.scores = {}  # agent_id -> total cooperation score (higher = more cooperative)
        self.my_history = []  # list of (opponent_id, my_action, opp_action)
        self.opponent_history = {}  # opponent_id -> list of (my_action, opp_action)
        self.trust = {}  # agent_id -> trust value (0 to 1), default 0.5
        self.punish_threshold = 0.3
        self.reward_threshold = 0.7
        self.forgiveness = 0.1
        self.coop_streak = 0
        self.recent_mine = []
        self.recent_opp = []

    def decide(self) -> bool:
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
            # No opponent, default to cooperate
            return True

        # Get trust for this opponent
        trust = self.trust.get(opp, 0.5)

        # If we've interacted before, use pattern
        if opp in self.opponent_history:
            history = self.opponent_history[opp]
            if history:
                # Last interaction with this opponent
                last_my, last_opp = history[-1]
                if last_opp == 'defect' and last_my == 'cooperate':
                    # They defected against our cooperation, punish
                    return False
                elif last_opp == 'cooperate' and last_my == 'defect':
                    # We defected but they cooperated, maybe forgive
                    if random.random() < self.forgiveness:
                        return True
                    else:
                        return False
                elif last_opp == 'cooperate' and last_my == 'cooperate':
                    # Both cooperated, continue cooperating
                    return True
                else:
                    # Both defected, consider forgiveness occasionally
                    if random.random() < self.forgiveness * 0.5:
                        return True
                    else:
                        return False

        # If trust is high, cooperate
        if trust > self.reward_threshold:
            return True
        # If trust is low, defect
        if trust < self.punish_threshold:
            return False
        # Otherwise, base on recent overall behavior
        if len(self.recent_mine) >= 3:
            my_recent_coop = self.recent_mine[-3:].count('cooperate')
            opp_recent_coop = self.recent_opp[-3:].count('cooperate')
            if my_recent_coop >= 2 and opp_recent_coop >= 2:
                return True
            elif my_recent_coop <= 1 and opp_recent_coop <= 1:
                return False

        # Default to cooperate in uncertain situations
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update round/generation tracking
        self.round += 1
        if self.round % 30 == 0:
            self.generation += 1
            self.round = 0

        # Update scores for all observed agents
        for aid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.scores[aid] = self.scores.get(aid, 0) + 1
            else:
                self.scores[aid] = self.scores.get(aid, 0) - 1

        # If this involves us, update our personal history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            opp_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            opp_action = recipient_action if donor_id == self.agent_id else donor_action

            self.my_history.append((opp_id, my_action, opp_action))
            self.recent_mine.append(my_action)
            self.recent_opp.append(opp_action)
            if len(self.recent_mine) > 10:
                self.recent_mine.pop(0)
                self.recent_opp.pop(0)

            if opp_id not in self.opponent_history:
                self.opponent_history[opp_id] = []
            self.opponent_history[opp_id].append((my_action, opp_action))

            # Update trust based on interaction
            if my_action == 'cooperate' and opp_action == 'cooperate':
                self.trust[opp_id] = min(1.0, self.trust.get(opp_id, 0.5) + 0.1)
            elif my_action == 'defect' and opp_action == 'cooperate':
                self.trust[opp_id] = max(0.0, self.trust.get(opp_id, 0.5) - 0.05)
            elif my_action == 'cooperate' and opp_action == 'defect':
                self.trust[opp_id] = max(0.0, self.trust.get(opp_id, 0.5) - 0.15)
            else:
                self.trust[opp_id] = max(0.0, self.trust.get(opp_id, 0.5) - 0.1)

        # Third-party observation: update trust based on observed behavior
        else:
            # If both cooperate, increase trust for both
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.trust[donor_id] = min(1.0, self.trust.get(donor_id, 0.5) + 0.02)
                self.trust[recipient_id] = min(1.0, self.trust.get(recipient_id, 0.5) + 0.02)
            # If one defects, decrease trust for that one
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.trust[donor_id] = max(0.0, self.trust.get(donor_id, 0.5) - 0.05)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.trust[recipient_id] = max(0.0, self.trust.get(recipient_id, 0.5) - 0.05)
            # If both defect, decrease both
            else:
                self.trust[donor_id] = max(0.0, self.trust.get(donor_id, 0.5) - 0.03)
                self.trust[recipient_id] = max(0.0, self.trust.get(recipient_id, 0.5) - 0.03)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        self.streak = {}
        self.streak_bonus = 0.15
        self.streak_threshold = 3
        # Child-specific: use a different uncertainty mechanism based on variance of recent actions
        self.action_history = {}  # agent_id -> deque of recent actions
        self.action_history_len = 10  # window for variance calculation
        self.variance_threshold = 0.25  # high variance threshold
        self.variance_penalty = 0.15  # penalty when variance is high
        self.variance_bonus = 0.1  # bonus when variance is low
        self.uncertainty = {}  # simplified uncertainty based on variance
        # Child-specific: add a "reputation trend" that uses linear regression slope over history
        self.rep_history = {}  # agent_id -> deque of (timestamp, reputation)
        self.rep_history_len = 8  # window for slope calculation
        self.slope_amplification = 0.2  # how much slope affects decisions
        # Child-specific: adjust retaliation to be more forgiving if opponent's reputation is improving
        self.retaliation_adjustment = 0.1  # reduction in retaliation when reputation improving
        # Child-specific: add a "recent_own_outcomes" deque for reactive adjustments
        self.recent_own_outcomes = deque(maxlen=5)
        # Child-specific: add a "cooperation_momentum" that increases after mutual cooperation
        self.cooperation_momentum = 0.0
        self.momentum_increment = 0.05
        self.momentum_decay = 0.9
        # Child-specific: add a trend-based credit assignment that rewards cooperation when reputation is rising
        self.trend_credit = {}  # agent_id -> float, positive when reputation improving

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        combined = 0.6 * opp_rep + 0.4 * trust

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        # Child-specific: use variance-based uncertainty to adjust threshold
        if opponent in self.action_history:
            actions = list(self.action_history[opponent])
            if len(actions) >= 4:
                coop_count = sum(1 for a in actions if a == 'cooperate')
                p = coop_count / len(actions)
                variance = p * (1 - p)
                if variance > self.variance_threshold:
                    threshold += self.variance_penalty  # more cautious with unpredictable opponents
                else:
                    threshold -= self.variance_bonus  # more willing with predictable opponents
                self.uncertainty[opponent] = variance
            else:
                self.uncertainty[opponent] = 0.5  # default moderate uncertainty

        # Child-specific: use linear regression slope of reputation history to detect trends
        if opponent in self.rep_history:
            history = list(self.rep_history[opponent])
            if len(history) >= 3:
                # Compute slope using simple linear regression
                n = len(history)
                x_mean = sum(t for t, r in history) / n
                y_mean = sum(r for t, r in history) / n
                numerator = sum((t - x_mean) * (r - y_mean) for t, r in history)
                denominator = sum((t - x_mean) ** 2 for t, r in history)
                if denominator > 0:
                    slope = numerator / denominator
                    # If reputation improving, be more cooperative; if declining, be more cautious
                    combined += self.slope_amplification * slope

        # Child-specific: adjust retaliation based on reputation trend
        if opponent in self.rep_history:
            history = list(self.rep_history[opponent])
            if len(history) >= 3:
                n = len(history)
                x_mean = sum(t for t, r in history) / n
                y_mean = sum(r for t, r in history) / n
                numerator = sum((t - x_mean) * (r - y_mean) for t, r in history)
                denominator = sum((t - x_mean) ** 2 for t, r in history)
                if denominator > 0:
                    slope = numerator / denominator
                    if slope > 0:
                        # If reputation improving, reduce retaliation
                        self.retaliation_adjustment = max(0.0, self.retaliation_adjustment - 0.01)
                    else:
                        self.retaliation_adjustment = min(0.2, self.retaliation_adjustment + 0.01)

        # Retaliation logic with adjustment
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation * (1 - self.retaliation_adjustment)

        # Forgiveness logic (same as parent)
        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # Streak logic (same as parent)
        if opponent in self.streak:
            streak_type, streak_len = self.streak[opponent]
            if streak_type == 'cooperate' and streak_len >= self.streak_threshold:
                combined += self.streak_bonus
            elif streak_type == 'defect' and streak_len >= self.streak_threshold:
                combined -= self.streak_bonus

        # Child-specific: incorporate cooperation momentum
        combined += self.cooperation_momentum

        # Child-specific: use recent own outcomes to adjust threshold
        if len(self.recent_own_outcomes) >= 3:
            defections = sum(1 for a, b in self.recent_own_outcomes if b == 'defect')
            if defections >= 2:
                threshold += 0.1
            else:
                threshold -= 0.05

        # Child-specific: incorporate trend credit - if opponent's reputation is rising, boost cooperation
        if opponent in self.trend_credit:
            combined += self.trend_credit[opponent]

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        self._update_streak(donor_id, donor_action)
        self._update_streak(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)

        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)

        # Child-specific: update action history for variance calculation
        if donor_id not in self.action_history:
            self.action_history[donor_id] = deque(maxlen=self.action_history_len)
        self.action_history[donor_id].append(donor_action)
        if recipient_id not in self.action_history:
            self.action_history[recipient_id] = deque(maxlen=self.action_history_len)
        self.action_history[recipient_id].append(recipient_action)

        # Child-specific: update reputation history for slope calculation
        self._update_rep_history(donor_id, donor_action)
        self._update_rep_history(recipient_id, recipient_action)

        # Child-specific: update cooperation momentum based on own interactions
        if donor_id == self.agent_id and recipient_action == 'cooperate':
            self.cooperation_momentum = min(1.0, self.cooperation_momentum + self.momentum_increment)
        elif recipient_id == self.agent_id and donor_action == 'cooperate':
            self.cooperation_momentum = min(1.0, self.cooperation_momentum + self.momentum_increment)
        else:
            self.cooperation_momentum *= self.momentum_decay

        # Child-specific: update trend credit based on reputation slope
        self._update_trend_credit(donor_id)
        self._update_trend_credit(recipient_id)

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)

    def _update_streak(self, agent_id: int, action: str) -> None:
        if agent_id not in self.streak:
            self.streak[agent_id] = (action, 1)
        else:
            prev_type, prev_len = self.streak[agent_id]
            if prev_type == action:
                self.streak[agent_id] = (action, prev_len + 1)
            else:
