        self.observed_actions = {}
        # 5. Add a "recent_defector" flag to quickly adjust behavior after a defection.
        self.recent_defector = False
        # 6. Keep the parent's momentum but adjust sensitivity.
        self.recent_actions = deque(maxlen=5)
