                if self.consistent_coop_count[agent_id] >= 3:
                    self.suspicion = max(self.suspicion_min, self.suspicion - self.suspicion_update_rate)
            else:
                self.consistent_coop_count[agent_id] = 0
                self.suspicion = min(1.0, self.suspicion + self.suspicion_update_rate * 0.5)

    def _update_reciprocity(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay reciprocity for all agents periodically
        for agent in list(self.reciprocity.keys()):
            self.reciprocity[agent] *= self.reciprocity_decay
            if self.reciprocity[agent] < 0.01:
