                    # Match: increase reciprocity
                    self.reciprocity[donor_id] = min(1.0, self.reciprocity.get(donor_id, 0.0) + self.reciprocity_increase)
                else:
                    # Mismatch: decrease reciprocity
                    self.reciprocity[donor_id] = max(0.0, self.reciprocity.get(donor_id, 0.0) - self.reciprocity_decrease)
        else:
            # Initialize reciprocity for new agents
            if donor_id not in self.reciprocity:
