        # Only update if we have a record of our last action toward that opponent
        if donor_id in self.last_own_action and donor_id in self.last_opponent_action:
            # Check if the opponent's action matches our previous action toward them
            if donor_id in self.last_opponent_action:
                if donor_action == self.last_own_action[donor_id]:
