        self.grudge = {}
        self.emotional_state = 0.0
        self.emotion_decay = 0.9
        self.emotion_threshold = 0.1
        self.opponent_emotion = {}
        # New mechanism: track a "pattern" score for each opponent that
        # measures how predictable their behavior is. High pattern means
        # they tend to repeat their previous action.
        self.pattern = {}
        self.pattern_decay = 0.9
        self.pattern_increase = 0.2
        self.pattern_decrease = 0.1
        self.last_observed_action = {}
        self.last_own_action = {}
        self.last_opponent_action = {}
        # New mechanism: track a "cautiousness" trait that starts high and
        # decreases as we observe more interactions, making us more willing
        # to cooperate in uncertain situations.
        self.cautiousness = 0.8
        self.cautiousness_decay = 0.98
        self.cautiousness_min = 0.2
        self.cautiousness_update_rate = 0.01
        self.interaction_count = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)
        combined = 0.6 * opp_rep + 0.4 * trust

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                # Pattern mechanism: if the opponent is predictable, we can
                # better anticipate their next move. If they have a high
                # pattern score, we assume they will cooperate next time,
                # so we reduce retaliation. If pattern is low, we assume
                # they might defect again, so we increase retaliation.
                pattern_score = self.pattern.get(opponent, 0.0)
                if pattern_score > 0.5:
                    combined -= self.retaliation * (1.0 - pattern_score)
                else:
                    combined -= self.retaliation * (0.5 + (0.5 - pattern_score))

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # New mechanism: use pattern to modulate trust
        # High pattern means more predictable, so we trust more
        pattern_value = self.pattern.get(opponent, 0.0)
        combined += pattern_value * 0.3

        # New mechanism: cautiousness raises the threshold, making us less
        # willing to cooperate. As we gain more experience, cautiousness
        # decays, making us more cooperative over time.
        threshold += self.cautiousness * 0.1

        # Emotional modulation (kept from parent)
        opp_emotion = self.opponent_emotion.get(opponent, 0.0)
        emotional_bias = self.emotional_state * self.emotion_decay + opp_emotion * 0.5
        emotional_bias = max(-0.5, min(0.5, emotional_bias))
        combined += emotional_bias

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))

        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)
        self._update_opponent_coop_rate(donor_id, donor_action, recipient_id, recipient_action)

        # New mechanism: update pattern based on whether the agent repeats
        # its previous action
        self._update_pattern(donor_id, donor_action)
        self._update_pattern(recipient_id, recipient_action)

        # New mechanism: update cautiousness based on experience
        self._update_cautiousness()

        # Emotional state update (kept from parent)
        self.emotional_state *= self.emotion_decay
        if donor_action == 'cooperate':
            self.emotional_state = min(1.0, self.emotional_state + 0.1)
        else:
            self.emotional_state = max(-1.0, self.emotional_state - 0.15)
        if recipient_action == 'cooperate':
            self.emotional_state = min(1.0, self.emotional_state + 0.05)
        else:
            self.emotional_state = max(-1.0, self.emotional_state - 0.05)

        delta = 0.1 if donor_action == 'cooperate' else -0.15
        self.opponent_emotion[donor_id] = self.opponent_emotion.get(donor_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[donor_id] = max(-1.0, min(1.0, self.opponent_emotion[donor_id]))

        delta = 0.05 if recipient_action == 'cooperate' else -0.05
        self.opponent_emotion[recipient_id] = self.opponent_emotion.get(recipient_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[recipient_id] = max(-1.0, min(1.0, self.opponent_emotion[recipient_id]))

    def _update_cautiousness(self) -> None:
        # Decay cautiousness over time as we gain experience
        self.cautiousness = max(self.cautiousness_min, self.cautiousness * self.cautiousness_decay)

        # Slightly reduce cautiousness with each observation
        self.cautiousness = max(self.cautiousness_min, self.cautiousness - self.cautiousness_update_rate)
        self.interaction_count += 1

    def _update_pattern(self, agent_id: int, action: str) -> None:
        # Decay pattern for all agents periodically
        for agent in list(self.pattern.keys()):
            self.pattern[agent] *= self.pattern_decay
            if self.pattern[agent] < 0.01:
                del self.pattern[agent]

        # Update pattern based on whether the action matches the last observed action
        if agent_id in self.last_observed_action:
            if action == self.last_observed_action[agent_id]:
                # Match: increase pattern
                self.pattern[agent_id] = min(1.0, self.pattern.get(agent_id, 0.0) + self.pattern_increase)
            else:
                # Mismatch: decrease pattern
                self.pattern[agent_id] = max(0.0, self.pattern.get(agent_id, 0.0) - self.pattern_decrease)
        else:
            # Initialize pattern for new agents
            if agent_id not in self.pattern:
                self.pattern[agent_id] = 0.0

        # Store the action for future comparison
        self.last_observed_action[agent_id] = action

    def _update_opponent_coop_rate(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
