from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
