        self.window_size = 5
        self.window_decay = 0.8

        # NEW MECHANISM: A "skepticism" trait that decreases the impact of
        # observed actions and increases reliance on direct interactions.
        # This makes the agent more cautious about third-party information,
        # potentially leading to more exploitation but also less manipulation.
        self.skepticism = 0.3  # Reduces weight of observed reputation
        self.direct_interaction_bonus = 0.2  # Extra weight to direct interactions
        self.skepticism_trust_update = 0.02  # Lower trust updates from observations
        self.skepticism_rep_update = 0.1  # Lower reputation updates from observations

        # NEW MECHANISM: A "boldness" trait that scales the threshold perturbation.
        # Higher boldness means the agent makes more extreme decisions (either very cooperative or very defective)
        self.boldness = 0.3  # Scales the random threshold perturbation

        # NEW MECHANISM: A "grudge" memory that tracks past defections by each opponent,
        # with a longer memory than the standard interactions list.
