        self.predictability_increase = 0.2
        self.predictability_decrease = 0.2
        self.predictability_threshold = 0.5
        self.last_own_action = {}
        self.last_opponent_action = {}
        # Replaced suspicion with a "generosity" trait that starts moderate
        # and increases as we observe cooperation, making us more cooperative.
        self.generosity = 0.5
        self.generosity_boost = 0.01
        self.generosity_max = 0.9
        self.generosity_min = 0.1
        self.consistent_coop_count = {}
        # New mechanism: a "reputation_momentum" that accelerates reputation changes
        # based on recent trends, making the agent more responsive to streaks.
        self.reputation_momentum = {}
        self.momentum_decay = 0.9
        self.momentum_boost = 0.05
        self.momentum_threshold = 0.3
        # New mechanism: a "tit_for_tat" bias that increases cooperation if
        # the opponent cooperated last time we interacted, and decreases if defected.
        self.tit_for_tat = {}
        self.tft_initial = 0.0
        self.tft_increase = 0.1
        self.tft_decrease = 0.15
        # New mechanism: a "risk_aversion" trait that makes us more cautious
        # when we have low reputation with an opponent.
        self.risk_aversion = 0.3

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)
        combined = 0.6 * opp_rep + 0.4 * trust

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                # Predictability mechanism: instead of immediate retaliation,
                # we adjust based on how predictable the opponent is.
                # High predictability means they are consistent, so we retaliate less.
                pred_score = self.predictability.get(opponent, 0.0)
                if pred_score > self.predictability_threshold:
                    combined -= self.retaliation * (1.0 - pred_score)
                else:
                    combined -= self.retaliation * (0.5 + (self.predictability_threshold - pred_score))

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # New mechanism: use predictability to modulate trust
        # High predictability means they are more predictable, so we trust more
        pred_value = self.predictability.get(opponent, 0.0)
        combined += pred_value * 0.3

        # New mechanism: generosity lowers the threshold, making us more willing to cooperate
        # As generosity increases, we become more cooperative over time
        threshold -= self.generosity * 0.1

        # New mechanism: reputation momentum - if reputation is rising, be more cooperative
        momentum = self.reputation_momentum.get(opponent, 0.0)
        if momentum > self.momentum_threshold:
            combined += momentum * 0.2
        elif momentum < -self.momentum_threshold:
            combined -= abs(momentum) * 0.2

        # New mechanism: tit-for-tat bias - cooperate if last interaction was cooperative
        tft_bias = self.tit_for_tat.get(opponent, self.tft_initial)
        combined += tft_bias * 0.2

        # New mechanism: risk aversion - if opponent's reputation is low, be more cautious
        if opp_rep < 0.3:
            combined -= self.risk_aversion * (0.3 - opp_rep)

        # Emotional modulation (kept from parent)
        opp_emotion = self.opponent_emotion.get(opponent, 0.0)
        emotional_bias = self.emotional_state * self.emotion_decay + opp_emotion * 0.5
        emotional_bias = max(-0.5, min(0.5, emotional_bias))
        combined += emotional_bias

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))

