        if action == 'cooperate':
            self.reputation_momentum[agent_id] = min(1.0, self.reputation_momentum[agent_id] + self.momentum_boost)
        else:
            self.reputation_momentum[agent_id] = max(-1.0, self.reputation_momentum[agent_id] - self.momentum_boost)

