        # Update tit-for-tat bias based on the opponent's last action in our interaction
        if opp_action == 'cooperate':
            self.tit_for_tat[opponent_id] = min(1.0, self.tit_for_tat.get(opponent_id, self.tft_initial) + self.tft_increase)
        else:
