                self.generosity = max(self.generosity_min, self.generosity - self.generosity_boost * 0.5)

    def _update_predictability(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay predictability for all agents periodically
        for agent in list(self.predictability.keys()):
            self.predictability[agent] *= self.predictability_decay
            if self.predictability[agent] < 0.01:
                del self.predictability[agent]

