            # Check if the opponent's action matches our previous action toward them
            if donor_id in self.last_opponent_action:
                if donor_action == self.last_own_action[donor_id]:
                    # Match: increase predictability
                    self.predictability[donor_id] = min(1.0, self.predictability.get(donor_id, 0.0) + self.predictability_increase)
                else:
                    # Mismatch: decrease predictability
                    self.predictability[donor_id] = max(0.0, self.predictability.get(donor_id, 0.0) - self.predictability_decrease)
        else:
            # Initialize predictability for new agents
            if donor_id not in self.predictability:
                self.predictability[donor_id] = 0.0

        if recipient_id in self.last_own_action and recipient_id in self.last_opponent_action:
            if recipient_id in self.last_opponent_action:
                if recipient_action == self.last_own_action[recipient_id]:
                    self.predictability[recipient_id] = min(1.0, self.predictability.get(recipient_id, 0.0) + self.predictability_increase)
                else:
                    self.predictability[recipient_id] = max(0.0, self.predictability.get(recipient_id, 0.0) - self.predictability_decrease)
        else:
            if recipient_id not in self.predictability:
                self.predictability[recipient_id] = 0.0

        # Store the actions for future comparison
        if donor_id == self.agent_id:
            self.last_own_action[recipient_id] = donor_action
            self.last_opponent_action[recipient_id] = recipient_action
        elif recipient_id == self.agent_id:
            self.last_own_action[donor_id] = recipient_action
            self.last_opponent_action[donor_id] = donor_action

    def _update_opponent_coop_rate(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
