        self.skepticism_trust_update = 0.02  # Lower trust updates from observations
        self.skepticism_rep_update = 0.1  # Lower reputation updates from observations

        # NEW MECHANISM: A "boldness" trait that scales the threshold perturbation.
        # Higher boldness means the agent makes more extreme decisions (either very cooperative or very defective)
        self.boldness = 0.3  # Scales the random threshold perturbation

