        if opponent in self.reciprocity:
            if self.reciprocity[opponent] >= self.reciprocity_threshold:
                combined += 0.15

        # Mutation: softer penalty for occasional defections - only penalize if defection rate is above threshold
        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            if len(recent) > 0:
                defect_rate = sum(1 for a, b in recent if b == 'defect') / len(recent)
                if defect_rate > self.reciprocity_penalty_threshold:
                    combined -= 0.1 * (defect_rate - self.reciprocity_penalty_threshold)

