        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        if opp_id not in self.rep_uncertainty:
            self.rep_uncertainty[opp_id] = 0.5
        self.rep_uncertainty[opp_id] = max(0.0, self.rep_uncertainty[opp_id] - 0.2)

        self.total_interactions += 1

        # Mutation: track own outcome for performance-based threshold adjustment
        outcome = 1 if (my_action == 'cooperate' and opp_action == 'cooperate') else 0
        self.recent_own_outcomes.append(outcome)
        if len(self.recent_own_outcomes) > 10:
            self.recent_own_outcomes.pop(0)
        if len(self.recent_own_outcomes) > 0:
            avg_outcome = sum(self.recent_own_outcomes) / len(self.recent_own_outcomes)
            # If we are doing poorly (low mutual cooperation), lower threshold to be more cooperative
            target_adjustment = (0.5 - avg_outcome) * self.performance_threshold_rate
            self.performance_threshold_adjustment += (target_adjustment - self.performance_threshold_adjustment) * 0.1

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
