        self.skepticism = 0.3  # Reduces weight of observed reputation
        self.direct_interaction_bonus = 0.2  # Extra weight to direct interactions
        self.skepticism_trust_update = 0.02  # Lower trust updates from observations
        self.skepticism_rep_update = 0.1  # Lower reputation updates from observations

