                if len(reps) >= 2:
                    change = abs(reps[-1] - reps[-2])
                    # Update volatility with exponential smoothing
                    self.reputation_volatility[agent_id] = (1 - self.volatility_alpha) * self.reputation_volatility[agent_id] + self.volatility_alpha * change

