        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        # Skepticism: reduce weight of reputation (which is largely observation-based)
        combined = (self.rep_weight * (1 - self.skepticism)) * opp_rep + self.trust_weight * trust

        uncertainty = self.rep_uncertainty.get(opponent, 0.5)
        combined = combined * (1.0 - uncertainty * 0.3)

        if opponent in self.interactions:
            recent = self.interactions[opponent][-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                # Skepticism: give more weight to direct interactions
                combined = (1 - self.skepticism) * combined + (self.skepticism + self.direct_interaction_bonus) * coop_rate

        # Boldness: scale the random threshold perturbation
        threshold = 0.5 + (random.random() - 0.5) * self.boldness

        if opponent in self.interactions:
            recent = self.interactions[opponent][-3:]
            if any(b == 'defect' for a, b in recent):
