        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        self.reputation_decay = 0.95
        self.recent_observations = deque(maxlen=50)
        self.opponent_coop_rate = {}
        self.threshold_adjustment = 0.0
        self.grudge = {}
        self.emotional_state = 0.0
        self.emotion_decay = 0.9
        self.emotion_threshold = 0.1
        self.opponent_emotion = {}
        # New mechanism: replace trend with "volatility" tracking
        # Volatility measures how erratic an opponent's behavior is
        self.volatility = {}
        self.volatility_decay = 0.9
        self.volatility_increase = 0.2
        self.volatility_decrease = 0.05
        self.volatility_threshold = 0.3
        self.last_own_action = {}
        self.last_opponent_action = {}
        # New mechanism: track a "reputation_instability" that increases when reputation changes rapidly
        # High instability means the agent's reputation is unreliable, so we trust less
        self.reputation_instability = {}
        self.instability_decay = 0.85
        self.instability_increase = 0.1
        self.instability_decrease = 0.03
        self.consistent_coop_count = {}
        # New mechanism: suspicion as a global attribute (initialized separately)
        self.suspicion = 0.0
        self.suspicion_min = -1.0
        self.suspicion_decay = 0.95
        self.suspicion_update_rate = 0.1

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)
        combined = 0.6 * opp_rep + 0.4 * trust

        # New mechanism: incorporate reputation instability into decision
        instability = self.reputation_instability.get(opponent, 0.0)
        combined -= instability * 0.3

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                # Volatility mechanism: adjust retaliation based on how erratic the opponent is
                vol_value = self.volatility.get(opponent, 0.0)
                if vol_value > self.volatility_threshold:
                    combined -= self.retaliation * (1.0 + vol_value)
                elif vol_value < -self.volatility_threshold:
                    combined -= self.retaliation * (1.0 - vol_value)
                else:
                    combined -= self.retaliation * 0.5

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        # New mechanism: use volatility to modulate trust
        # High volatility makes us more cautious, reducing cooperation
        vol_value = self.volatility.get(opponent, 0.0)
        combined -= vol_value * 0.2

        # New mechanism: suspicion raises the threshold, making us less willing to cooperate
        # As suspicion decays, we become more cooperative over time
        threshold += self.suspicion * 0.1

        # Emotional modulation (kept from parent)
        opp_emotion = self.opponent_emotion.get(opponent, 0.0)
        emotional_bias = self.emotional_state * self.emotion_decay + opp_emotion * 0.5
        emotional_bias = max(-0.5, min(0.5, emotional_bias))
        combined += emotional_bias

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))

        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)
        self._update_opponent_coop_rate(donor_id, donor_action, recipient_id, recipient_action)

        # New mechanism: update volatility based on changes in opponent behavior
        self._update_volatility(donor_id, donor_action, recipient_id, recipient_action)

        # New mechanism: update reputation instability based on reputation changes
        self._update_reputation_instability(donor_id, donor_action, recipient_id, recipient_action)

        # New mechanism: update suspicion based on consistent cooperation
        self._update_suspicion(donor_id, donor_action, recipient_id, recipient_action)

        # Emotional state update (kept from parent)
        self.emotional_state *= self.emotion_decay
        if donor_action == 'cooperate':
            self.emotional_state = min(1.0, self.emotional_state + 0.1)
        else:
            self.emotional_state = max(-1.0, self.emotional_state - 0.15)
        if recipient_action == 'cooperate':
            self.emotional_state = min(1.0, self.emotional_state + 0.05)
        else:
            self.emotional_state = max(-1.0, self.emotional_state - 0.05)

        delta = 0.1 if donor_action == 'cooperate' else -0.15
        self.opponent_emotion[donor_id] = self.opponent_emotion.get(donor_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[donor_id] = max(-1.0, min(1.0, self.opponent_emotion[donor_id]))

        delta = 0.05 if recipient_action == 'cooperate' else -0.05
        self.opponent_emotion[recipient_id] = self.opponent_emotion.get(recipient_id, 0.0) * self.emotion_decay + delta
        self.opponent_emotion[recipient_id] = max(-1.0, min(1.0, self.opponent_emotion[recipient_id]))

    def _update_suspicion(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay suspicion over time
        self.suspicion = max(self.suspicion_min, self.suspicion * self.suspicion_decay)

        # If we see consistent cooperation from an agent, reduce suspicion
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.consistent_coop_count:
                self.consistent_coop_count[agent_id] = 0
            if action == 'cooperate':
                self.consistent_coop_count[agent_id] += 1
                if self.consistent_coop_count[agent_id] >= 3:
                    self.suspicion = max(self.suspicion_min, self.suspicion - self.suspicion_update_rate)
            else:
                self.consistent_coop_count[agent_id] = 0
                self.suspicion = min(1.0, self.suspicion + self.suspicion_update_rate * 0.5)

    def _update_volatility(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay volatility for all agents
        for agent in list(self.volatility.keys()):
            self.volatility[agent] *= self.volatility_decay
            if abs(self.volatility[agent]) < 0.01:
                del self.volatility[agent]

        # Update volatility based on comparison of current action to previous action
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id in self.last_opponent_action:
                prev_action = self.last_opponent_action[agent_id]
                if action != prev_action:
                    # Behavior changed: increase volatility
                    self.volatility[agent_id] = min(1.0, self.volatility.get(agent_id, 0.0) + self.volatility_increase)
                else:
                    # Behavior consistent: decrease volatility
                    self.volatility[agent_id] = max(0.0, self.volatility.get(agent_id, 0.0) - self.volatility_decrease)
            else:
                # Initialize volatility for new agents
                if agent_id not in self.volatility:
                    self.volatility[agent_id] = 0.0

        # Store the actions for future comparison
        if donor_id == self.agent_id:
            self.last_own_action[recipient_id] = donor_action
            self.last_opponent_action[recipient_id] = recipient_action
        elif recipient_id == self.agent_id:
            self.last_own_action[donor_id] = recipient_action
            self.last_opponent_action[donor_id] = donor_action
        else:
            # For third-party observations, update last_opponent_action for both
            self.last_opponent_action[donor_id] = donor_action
            self.last_opponent_action[recipient_id] = recipient_action

    def _update_reputation_instability(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Decay instability for all agents
        for agent in list(self.reputation_instability.keys()):
            self.reputation_instability[agent] *= self.instability_decay
            if abs(self.reputation_instability[agent]) < 0.01:
                del self.reputation_instability[agent]

        # Update instability based on reputation changes
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            prev_rep = self.reputation.get(agent_id, 0.5)
            # After _update_reputation, we can compute the change
            new_rep = self.reputation.get(agent_id, 0.5)
            rep_change = abs(new_rep - prev_rep)
            if rep_change > 0.05:
                # Large reputation change: increase instability
                self.reputation_instability[agent_id] = min(1.0, self.reputation_instability.get(agent_id, 0.0) + self.instability_increase)
            else:
                # Small change: decrease instability
                self.reputation_instability[agent_id] = max(0.0, self.reputation_instability.get(agent_id, 0.0) - self.instability_decrease)

    def _update_opponent_coop_rate(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.opponent_coop_rate:
                self.opponent_coop_rate[agent_id] = 0.5
            alpha = 0.1
            if action == 'cooperate':
                self.opponent_coop_rate[agent_id] = (1 - alpha) * self.opponent_coop_rate[agent_id] + alpha * 1.0
            else:
                self.opponent_coop_rate[agent_id] = (1 - alpha) * self.opponent_coop_rate[agent_id] + alpha * 0.0

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        self.reputation[agent_id] *= self.reputation_decay
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = deque(maxlen=self.memory * 3)
        self.interactions[opp_id].append((my_action, opp_action))

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        self.total_interactions += 1

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - 0.05)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + 0.02)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - 0.05)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + 0.02)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.partner_reputation:
            self.partner_reputation[recipient_id] = {'coop': 0, 'defect': 0}

        if donor_action == 'cooperate':
            self.partner_reputation[donor_id]['coop'] += 1
        else:
            self.partner_reputation[donor_id]['defect'] += 1

        if recipient_action == 'cooperate':
            self.partner_reputation[recipient_id]['coop'] += 1
        else:
            self.partner_reputation[recipient_id]['defect'] += 1

        if donor_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1
        if recipient_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        self.rep_weight = 0.9
        self.trust_weight = 0.1
        self.rep_decay = 0.95
        self.observation_trust_update = 0.05
        self.defect_penalty_obs = 0.12
        self.rep_uncertainty = {}
        self.uncertainty_decay = 0.9
        self.uncertainty_increase = 0.1
        # New: reciprocity memory to track how often we cooperate with each opponent
        self.reciprocity = {}
        self.reciprocity_threshold = 0.6
        # New: decay factor for reciprocity to make it more recent-focused
        self.reciprocity_decay = 0.9
        # Mutation: replace global bias with a per-opponent behavioral consistency score
        self.consistency = {}
        self.consistency_decay = 0.95
        self.consistency_alpha = 0.2
        # New: track a personal reputation (self-image) that influences decisions
        self.self_reputation = 0.5
        self.self_rep_inertia = 0.9
        # Mutation: add a forgiveness cap to limit how much forgiveness can be applied
        self.forgiveness_cap = 0.15
        # Mutation: add a threshold for when to use forgiveness based on partner's cooperation count
        self.forgiveness_coop_threshold = 3

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        combined = self.rep_weight * opp_rep + self.trust_weight * trust

        uncertainty = self.rep_uncertainty.get(opponent, 0.5)
        combined = combined * (1.0 - uncertainty * 0.3)

        if opponent in self.interactions:
            recent = self.interactions[opponent][-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.2 * combined + 0.8 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = self.interactions[opponent][-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation

        # Mutation: forgiveness is now capped and requires a minimum number of partner cooperations
        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= self.forgiveness_coop_threshold and combined > 0.4:
                combined += min(self.forgiveness, self.forgiveness_cap)

        # New: reciprocity mechanism - if we've cooperated with this opponent a lot, boost cooperation
        if opponent in self.reciprocity:
            if self.reciprocity[opponent] >= self.reciprocity_threshold:
                combined += 0.15

        # New: add a penalty for opponents who defect often in recent memory, but with a softer touch
        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            if len(recent) > 0:
                defect_rate = sum(1 for a, b in recent if b == 'defect') / len(recent)
                if defect_rate > 0.6:
                    combined -= 0.1

        # Mutation: incorporate consistency - if opponent's behavior is predictable, adjust confidence
        if opponent in self.consistency:
            consistency = self.consistency[opponent]
            # High consistency (near 1) means predictable; low means unpredictable
            if consistency > 0.7:
                combined += 0.05 * (combined - 0.5)  # Amplify existing tendency
            elif consistency < 0.3:
                combined -= 0.05 * (combined - 0.5)  # Dampen tendency

        # Mutation: incorporate self_reputation - if we see ourselves as cooperative, be more cooperative
        combined += (self.self_reputation - 0.5) * 0.1

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)

        # Mutation: update consistency scores for the observed agents
        self._update_consistency(donor_id, donor_action)
        self._update_consistency(recipient_id, recipient_action)

        # Mutation: update self-reputation based on our own actions
        if donor_id == self.agent_id:
            self._update_self_reputation(donor_action)
        if recipient_id == self.agent_id:
            self._update_self_reputation(recipient_action)

        for agent in list(self.reputation.keys()):
            self.reputation[agent] = self.reputation[agent] * self.rep_decay
        for agent in list(self.rep_uncertainty.keys()):
            self.rep_uncertainty[agent] = self.rep_uncertainty[agent] * self.uncertainty_decay
        # New: decay reciprocity values to emphasize recent interactions
        for agent in list(self.reciprocity.keys()):
            self.reciprocity[agent] = self.reciprocity[agent] * self.reciprocity_decay
        # Mutation: decay consistency scores
        for agent in list(self.consistency.keys()):
            self.consistency[agent] = self.consistency[agent] * self.consistency_decay

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
            self.rep_uncertainty[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
            self.rep_uncertainty[agent_id] = max(0.0, self.rep_uncertainty[agent_id] - self.uncertainty_increase)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)
            self.rep_uncertainty[agent_id] = min(1.0, self.rep_uncertainty[agent_id] + self.uncertainty_increase)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = []
        self.interactions[opp_id].append((my_action, opp_action))

        # New: track reciprocity - count how many times we cooperated with this opponent
        if opp_id not in self.reciprocity:
            self.reciprocity[opp_id] = 0
        if my_action == 'cooperate':
            self.reciprocity[opp_id] += 1

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        if opp_id not in self.rep_uncertainty:
            self.rep_uncertainty[opp_id] = 0.5
        self.rep_uncertainty[opp_id] = max(0.0, self.rep_uncertainty[opp_id] - 0.2)

        self.total_interactions += 1

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - self.defect_penalty_obs)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + self.observation_trust_update)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - self.defect_penalty_obs)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + self.observation_trust_update)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.partner_reputation:
            self.partner_reputation[recipient_id] = {'coop': 0, 'defect': 0}

        if donor_action == 'cooperate':
            self.partner_reputation[donor_id]['coop'] += 1
        else:
            self.partner_reputation[donor_id]['defect'] += 1

        if recipient_action == 'cooperate':
            self.partner_reputation[recipient_id]['coop'] += 1
        else:
            self.partner_reputation[recipient_id]['defect'] += 1

        if donor_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1
        if recipient_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1

    def _update_consistency(self, agent_id: int, action: str) -> None:
        # Track the fraction of cooperate actions observed for this agent
        if agent_id not in self.consistency:
            self.consistency[agent_id] = 0.5
        # Simple moving average: alpha * (action_code) + (1-alpha) * previous
        action_code = 1 if action == 'cooperate' else 0
        self.consistency[agent_id] = (1 - self.consistency_alpha) * self.consistency[agent_id] + self.consistency_alpha * action_code

