    def _update_consistency(self, agent_id: int, action: str) -> None:
        # Track the fraction of cooperate actions observed for this agent
        if agent_id not in self.consistency:
            self.consistency[agent_id] = 0.5
        # Simple moving average: alpha * (action_code) + (1-alpha) * previous
        action_code = 1 if action == 'cooperate' else 0
        self.consistency[agent_id] = (1 - self.consistency_alpha) * self.consistency[agent_id] + self.consistency_alpha * action_code

    def _update_self_reputation(self, action: str) -> None:
        # Update self-image based on our own actions
        target = 1.0 if action == 'cooperate' else 0.0
        self.self_reputation = self.self_rep_inertia * self.self_reputation + (1 - self.self_rep_inertia) * target
        # Keep in [0,1]
        self.self_reputation = max(0.0, min(1.0, self.self_reputation))

    def _adapt_tolerance(self) -> None:
        # Adjust tolerance based on global cooperation rate
        total_actions = self.global_coop_count + self.global_defect_count
        if total_actions > 0:
            coop_rate = self.global_coop_count / total_actions
            # If cooperation is high, increase tolerance (be more willing to cooperate)
            # If defection is high, decrease tolerance (be more cautious)
            target_tolerance = 0.5 + (coop_rate - 0.5) * 2  # Map coop_rate 0->0, 0.5->0.5, 1->1
            # Clamp to min/max
            target_tolerance = max(self.tolerance_min, min(self.tolerance_max, target_tolerance))
            # Smooth adaptation
            self.tolerance += self.tolerance_adaptation_rate * (target_tolerance - self.tolerance)
            # Clamp again
            self.tolerance = max(self.tolerance_min, min(self.tolerance_max, self.tolerance))

    def _update_forgiveness_memory(self, agent_id: int, action: str) -> None:
        # Track recent defections; if the agent cooperates, reduce the count
        if agent_id not in self.forgiveness_memory:
            self.forgiveness_memory[agent_id] = 0
        if action == 'defect':
            self.forgiveness_memory[agent_id] += 1
        else:
            # Reduce the count when they cooperate (forgiving)
            self.forgiveness_memory[agent_id] = max(0, self.forgiveness_memory[agent_id] - 1)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
