        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= self.forgiveness_coop_threshold and combined > 0.4:
                combined += min(self.forgiveness, self.forgiveness_cap)

        if opponent in self.reciprocity:
            if self.reciprocity[opponent] >= self.reciprocity_threshold:
                combined += 0.15

        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            if len(recent) > 0:
                defect_rate = sum(1 for a, b in recent if b == 'defect') / len(recent)
                if defect_rate > 0.6:
                    combined -= 0.1

