        # Update learning rate based on whether the agent's behavior is consistent
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reciprocity_learning_rate:
                self.reciprocity_learning_rate[agent_id] = self.reciprocity_base

