                if action != prev_action:
                    # Behavior changed: increase learning rate to adapt faster
                    self.reciprocity_learning_rate[agent_id] = min(
                        self.reciprocity_max,
                        self.reciprocity_learning_rate[agent_id] + 0.05
                    )
                else:
                    # Behavior consistent: decrease learning rate to stabilize
                    self.reciprocity_learning_rate[agent_id] = max(
                        self.reciprocity_min,
                        self.reciprocity_learning_rate[agent_id] - 0.01
                    )
            else:
                # Initialize with base rate
                self.reciprocity_learning_rate[agent_id] = self.reciprocity_base

