        self.global_defect_count += 1 if donor_action == 'defect' else 0
        self.global_coop_count += 1 if recipient_action == 'cooperate' else 0
        self.global_defect_count += 1 if recipient_action == 'defect' else 0
        self._adapt_tolerance(donor_id, donor_action)
        self._adapt_tolerance(recipient_id, recipient_action)

        for agent in list(self.reputation.keys()):
            self.reputation[agent] = self.reputation[agent] * self.rep_decay
        for agent in list(self.rep_uncertainty.keys()):
