        # New mutation: grudge mechanism - if opponent has defected against us many times, penalize heavily
        if opponent in self.grudges:
            grudge_count = self.grudges[opponent]
            if grudge_count >= self.grudges_threshold:
                combined -= self.grudges_penalty
