                self.recent_coop_window[other_id] += 1
            # Decay all decayed reps slightly each observation
            for pid in list(self.decayed_reps.keys()):
                self.decayed_reps[pid] *= 0.95
            # Update decayed rep for self based on action outcome
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
