        if donor_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1
        if recipient_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1

    def _update_consistency(self, agent_id: int, action: str) -> None:
        if agent_id not in self.consistency:
            self.consistency[agent_id] = 0.5
        action_code = 1 if action == 'cooperate' else 0
        self.consistency[agent_id] = (1 - self.consistency_alpha) * self.consistency[agent_id] + self.consistency_alpha * action_code

    def _update_self_reputation(self, action: str) -> None:
        target = 1.0 if action == 'cooperate' else 0.0
        self.self_reputation = self.self_rep_inertia * self.self_reputation + (1 - self.self_rep_inertia) * target
        self.self_reputation = max(0.0, min(1.0, self.self_reputation))

    def _adapt_tolerance(self, agent_id: int, action: str) -> None:
        # Per-opponent tolerance adaptation based on recent observed actions
        if agent_id not in self.tolerance:
            self.tolerance[agent_id] = self.tolerance_default
            self.recent_defections[agent_id] = 0

        # Track recent defections with decay
        if action == 'defect':
            self.recent_defections[agent_id] += 1
        else:
            self.recent_defections[agent_id] = max(0, self.recent_defections[agent_id] - 0.5)

        # Compute target tolerance based on recent defection streak and global norms
        streak = self.recent_defections[agent_id]
        if streak >= 3:
            target = self.tolerance_min
        elif streak >= 2:
            target = 0.3
        elif streak >= 1:
            target = 0.4
        else:
            # If no recent defections, lean toward default but slightly higher if global cooperation is high
            total_actions = self.global_coop_count + self.global_defect_count
            if total_actions > 0:
                coop_rate = self.global_coop_count / total_actions
                target = self.tolerance_default + (coop_rate - 0.5) * 0.4
            else:
                target = self.tolerance_default
            target = max(self.tolerance_min, min(self.tolerance_max, target))

        # Smooth adaptation
        self.tolerance[agent_id] += self.tolerance_adaptation_rate * (target - self.tolerance[agent_id])
        self.tolerance[agent_id] = max(self.tolerance_min, min(self.tolerance_max, self.tolerance[agent_id]))

