        if len(self.recent_global_actions) > 0:
            recent_defect_rate = sum(self.recent_global_actions) / len(self.recent_global_actions)
        else:
            recent_defect_rate = 0.5

        # Compute target tolerance: lower tolerance if defection rate high
        # Use a logistic-like mapping to keep within bounds
        raw_target = self.tolerance_default - (recent_defect_rate - 0.5) * 0.6
        target = max(self.tolerance_min, min(self.tolerance_max, raw_target))

        # Compute error and update momentum
        error = target - self.tolerance
        self.tolerance_momentum = self.momentum_decay * self.tolerance_momentum + self.momentum_increase * error

        # Apply momentum and adaptation rate
        self.tolerance += self.tolerance_adaptation_rate * error + self.tolerance_momentum
        self.tolerance = max(self.tolerance_min, min(self.tolerance_max, self.tolerance))

