        # cooperation rate in the last few interactions
        self.dynamic_threshold_factor = 0.2
        self.threshold_memory = 5
        self.opponent_coop_history = {}
        self.threshold_base = 0.5

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)
        combined = 0.6 * opp_rep + 0.4 * trust

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        # Child-specific modification: replace the random threshold with a
        # dynamic threshold based on opponent's cooperation history
        if opponent in self.opponent_coop_history:
            history = list(self.opponent_coop_history[opponent])[-self.threshold_memory:]
            if len(history) > 0:
                coop_rate = sum(1 for h in history if h == 'cooperate') / len(history)
                # If opponent cooperates often, lower threshold (more cooperative)
                # If opponent defects often, raise threshold (more cautious)
                threshold = self.threshold_base - self.dynamic_threshold_factor * (coop_rate - 0.5)
            else:
                threshold = self.threshold_base
        else:
            threshold = self.threshold_base

        # Add small random noise for exploration
        threshold += (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
