            recent_cooperations = sum(1 for a, b in self.recent_outcomes if b == 'cooperate')
            if recent_defections > recent_cooperations:
                threshold += 0.1
            else:
                threshold -= 0.05

        if len(self.recent_actions) >= 3:
            if all(a == 'cooperate' for a in self.recent_actions):
                self.coop_tendency = min(1.0, self.coop_tendency + 0.05)
            elif all(a == 'defect' for a in self.recent_actions):
                self.coop_tendency = max(0.0, self.coop_tendency - 0.05)

        threshold += (0.5 - self.coop_tendency) * self.swing_factor

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if len(recent) == 3:
                if recent[-1][0] == 'cooperate' and recent[-1][1] == 'defect':
                    threshold += 0.1
                elif recent[-1][0] == 'defect' and recent[-1][1] == 'cooperate':
                    threshold -= 0.05

        # Child-specific: incorporate trend analysis
        if opponent in self.trend:
            trend_val = sum(self.trend[opponent]) / len(self.trend[opponent]) if self.trend[opponent] else 0.0
            # If the trend is positive (opponent cooperating more), add to combined
            if trend_val > 0:
                combined += self.trend_weight * trend_val
            # If negative, increase threshold to be more cautious
            else:
                threshold += -self.trend_weight * trend_val

        # Child-specific: incorporate reciprocity score - if opponent tends to reciprocate cooperation, be more cooperative
        if opponent in self.reciprocity:
            recip_score = self.reciprocity[opponent]
            if recip_score > 0.5:
                combined += 0.1 * (recip_score - 0.5)
            elif recip_score < 0.3:
                threshold += 0.1 * (0.3 - recip_score)

        # Child-specific modification: incorporate volatility - if opponent is highly volatile, be more cautious
        vol = self.volatility.get(opponent, 0.0)
        if vol > self.volatility_threshold:
            # Increase threshold to be more defensive against unpredictable opponents
            threshold += self.volatility_penalty * (vol - self.volatility_threshold) / (1 - self.volatility_threshold)

        # Child-specific exploration: adjust threshold based on adaptive generosity
        # A higher generosity lowers the threshold, making the agent more cooperative
        threshold -= self.adaptive_generosity

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        self._update_streak(donor_id, donor_action)
        self._update_streak(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)
        self._update_uncertainty(donor_id, donor_action, recipient_id, recipient_action)
        self._update_rep_velocity(donor_id, donor_action)
        self._update_rep_velocity(recipient_id, recipient_action)
        # Child-specific modification: update volatility for observed agents
        self._update_volatility(donor_id, donor_action)
        self._update_volatility(recipient_id, recipient_action)

        if donor_id == self.agent_id:
            self.recent_actions.append(donor_action)
        elif recipient_id == self.agent_id:
            self.recent_actions.append(recipient_action)

        # Child-specific: update trend for observed agents
        self._update_trend(donor_id, donor_action)
        self._update_trend(recipient_id, recipient_action)

        # Child-specific: update reciprocity for self-interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._update_reciprocity(donor_id, donor_action, recipient_id, recipient_action)

        # Child-specific modification: adapt generosity based on own recent outcomes
        if len(self.recent_outcomes) >= 3:
            recent_opponent_coop = sum(1 for a, b in self.recent_outcomes if b == 'cooperate')
            recent_opponent_defect = sum(1 for a, b in self.recent_outcomes if b == 'defect')
            if recent_opponent_coop > recent_opponent_defect:
                # If opponents are cooperating, become more generous
                self.adaptive_generosity = min(self.generosity_ceiling, self.adaptive_generosity + self.generosity_adaptation_rate)
            elif recent_opponent_defect > recent_opponent_coop:
                # If opponents are defecting, become less generous
                self.adaptive_generosity = max(self.generosity_floor, self.adaptive_generosity - self.generosity_adaptation_rate)

        # Child-specific modification: update the opponent cooperation history
        # for the donor and recipient based on their actions
        if donor_id not in self.opponent_coop_history:
            self.opponent_coop_history[donor_id] = deque(maxlen=self.threshold_memory)
        self.opponent_coop_history[donor_id].append(donor_action)
        if recipient_id not in self.opponent_coop_history:
            self.opponent_coop_history[recipient_id] = deque(maxlen=self.threshold_memory)
        self.opponent_coop_history[recipient_id].append(recipient_action)

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)

    def _update_streak(self, agent_id: int, action: str) -> None:
        if agent_id not in self.streak:
            self.streak[agent_id] = (action, 1)
        else:
            prev_type, prev_len = self.streak[agent_id]
            if prev_type == action:
                self.streak[agent_id] = (action, prev_len + 1)
            else:
                self.streak[agent_id] = (action, 1)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = deque(maxlen=50)
        self.interactions[opp_id].append((my_action, opp_action))

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        self.total_interactions += 1
        self.recent_outcomes.append((my_action, opp_action))

        if my_action == 'cooperate' and opp_action == 'cooperate':
            self.coop_tendency = min(1.0, self.coop_tendency + 0.05)
        elif my_action == 'defect' and opp_action == 'defect':
            self.coop_tendency = max(0.0, self.coop_tendency - 0.05)

        # Child-specific modification: update opponent cooperation history in
        # self-interactions as well
        if opp_id not in self.opponent_coop_history:
            self.opponent_coop_history[opp_id] = deque(maxlen=self.threshold_memory)
        self.opponent_coop_history[opp_id].append(opp_action)

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - 0.05)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + 0.02)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - 0.05)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + 0.02)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation: {agent_id: score} initialized to neutral 0
        self.reputations = {}
        # Track interaction counts with each agent for weighted decisions
        self.interaction_counts = {}
        # Track cooperation rates of each agent
        self.coop_counts = {}
        self.total_actions = {}
        # Current opponent ID (set by framework before decide)
        self._ctx_opponent_id = None
        # Personal history for adaptive learning
        self.personal_coop_rate = 0.5
        self.rounds_played = 0
        self.cooperations = 0
        # NEW: Track recent actions for each agent using a deque (window of 5)
        self.recent_actions = {}  # {agent_id: deque of 'C'/'D'}

    def _get_rep(self, agent_id: int) -> float:
        return self.reputations.get(agent_id, 0.0)

    def _update_rep(self, agent_id: int, delta: float) -> None:
        self.reputations[agent_id] = self._get_rep(agent_id) + delta
        # Clamp to prevent extreme values
        self.reputations[agent_id] = max(-10.0, min(10.0, self.reputations[agent_id]))

    def _get_recent_coop_rate(self, agent_id: int) -> float:
        """Compute cooperation rate from recent window; returns 0.5 if no data."""
        actions = self.recent_actions.get(agent_id, deque())
        if not actions:
            return 0.5
        coop_count = actions.count('C')
        return coop_count / len(actions)

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        if opponent_id is None:
            return True  # Shouldn't happen, but safe

        # Base probability from reputation
        rep = self._get_rep(opponent_id)
        prob = 0.5 + 0.1 * rep

        # Use recent coop rate instead of overall for more responsive behavior
        recent_coop = self._get_recent_coop_rate(opponent_id)
        # Blend reputation with recent cooperative behavior
        prob = 0.4 * (0.5 + 0.1 * rep) + 0.6 * recent_coop

        # Adjust based on interaction count: more interactions -> more trust if rep positive
        n = self.interaction_counts.get(opponent_id, 0)
        if n > 0:
            # Blend with overall coop rate if we have history
            coop_rate = self.coop_counts.get(opponent_id, 0) / n
            prob = 0.5 * prob + 0.5 * (0.3 + 0.7 * coop_rate)

        # Personal adjustment: be slightly more cooperative if we've been cooperating a lot
        if self.rounds_played > 0 and self.cooperations / self.rounds_played > 0.7:
            prob += 0.1
        # Defect more if we've been exploited
        if self.rounds_played > 0 and self.cooperations / self.rounds_played < 0.3:
            prob -= 0.1

        # Clamp to [0,1] and make decision
        prob = max(0.0, min(1.0, prob))
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own stats if we are a participant
        if donor_id == self.agent_id:
            self.rounds_played += 1
            if donor_action == 'cooperate':
                self.cooperations += 1
        if recipient_id == self.agent_id:
            self.rounds_played += 1
            if recipient_action == 'cooperate':
                self.cooperations += 1

        # Update recent actions for both participants (new mechanism)
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if pid != self.agent_id:
                # Convert to 'C' or 'D' for compact storage
                symbol = 'C' if action == 'cooperate' else 'D'
                if pid not in self.recent_actions:
                    self.recent_actions[pid] = deque(maxlen=5)
                self.recent_actions[pid].append(symbol)

        # Update observations for both participants
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if pid != self.agent_id:
                # Increment total actions observed
                self.total_actions[pid] = self.total_actions.get(pid, 0) + 1
                if action == 'cooperate':
                    self.coop_counts[pid] = self.coop_counts.get(pid, 0) + 1

        # Update interaction counts if we are a participant
        if donor_id == self.agent_id:
            self.interaction_counts[recipient_id] = self.interaction_counts.get(recipient_id, 0) + 1
        if recipient_id == self.agent_id:
            self.interaction_counts[donor_id] = self.interaction_counts.get(donor_id, 0) + 1

        # Update reputations based on actions (social norm) - same as parent
        if donor_action == 'cooperate':
            self._update_rep(donor_id, 0.2)
        else:
            self._update_rep(donor_id, -0.3)

        if recipient_action == 'cooperate':
            self._update_rep(recipient_id, 0.2)
        else:
            self._update_rep(recipient_id, -0.3)

        # Special case: if someone defects against a cooperator, punish more
        if donor_action == 'defect' and recipient_action == 'cooperate':
            self._update_rep(donor_id, -0.2)
        if recipient_action == 'defect' and donor_action == 'cooperate':
            self._update_rep(recipient_id, -0.2)

        # If both cooperate, small bonus
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            self._update_rep(donor_id, 0.05)
            self._update_rep(recipient_id, 0.05)

        # If both defect, small punishment
        if donor_action == 'defect' and recipient_action == 'defect':
            self._update_rep(donor_id, -0.05)
            self._update_rep(recipient_id, -0.05)

import math
