        if agent_id in self.recent_interaction_window:
            window = self.recent_interaction_window[agent_id]
            if len(window) > 0:
                window_coop_rate = sum(1 for a in window if a == 'cooperate') / len(window)
                rep += (window_coop_rate - 0.5) * 1.5
        return rep

    def update_rep(self, agent_id, delta):
        if not hasattr(self, 'reps'):
            self.reps = {}
        self.reps[agent_id] = self.reps.get(agent_id, 0) + delta
        self.reps[agent_id] = max(-10, min(10, self.reps[agent_id]))

import math
