        if opponent in self.consistency:
            consistency = self.consistency[opponent]
            # High consistency (near 1) means predictable; low means unpredictable
            if consistency > 0.7:
                combined += 0.05 * (combined - 0.5)  # Amplify existing tendency
            elif consistency < 0.3:
                combined -= 0.05 * (combined - 0.5)  # Dampen tendency

        # Mutation: incorporate self_reputation - if we see ourselves as cooperative, be more cooperative
        combined += (self.self_reputation - 0.5) * 0.1

        # Mutation: incorporate observed reputation more heavily when we have no direct interactions
        if opponent in self.obs_reputation:
            obs_rep = self.obs_reputation[opponent]
            # Blend observed reputation with direct estimates
            if opponent in self.interactions:
                # Direct interactions exist, blend with a weight
                combined = (1 - self.obs_rep_weight) * combined + self.obs_rep_weight * obs_rep
            else:
                # No direct interactions, rely more on observed reputation
                combined = 0.7 * obs_rep + 0.3 * combined

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Mutation: update separate observed reputation for third-party observations
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            self._update_obs_reputation(donor_id, donor_action)
            self._update_obs_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)

        # Mutation: update consistency scores for the observed agents
        self._update_consistency(donor_id, donor_action)
        self._update_consistency(recipient_id, recipient_action)

        # Mutation: update self-reputation based on our own actions
        if donor_id == self.agent_id:
            self._update_self_reputation(donor_action)
        if recipient_id == self.agent_id:
            self._update_self_reputation(recipient_action)

        # New: update emotional state based on observed interactions
        self._update_emotional_state(donor_action, recipient_action)

        for agent in list(self.reputation.keys()):
            self.reputation[agent] = self.reputation[agent] * self.rep_decay
        for agent in list(self.rep_uncertainty.keys()):
            self.rep_uncertainty[agent] = self.rep_uncertainty[agent] * self.uncertainty_decay
        # New: decay reciprocity values to emphasize recent interactions
        for agent in list(self.reciprocity.keys()):
            self.reciprocity[agent] = self.reciprocity[agent] * self.reciprocity_decay
        # Mutation: decay consistency scores
        for agent in list(self.consistency.keys()):
            self.consistency[agent] = self.consistency[agent] * self.consistency_decay
        # Decay emotional state towards neutral
        self.emotional_state = 0.5 + (self.emotional_state - 0.5) * self.emotional_decay
        # Mutation: decay observed reputation
        for agent in list(self.obs_reputation.keys()):
            self.obs_reputation[agent] = self.obs_reputation[agent] * self.obs_rep_decay

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
            self.rep_uncertainty[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
            self.rep_uncertainty[agent_id] = max(0.0, self.rep_uncertainty[agent_id] - self.uncertainty_increase)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)
            self.rep_uncertainty[agent_id] = min(1.0, self.rep_uncertainty[agent_id] + self.uncertainty_increase)

    def _update_obs_reputation(self, agent_id: int, action: str) -> None:
        # Separate reputation based on third-party observations
        if agent_id not in self.obs_reputation:
            self.obs_reputation[agent_id] = 0.5
        if action == 'cooperate':
            self.obs_reputation[agent_id] = min(1.0, self.obs_reputation[agent_id] + 0.15)
        else:
            self.obs_reputation[agent_id] = max(0.0, self.obs_reputation[agent_id] - 0.25)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = []
        self.interactions[opp_id].append((my_action, opp_action))

        # New: track reciprocity - count how many times we cooperated with this opponent
        if opp_id not in self.reciprocity:
            self.reciprocity[opp_id] = 0
        if my_action == 'cooperate':
            self.reciprocity[opp_id] += 1

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        if opp_id not in self.rep_uncertainty:
            self.rep_uncertainty[opp_id] = 0.5
        self.rep_uncertainty[opp_id] = max(0.0, self.rep_uncertainty[opp_id] - 0.2)

        self.total_interactions += 1

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - self.defect_penalty_obs)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + self.observation_trust_update)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - self.defect_penalty_obs)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + self.observation_trust_update)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.partner_reputation:
            self.partner_reputation[recipient_id] = {'coop': 0, 'defect': 0}

        if donor_action == 'cooperate':
            self.partner_reputation[donor_id]['coop'] += 1
        else:
            self.partner_reputation[donor_id]['defect'] += 1

        if recipient_action == 'cooperate':
            self.partner_reputation[recipient_id]['coop'] += 1
        else:
            self.partner_reputation[recipient_id]['defect'] += 1

        if donor_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1
        if recipient_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1

    def _update_consistency(self, agent_id: int, action: str) -> None:
        # Track the fraction of cooperate actions observed for this agent
        if agent_id not in self.consistency:
            self.consistency[agent_id] = 0.5
        # Simple moving average: alpha * (action_code) + (1-alpha) * previous
        action_code = 1 if action == 'cooperate' else 0
        self.consistency[agent_id] = (1 - self.consistency_alpha) * self.consistency[agent_id] + self.consistency_alpha * action_code

    def _update_self_reputation(self, action: str) -> None:
        # Update self-image based on our own actions
        target = 1.0 if action == 'cooperate' else 0.0
        self.self_reputation = self.self_rep_inertia * self.self_reputation + (1 - self.self_rep_inertia) * target
        # Keep in [0,1]
        self.self_reputation = max(0.0, min(1.0, self.self_reputation))

    def _update_emotional_state(self, donor_action: str, recipient_action: str) -> None:
        # Update emotional state based on observed interactions
        # Both cooperating increases positive emotion; both defecting or one defecting decreases it
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            self.emotional_state = min(1.0, self.emotional_state + self.emotional_update_positive)
        elif donor_action == 'defect' and recipient_action == 'defect':
            self.emotional_state = max(0.0, self.emotional_state - self.emotional_update_negative)
        elif donor_action == 'defect' or recipient_action == 'defect':
            # One defects, the other cooperates - mild negative effect
            self.emotional_state = max(0.0, self.emotional_state - self.emotional_update_negative * 0.5)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        self.streak = {}
        self.streak_bonus = 0.15
        self.streak_threshold = 3
        self.uncertainty = {}
        self.uncertainty_decay = 0.9
        self.uncertainty_boost = 0.1
        self.uncertainty_threshold = 0.6
        self.rep_velocity = {}
        self.velocity_window = 5
        self.velocity_decay = 0.8
        self.momentum_factor = 0.3
        self.risk_tolerance = 0.5
        self.recent_outcomes = deque(maxlen=10)
        self.recent_actions = deque(maxlen=10)
        self.coop_tendency = 0.5
        self.swing_factor = 0.3
        # Child-specific: track recent cooperation trends per opponent
        self.trend = {}
        self.trend_window = 4
        self.trend_weight = 0.2
        # Child-specific: add a "reciprocity" score per opponent
        self.reciprocity = {}
        self.reciprocity_memory = 5
        self.reciprocity_decay = 0.9
        # Child-specific modification: add a volatility tracker
        self.volatility = {}
        self.volatility_window = 5
        self.volatility_penalty = 0.15
        self.volatility_threshold = 0.4
        # Child-specific: add a "predictability" score that rewards consistent behavior
        self.predictability = {}
        self.predictability_threshold = 0.3
        self.predictability_bonus = 0.2
        self.predictability_penalty = 0.1

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)
        combined = 0.6 * opp_rep + 0.4 * trust

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.3 * combined + 0.7 * coop_rate

        threshold = 0.5 + (random.random() - 0.5) * 0.1

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= 4 and combined > 0.4:
                combined += self.forgiveness

        if opponent in self.streak:
            streak_type, streak_len = self.streak[opponent]
            if streak_type == 'cooperate' and streak_len >= self.streak_threshold:
                combined += self.streak_bonus
            elif streak_type == 'defect' and streak_len >= self.streak_threshold:
                combined -= self.streak_bonus

        if opponent in self.rep_velocity:
            velocity = self.rep_velocity[opponent]
            combined += self.momentum_factor * velocity

        uncertainty = self.uncertainty.get(opponent, 0.0)
        if uncertainty > self.uncertainty_threshold:
            streak_factor = 0.0
            if opponent in self.streak:
                _, streak_len = self.streak[opponent]
                if streak_len >= 2:
                    streak_factor = 0.05 * min(streak_len, 5)
            combined -= (0.1 * uncertainty + streak_factor)

        risk_adjustment = 0.0
        if uncertainty > self.uncertainty_threshold:
            risk_adjustment += 0.1 * (uncertainty - self.uncertainty_threshold) / (1 - self.uncertainty_threshold)
        if opponent in self.rep_velocity:
            velocity = self.rep_velocity[opponent]
            if velocity > 0:
                risk_adjustment -= 0.05 * min(velocity, 1.0)
            else:
                risk_adjustment += 0.05 * min(-velocity, 1.0)
        threshold += risk_adjustment

        if len(self.recent_outcomes) >= 3:
            recent_defections = sum(1 for a, b in self.recent_outcomes if b == 'defect')
            recent_cooperations = sum(1 for a, b in self.recent_outcomes if b == 'cooperate')
            if recent_defections > recent_cooperations:
                threshold += 0.1
            else:
                threshold -= 0.05

        if len(self.recent_actions) >= 3:
            if all(a == 'cooperate' for a in self.recent_actions):
                self.coop_tendency = min(1.0, self.coop_tendency + 0.05)
            elif all(a == 'defect' for a in self.recent_actions):
                self.coop_tendency = max(0.0, self.coop_tendency - 0.05)

        threshold += (0.5 - self.coop_tendency) * self.swing_factor

        if opponent in self.interactions:
            recent = list(self.interactions[opponent])[-3:]
            if len(recent) == 3:
                if recent[-1][0] == 'cooperate' and recent[-1][1] == 'defect':
                    threshold += 0.1
                elif recent[-1][0] == 'defect' and recent[-1][1] == 'cooperate':
                    threshold -= 0.05

        # Child-specific: incorporate trend analysis
        if opponent in self.trend:
            trend_val = self.trend[opponent]
            # If the trend is positive (opponent cooperating more), add to combined
            if trend_val > 0:
                combined += self.trend_weight * trend_val
            # If negative, increase threshold to be more cautious
            else:
                threshold += -self.trend_weight * trend_val

        # Child-specific: incorporate reciprocity score - if opponent tends to reciprocate cooperation, be more cooperative
        if opponent in self.reciprocity:
            recip_score = self.reciprocity[opponent]
            if recip_score > 0.5:
                combined += 0.1 * (recip_score - 0.5)
            elif recip_score < 0.3:
                threshold += 0.1 * (0.3 - recip_score)

        # Child-specific modification: incorporate volatility - if opponent is highly volatile, be more cautious
        vol = self.volatility.get(opponent, 0.0)
        if vol > self.volatility_threshold:
            # Increase threshold to be more defensive against unpredictable opponents
            threshold += self.volatility_penalty * (vol - self.volatility_threshold) / (1 - self.volatility_threshold)

        # Child-specific: incorporate predictability - if opponent is predictable (low volatility), trust more
        pred = self.predictability.get(opponent, 0.0)
        if pred < self.predictability_threshold:
            # Low predictability means high volatility, be more cautious
            threshold += self.predictability_penalty
        else:
            # High predictability gives a bonus to cooperation
            combined += self.predictability_bonus * min(pred, 1.0)

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        self._update_streak(donor_id, donor_action)
        self._update_streak(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)
        self._update_uncertainty(donor_id, donor_action, recipient_id, recipient_action)
        self._update_rep_velocity(donor_id, donor_action)
        self._update_rep_velocity(recipient_id, recipient_action)
        # Child-specific modification: update volatility for observed agents
        self._update_volatility(donor_id, donor_action)
        self._update_volatility(recipient_id, recipient_action)
        # Child-specific: update predictability for observed agents
        self._update_predictability(donor_id, donor_action)
        self._update_predictability(recipient_id, recipient_action)

        if donor_id == self.agent_id:
            self.recent_actions.append(donor_action)
        elif recipient_id == self.agent_id:
            self.recent_actions.append(recipient_action)

        # Child-specific: update trend for observed agents
        self._update_trend(donor_id, donor_action)
        self._update_trend(recipient_id, recipient_action)

        # Child-specific: update reciprocity for self-interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._update_reciprocity(donor_id, donor_action, recipient_id, recipient_action)

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)

    def _update_streak(self, agent_id: int, action: str) -> None:
        if agent_id not in self.streak:
            self.streak[agent_id] = (action, 1)
        else:
            prev_type, prev_len = self.streak[agent_id]
            if prev_type == action:
                self.streak[agent_id] = (action, prev_len + 1)
            else:
                self.streak[agent_id] = (action, 1)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = deque(maxlen=50)
        self.interactions[opp_id].append((my_action, opp_action))

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        self.total_interactions += 1
        self.recent_outcomes.append((my_action, opp_action))

        if my_action == 'cooperate' and opp_action == 'cooperate':
            self.coop_tendency = min(1.0, self.coop_tendency + 0.05)
        elif my_action == 'defect' and opp_action == 'defect':
            self.coop_tendency = max(0.0, self.coop_tendency - 0.05)

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - 0.05)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + 0.02)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - 0.05)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + 0.02)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.partner_reputation:
            self.partner_reputation[recipient_id] = {'coop': 0, 'defect': 0}

        if donor_action == 'cooperate':
            self.partner_reputation[donor_id]['coop'] += 1
        else:
            self.partner_reputation[donor_id]['defect'] += 1

        if recipient_action == 'cooperate':
            self.partner_reputation[recipient_id]['coop'] += 1
        else:
            self.partner_reputation[recipient_id]['defect'] += 1

        if donor_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1
        if recipient_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1

    def _update_uncertainty(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.uncertainty:
                self.uncertainty[agent_id] = 0.0
            else:
                self.uncertainty[agent_id] *= self.uncertainty_decay

            rep = self.reputation.get(agent_id, 0.5)
            if (action == 'cooperate' and rep < 0.4) or (action == 'defect' and rep > 0.6):
                self.uncertainty[agent_id] = min(1.0, self.uncertainty[agent_id] + self.uncertainty_boost)
            else:
                self.uncertainty[agent_id] = max(0.0, self.uncertainty[agent_id] - 0.02)

            if agent_id in self.streak:
                streak_type, streak_len = self.streak[agent_id]
                if streak_len >= 3:
                    self.uncertainty[agent_id] = max(0.0, self.uncertainty[agent_id] - 0.05)
                elif streak_len >= 5:
                    self.uncertainty[agent_id] = max(0.0, self.uncertainty[agent_id] - 0.1)

    def _update_rep_velocity(self, agent_id: int, action: str) -> None:
        if action == 'cooperate':
            change = self.coop_bonus
        else:
            change = -self.defect_penalty

        if agent_id not in self.rep_velocity:
            self.rep_velocity[agent_id] = change
        else:
            self.rep_velocity[agent_id] = self.velocity_decay * self.rep_velocity[agent_id]

