        self.observed_recent = {}
        self.last_action_against = {}
        self.generation = 0
        self.round_in_generation = 0
        self.total_rounds = 0
        # New: memory of all observed interactions for third-party, max 50 per agent
        self.memory = {}
        # New: forgiveness factor - how much a single defection is overlooked
        self.forgiveness = 0.3
        # New: adaptive threshold based on own reputation
        self.base_threshold = 0.0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        opp_rep = self.get_rep(opponent)
        # Use adaptive threshold: if own reputation is high, be more trusting
        threshold = self.base_threshold - self.reputation * 0.05
        direct = self.last_action_against.get(opponent)
        if direct is not None:
            # If they defected last time, consider forgiveness
            if direct == 'defect' and opp_rep < threshold + self.forgiveness:
                return False
            if direct == 'cooperate' and opp_rep > threshold - self.forgiveness:
                return True
        return opp_rep >= threshold

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_action = recipient_action
                other_id = recipient_id
            else:
                my_action = recipient_action
                other_action = donor_action
                other_id = donor_id
            self.last_action_against[other_id] = other_action
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
                self.reputation += 0.5
            else:
                self.reputation -= 0.5
            self.reputation = max(-10, min(10, self.reputation))
            self.own_recent.append(my_action)
            self.total_interactions[other_id] = self.total_interactions.get(other_id, 0) + 1
            if my_action == 'cooperate':
                self.coop_counts[other_id] = self.coop_counts.get(other_id, 0) + 1
        else:
            # Third-party: use a weighted update with decay over time
            # Store in memory for later analysis
            self._store_memory(donor_id, donor_action, recipient_id, recipient_action)
            # Update reputation with decay factor based on memory length
            decay = 0.9 ** (len(self.memory.get(donor_id, [])) // 5)
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.update_rep(donor_id, 0.3 * decay)
                self.update_rep(recipient_id, 0.3 * decay)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.update_rep(donor_id, 0.2 * decay)
                self.update_rep(recipient_id, 0.2 * decay)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.update_rep(donor_id, -0.3 * decay)
                self.update_rep(recipient_id, -0.1 * decay)
            else:  # donor defect, recipient cooperate
                self.update_rep(donor_id, -0.1 * decay)
                self.update_rep(recipient_id, 0.3 * decay)
            # Update observed recent
            for pid in (donor_id, recipient_id):
                if pid not in self.observed_recent:
                    self.observed_recent[pid] = deque(maxlen=10)
                self.observed_recent[pid].append(donor_action if pid == donor_id else recipient_action)

    def _store_memory(self, donor_id, donor_action, recipient_id, recipient_action):
        # Store as tuple (donor_id, donor_action, recipient_id, recipient_action)
        if donor_id not in self.memory:
            self.memory[donor_id] = deque(maxlen=50)
        self.memory[donor_id].append((donor_action, recipient_action))
        if recipient_id not in self.memory:
            self.memory[recipient_id] = deque(maxlen=50)
        self.memory[recipient_id].append((recipient_action, donor_action))

    def get_rep(self, agent_id):
        rep = self.reputation if agent_id == self.agent_id else 0
        if agent_id in self.observed_recent:
            recent = self.observed_recent[agent_id]
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                rep += (coop_rate - 0.5) * 2
        if agent_id in self.total_interactions and self.total_interactions[agent_id] > 0:
            coop_ratio = self.coop_counts.get(agent_id, 0) / self.total_interactions[agent_id]
