        threshold = self.base_threshold - self.reputation * 0.05
        direct = self.last_action_against.get(opponent)
        if direct is not None:
            # If they defected last time, consider forgiveness
            if direct == 'defect' and opp_rep < threshold + self.forgiveness:
                return False
            if direct == 'cooperate' and opp_rep > threshold - self.forgiveness:
                return True
        return opp_rep >= threshold

