            else:  # donor defect, recipient cooperate
                self.update_rep(donor_id, -0.1 * decay)
                self.update_rep(recipient_id, 0.3 * decay)
            # Update observed recent
            for pid in (donor_id, recipient_id):
                if pid not in self.observed_recent:
                    self.observed_recent[pid] = deque(maxlen=10)
                self.observed_recent[pid].append(donor_action if pid == donor_id else recipient_action)

    def _store_memory(self, donor_id, donor_action, recipient_id, recipient_action):
        # Store as tuple (donor_id, donor_action, recipient_id, recipient_action)
        if donor_id not in self.memory:
            self.memory[donor_id] = deque(maxlen=50)
        self.memory[donor_id].append((donor_action, recipient_action))
        if recipient_id not in self.memory:
            self.memory[recipient_id] = deque(maxlen=50)
        self.memory[recipient_id].append((recipient_action, donor_action))

    def get_rep(self, agent_id):
        rep = self.reputation if agent_id == self.agent_id else 0
        if agent_id in self.observed_recent:
            recent = self.observed_recent[agent_id]
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
