        if agent_id in self.memory:
            mem = self.memory[agent_id]
            if len(mem) >= 5:
                # Count consecutive cooperation after a defection (forgiving pattern)
                coop_after_defect = 0
                for i in range(1, len(mem)):
                    if mem[i][0] == 'cooperate' and mem[i-1][0] == 'defect':
                        coop_after_defect += 1
                if coop_after_defect > 0:
                    rep += 0.2 * min(coop_after_defect, 3)
        return rep

    def update_rep(self, agent_id, delta):
        if not hasattr(self, 'reps'):
            self.reps = {}
        self.reps[agent_id] = self.reps.get(agent_id, 0) + delta
        self.reps[agent_id] = max(-10, min(10, self.reps[agent_id]))

