from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = 0.0
        self.coop_counts = {}
        self.total_interactions = {}
        self.own_recent = []
        self.observed_recent = {}
        self.last_action_against = {}
        self.generation = 0
        self.round_in_generation = 0
        self.total_rounds = 0
        # Track a momentum-based reputation estimate (explores different update rule)
        self.momentum_reps = {}
        # Track a sliding window of recent cooperation with emphasis on very recent actions
        self.short_window_coop = {}
        self.short_window_total = {}
        # Track an average reputation from third-party observations with decay
        self.avg_observed_rep = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        opp_rep = self.get_rep(opponent)
        direct = self.last_action_against.get(opponent)
        if direct is not None:
            if direct == 'defect' and opp_rep < 1:
                return False
            if direct == 'cooperate' and opp_rep > -3:
                return True
        # Changed tolerance: cooperate only if rep >= 0 (more conservative)
        return opp_rep >= 0

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_action = recipient_action
                other_id = recipient_id
            else:
                my_action = recipient_action
                other_action = donor_action
                other_id = donor_id
            self.last_action_against[other_id] = other_action
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
                self.reputation += 0.5
            else:
                self.reputation -= 0.5
            self.reputation = max(-10, min(10, self.reputation))
            self.own_recent.append(my_action)
            if len(self.own_recent) > 10:
                self.own_recent.pop(0)
            self.total_interactions[other_id] = self.total_interactions.get(other_id, 0) + 1
            if my_action == 'cooperate':
                self.coop_counts[other_id] = self.coop_counts.get(other_id, 0) + 1
            # Update short window (last 3 interactions) for this agent
            if other_id not in self.short_window_total:
                self.short_window_total[other_id] = deque(maxlen=3)
                self.short_window_coop[other_id] = 0
            self.short_window_total[other_id].append(1)
            if my_action == 'cooperate':
                self.short_window_coop[other_id] += 1
            # Update momentum-based rep for self with a different update rule
            if other_action == 'cooperate':
                self.momentum_reps[self.agent_id] = self.momentum_reps.get(self.agent_id, 0) * 0.9 + 0.5
            else:
                self.momentum_reps[self.agent_id] = self.momentum_reps.get(self.agent_id, 0) * 0.9 - 0.3
            self.momentum_reps[self.agent_id] = max(-10, min(10, self.momentum_reps[self.agent_id]))
        else:
            # Third-party observation
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.update_rep(donor_id, 0.3)
                self.update_rep(recipient_id, 0.3)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.update_rep(donor_id, 0.2)
                self.update_rep(recipient_id, 0.2)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.update_rep(donor_id, -0.3)
                self.update_rep(recipient_id, -0.1)
            else:
                self.update_rep(donor_id, -0.1)
                self.update_rep(recipient_id, 0.3)
            for pid in (donor_id, recipient_id):
                if pid not in self.observed_recent:
                    self.observed_recent[pid] = []
                self.observed_recent[pid].append(donor_action if pid == donor_id else recipient_action)
                if len(self.observed_recent[pid]) > 10:
                    self.observed_recent[pid].pop(0)
                # Update average observed reputation with exponential moving average
                action_val = 1 if (pid == donor_id and donor_action == 'cooperate') or \
                                  (pid == recipient_id and recipient_action == 'cooperate') else 0
                if pid not in self.avg_observed_rep:
                    self.avg_observed_rep[pid] = action_val
                else:
                    self.avg_observed_rep[pid] = 0.7 * self.avg_observed_rep[pid] + 0.3 * action_val

    def get_rep(self, agent_id):
        rep = self.reputation if agent_id == self.agent_id else 0
        # Use momentum-based rep if available
        if agent_id in self.momentum_reps:
            rep += self.momentum_reps[agent_id] * 0.7
        if agent_id in self.observed_recent:
            recent = self.observed_recent[agent_id]
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                rep += (coop_rate - 0.5) * 2
        if agent_id in self.total_interactions and self.total_interactions[agent_id] > 0:
            coop_ratio = self.coop_counts.get(agent_id, 0) / self.total_interactions[agent_id]
            rep += (coop_ratio - 0.5) * 1
        # Incorporate short window (last 3) cooperation rate with higher weight
        if agent_id in self.short_window_total and len(self.short_window_total[agent_id]) > 0:
            window_coop_rate = self.short_window_coop.get(agent_id, 0) / len(self.short_window_total[agent_id])
            rep += (window_coop_rate - 0.5) * 2
        # Incorporate average observed reputation
        if agent_id in self.avg_observed_rep:
            rep += (self.avg_observed_rep[agent_id] - 0.5) * 1.5
        return rep

    def update_rep(self, agent_id, delta):
        if not hasattr(self, 'reps'):
            self.reps = {}
        self.reps[agent_id] = self.reps.get(agent_id, 0) + delta
        self.reps[agent_id] = max(-10, min(10, self.reps[agent_id]))

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.cooperation_history = {}
        self.my_reputation = {}
        self.round_count = 0
        self.opponent_history = {}
        self.trust_scores = {}
        self.cooperation_count = 0
        self.total_rounds = 0
        self.recent_actions = []
        self.defection_count = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # Initialize trust if unknown
        if opponent not in self.trust_scores:
            self.trust_scores[opponent] = 0.5

        # Get reputation of opponent (their cooperation rate in general)
        rep = self.my_reputation.get(opponent, 0.5)

        # Personal history with opponent
        hist = self.opponent_history.get(opponent, [])
        if len(hist) > 0:
            past_coop = sum(hist) / len(hist)
        else:
            past_coop = 0.5

        # Combine trust, reputation, and recent behavior
        trust = self.trust_scores[opponent]
        combined_score = 0.4 * trust + 0.3 * rep + 0.3 * past_coop

        # Adaptive threshold based on overall environment
        if self.total_rounds > 0 and self.cooperation_count / self.total_rounds > 0.7:
            threshold = 0.55
        else:
            threshold = 0.45

        # Slight randomness to avoid being too predictable
        if random.random() < 0.05:
            return random.random() < 0.5

        return combined_score > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_coop = 1 if donor_action == 'cooperate' else 0
        recipient_coop = 1 if recipient_action == 'cooperate' else 0

        # Update own reputation tracking for both participants
        if donor_id not in self.my_reputation:
            self.my_reputation[donor_id] = []
        if recipient_id not in self.my_reputation:
            self.my_reputation[recipient_id] = []

        self.my_reputation[donor_id].append(donor_coop)
        self.my_reputation[recipient_id].append(recipient_coop)

        # Update trust based on observed interactions
        self._update_trust(donor_id, recipient_id, donor_coop, recipient_coop)
        self._update_trust(recipient_id, donor_id, recipient_coop, donor_coop)

        # If this is our own interaction, update personal history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_count += 1
            self.total_rounds += 1
            if donor_id == self.agent_id:
                my_action = donor_coop
                opp_action = recipient_coop
                opp = recipient_id
            else:
                my_action = recipient_coop
                opp_action = donor_coop
                opp = donor_id

            if my_action == 1:
                self.cooperation_count += 1
            else:
                self.defection_count += 1

            if opp not in self.opponent_history:
                self.opponent_history[opp] = []
            self.opponent_history[opp].append(opp_action)

            # Update trust based on outcome
            if my_action == 1 and opp_action == 1:
                self.trust_scores[opp] = min(1.0, self.trust_scores.get(opp, 0.5) + 0.1)
            elif my_action == 1 and opp_action == 0:
                self.trust_scores[opp] = max(0.0, self.trust_scores.get(opp, 0.5) - 0.2)
            elif my_action == 0 and opp_action == 1:
                self.trust_scores[opp] = min(1.0, self.trust_scores.get(opp, 0.5) + 0.05)
            else:
                self.trust_scores[opp] = max(0.0, self.trust_scores.get(opp, 0.5) - 0.05)

    def _update_trust(self, observer_id: int, target_id: int, observer_action: int, target_action: int) -> None:
        # This function updates trust based on third-party observations
        if target_id not in self.trust_scores:
            self.trust_scores[target_id] = 0.5

        # If target cooperated when observer cooperated, they are trustworthy
        if observer_action == 1 and target_action == 1:
            self.trust_scores[target_id] = min(1.0, self.trust_scores[target_id] + 0.02)
        elif observer_action == 1 and target_action == 0:
            self.trust_scores[target_id] = max(0.0, self.trust_scores[target_id] - 0.03)
        elif observer_action == 0 and target_action == 1:
            self.trust_scores[target_id] = min(1.0, self.trust_scores[target_id] + 0.01)
        else:
            self.trust_scores[target_id] = max(0.0, self.trust_scores[target_id] - 0.01)

