class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = 0.0
        self.coop_counts = {}
        self.total_interactions = {}
        self.own_recent = []
        self.observed_recent = {}
        self.last_action_against = {}
        self.generation = 0
        self.round_in_generation = 0
        self.total_rounds = 0
        # New: track an exponentially decaying reputation estimate
        self.decayed_reps = {}
        # New: track a recent cooperation count for each agent (window of 5)
        self.recent_coop_window = {}
        self.recent_interaction_window = {}
        # New: track a longer-term memory of observed cooperation rate
        self.long_term_coop = {}
        self.long_term_interactions = {}
        # Modification: add a forgiveness factor that decays over time and resets on cooperation
        self.forgiveness = 0.0
        self.forgiveness_decay = 0.9
        self.last_defection_seen = {}
        # New: Add a suspicion counter that tracks how often this agent has been exploited
        self.suspicion = 0.0
        self.suspicion_reset = 0.5

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        opp_rep = self.get_rep(opponent)
        direct = self.last_action_against.get(opponent)
        # Modification: incorporate forgiveness and suspicion into decision
        if direct is not None:
            if direct == 'defect' and opp_rep + self.forgiveness - self.suspicion < 1.5:
                return False
            if direct == 'cooperate' and opp_rep > -2:
                return True
        # New: cooperate if rep >= -1 (more forgiving) but penalize if opponent has defected recently
        if opponent in self.last_defection_seen:
            if self.total_rounds - self.last_defection_seen[opponent] < 3:
                return False
        # New: If suspicion is high, be more cautious
        if self.suspicion > 2.0:
            return False
        return opp_rep >= -1

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_action = recipient_action
                other_id = recipient_id
            else:
                my_action = recipient_action
                other_action = donor_action
                other_id = donor_id
            self.last_action_against[other_id] = other_action
            if other_action == 'defect':
                self.last_defection_seen[other_id] = self.total_rounds
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
                self.reputation += 0.5
            else:
                self.reputation -= 0.5
            self.reputation = max(-10, min(10, self.reputation))
            self.own_recent.append(my_action)
            if len(self.own_recent) > 10:
                self.own_recent.pop(0)
            self.total_interactions[other_id] = self.total_interactions.get(other_id, 0) + 1
            if my_action == 'cooperate':
                self.coop_counts[other_id] = self.coop_counts.get(other_id, 0) + 1
            # Modification: increase forgiveness on mutual cooperation, reset on defection
            if my_action == 'cooperate' and other_action == 'cooperate':
                self.forgiveness = min(2.0, self.forgiveness + 0.2)
                self.suspicion = max(0.0, self.suspicion - self.suspicion_reset)
            else:
                self.forgiveness *= self.forgiveness_decay
                # New: Increase suspicion when exploited (cooperate vs defect)
                if my_action == 'cooperate' and other_action == 'defect':
                    self.suspicion += 0.3
                elif my_action == 'defect' and other_action == 'cooperate':
                    self.suspicion = max(0.0, self.suspicion - 0.1)
            # New: update recent interaction window for this agent
            if other_id not in self.recent_interaction_window:
                self.recent_interaction_window[other_id] = deque(maxlen=5)
                self.recent_coop_window[other_id] = 0
            self.recent_interaction_window[other_id].append(my_action)
            if my_action == 'cooperate':
                self.recent_coop_window[other_id] += 1
            # New: update long-term memory for this agent
            self.long_term_interactions[other_id] = self.long_term_interactions.get(other_id, 0) + 1
            if my_action == 'cooperate':
                self.long_term_coop[other_id] = self.long_term_coop.get(other_id, 0) + 1
            # Decay all decayed reps slightly each observation
            for pid in list(self.decayed_reps.keys()):
                self.decayed_reps[pid] *= 0.95
