            rep += avg_trust * 3.0

        # NEW: Add loyalty as an additional factor
        if agent_id in self.loyalty:
            rep += self.loyalty[agent_id] * 1.0

        # NEW: Add suspicion penalty
        if agent_id in self.suspicion:
            rep -= self.suspicion[agent_id] * 0.5

        return rep

