            # (more stable over time, but still responsive)
            alpha = 0.5 / (1 + self.total_interactions.get(other_id, 0) * 0.1)
            self.trust[other_id] = (1 - alpha) * self.trust[other_id] + alpha * delta
            # Clamp to -1..1
            self.trust[other_id] = max(-1.0, min(1.0, self.trust[other_id]))
        else:
            # Third-party observation: update reputation of both actors
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.update_rep(donor_id, 0.3)
                self.update_rep(recipient_id, 0.3)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.update_rep(donor_id, 0.2)
                self.update_rep(recipient_id, 0.2)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.update_rep(donor_id, -0.3)
                self.update_rep(recipient_id, -0.1)
            else:  # donor defect, recipient cooperate
                self.update_rep(donor_id, -0.1)
                self.update_rep(recipient_id, 0.3)
            for pid in (donor_id, recipient_id):
                if pid not in self.observed_recent:
                    self.observed_recent[pid] = []
                self.observed_recent[pid].append(donor_action if pid == donor_id else recipient_action)
                if len(self.observed_recent[pid]) > 10:
                    self.observed_recent[pid].pop(0)

    def get_rep(self, agent_id):
        # Combine reputation with observed recent cooperation rate
        rep = self.reputation if agent_id == self.agent_id else 0
        if agent_id in self.reps:
            self.reps[agent_id] *= (1 - self.forgiveness)
            rep += self.reps[agent_id]
        if agent_id in self.observed_recent:
            recent = self.observed_recent[agent_id]
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                rep += (coop_rate - 0.5) * 2
        if agent_id in self.total_interactions and self.total_interactions[agent_id] > 0:
            coop_ratio = self.coop_counts.get(agent_id, 0) / self.total_interactions[agent_id]
            rep += (coop_ratio - 0.5) * 1

        # NEW: Add trust as an additional signal, weighted by how much we trust them
        # This makes decisions more dependent on direct personal history,
        # rather than just general reputation
        if agent_id in self.trust:
            rep += self.trust[agent_id] * 2  # weight trust more heavily

        return rep

    def update_rep(self, agent_id, delta):
        if not hasattr(self, 'reps'):
            self.reps = {}
        self.reps[agent_id] = self.reps.get(agent_id, 0) + delta
        self.reps[agent_id] = max(-10, min(10, self.reps[agent_id]))

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation score for each other agent, initialized neutral (0)
        # Range roughly -10 to +10, clamped
        self.reputation = {}
        # Track cooperation rate of each agent (cooperate_count, total_obs)
        self.coop_rate = {}
        # Track recent actions by self for learning
        self.self_history = []
        # Track opponent history for modeling
        self.opponent_history = {}
        # Track round number within generation
        self.round_count = 0
        # Track generation number (resets internal learning slowly)
        self.gen_count = 0
        # Last opponent ID for context (set by framework)
        self._ctx_opponent_id = None
        # Memory of past interactions with each agent: list of (my_action, opp_action)
        self.interaction_memory = {}
        # Cooldown for forgiveness: if someone defects too often, be harsh
        self.defection_count = {}
        # Overall generosity parameter (decays if exploited)
        self.generosity = 0.9

    def decide(self) -> bool:
        # Get opponent ID
        opp = self._ctx_opponent_id
        if opp is None:
            return True  # Default cooperate if no opponent

        # Update round count
        self.round_count += 1
        if self.round_count > 30:
            self.round_count = 1
            self.gen_count += 1
            # Slight decay of generosity each generation (learning)
            self.generosity = max(0.5, self.generosity * 0.995)

        # If we have no history with this opponent, use reputation
        # Start with cooperation if opponent has decent reputation
        if opp not in self.interaction_memory or len(self.interaction_memory[opp]) == 0:
            # Use reputation if available
            rep = self.reputation.get(opp, 0)
            if rep > 2:
                return True
            elif rep < -2:
                return False
            else:
                # Unknown: cooperate with probability proportional to generosity
                return random.random() < self.generosity

        # Analyze opponent's recent behavior
        mem = self.interaction_memory[opp]
        # Look at last up to 5 interactions
        recent = mem[-5:]
        opp_coop_count = sum(1 for _, opp_action in recent if opp_action == 'cooperate')
        opp_defect_count = len(recent) - opp_coop_count

        # Tit-for-tat with forgiveness: if opponent cooperated last time, cooperate
        # If opponent defected last time, defect with high probability but occasionally forgive
        if not recent:
            return True
        last_opp_action = recent[-1][1]

        # Also consider overall reputation
        rep = self.reputation.get(opp, 0)

        # Strategic: if opponent has been cooperating a lot, cooperate
        if opp_coop_count / len(recent) > 0.7:
            return True
        # If opponent has been defecting a lot, defect
        if opp_defect_count / len(recent) > 0.6:
            return False

        # Tit-for-tat with forgiveness: based on last action
        if last_opp_action == 'cooperate':
            # Sometimes deviate to test, but mostly cooperate
            return random.random() < (self.generosity * 0.9 + 0.1)
        else:
            # Defect, but forgive with small probability (e.g., 10% + generosity)
            # This prevents endless defection spirals
            forgive_prob = 0.1 + 0.05 * self.generosity
            # Also if reputation is high, forgive more
            if rep > 5:
                forgive_prob += 0.1
            return random.random() > forgive_prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update state for all observations
        # Track cooperation rates for each agent (excluding self)
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue  # Don't track self in reputation (we know our own actions)
            # Update coop rate stats
            if agent_id not in self.coop_rate:
                self.coop_rate[agent_id] = [0, 0]  # [cooperate_count, total_obs]
            self.coop_rate[agent_id][1] += 1
            if action == 'cooperate':
                self.coop_rate[agent_id][0] += 1

        # Update reputation based on actions
        # Cooperation increases reputation, defection decreases it
        # Also consider reciprocity: defecting against a cooperator is worse
        # Update donor and recipient reputations
        # For donor: if donor cooperates, +1; if defects, -1
        # For recipient: if recipient cooperates, +1; if defects, -1
        # But also context: if one defects while other cooperates, that's worse
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 1
            else:
                # Defection is worse if recipient cooperated (unprovoked)
                if recipient_action == 'cooperate':
                    self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 2
                else:
                    self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 1

        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + 1
            else:
                if donor_action == 'cooperate':
                    self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) - 2
                else:
                    self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) - 1

        # Clamp reputation to [-10, 10]
        for aid in [donor_id, recipient_id]:
            if aid != self.agent_id:
                self.reputation[aid] = max(-10, min(10, self.reputation.get(aid, 0)))

        # If this involves self, update interaction memory with opponent
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent and actions
            if donor_id == self.agent_id:
                opp_id = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opp_id = donor_id
                my_action = recipient_action
                opp_action = donor_action

            # Append to interaction memory
            if opp_id not in self.interaction_memory:
                self.interaction_memory[opp_id] = []
            self.interaction_memory[opp_id].append((my_action, opp_action))
            # Keep memory limited to last 20 interactions
            if len(self.interaction_memory[opp_id]) > 20:
                self.interaction_memory[opp_id] = self.interaction_memory[opp_id][-20:]

            # Update defection count for opponent
            if opp_action == 'defect':
                self.defection_count[opp_id] = self.defection_count.get(opp_id, 0) + 1
            else:
                self.defection_count[opp_id] = self.defection_count.get(opp_id, 0) - 0.5
                if self.defection_count[opp_id] < 0:
                    self.defection_count[opp_id] = 0

            # If opponent defects a lot, reduce generosity slightly
            if self.defection_count.get(opp_id, 0) > 5:
                self.generosity = max(0.5, self.generosity - 0.01)

            # Also record self history
            self.self_history.append(my_action)
            if len(self.self_history) > 50:
                self.self_history = self.self_history[-50:]

        # Optional: if we observe others, we don't need to store all, but we can
        # Keep a simple memory of recent observations for potential learning
        # (Not used heavily, but could be extended)

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = 0.0
        self.coop_counts = {}
        self.total_interactions = {}
        self.own_recent = []
        self.observed_recent = {}
        self.last_action_against = {}
        self.generation = 0
        self.round_in_generation = 0
        self.total_rounds = 0
        # NEW: track a suspicion factor - how quickly we distrust others
        self.suspicion = 0.8  # 0.0 = never suspicious, 1.0 = instantly suspicious

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        opp_rep = self.get_rep(opponent)
        # If we have direct experience, weigh it with suspicion
        direct = self.last_action_against.get(opponent)
        if direct is not None:
            # If they defected last time, defect unless they have extremely high rep
            if direct == 'defect' and opp_rep < (3 - self.suspicion * 2):
                return False
            # If they cooperated last time, cooperate unless rep is very low
            if direct == 'cooperate' and opp_rep > (-3 + self.suspicion * 2):
                return True
        # Otherwise use reputation threshold, but suspicion raises threshold
        return opp_rep >= (0 + self.suspicion * 0.5)

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_action = recipient_action
                other_id = recipient_id
            else:
                my_action = recipient_action
                other_action = donor_action
                other_id = donor_id
            self.last_action_against[other_id] = other_action
            # Adjust own reputation: cooperate with cooperator +1, defect vs defector +1, else -1
            # Suspicion makes us more critical of our own failures
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
                self.reputation += 0.5 * (1 + self.suspicion * 0.2)
            else:
                self.reputation -= 0.5 * (1 + self.suspicion * 0.2)
            self.reputation = max(-10, min(10, self.reputation))
            self.own_recent.append(my_action)
            if len(self.own_recent) > 10:
                self.own_recent.pop(0)
            self.total_interactions[other_id] = self.total_interactions.get(other_id, 0) + 1
            if my_action == 'cooperate':
                self.coop_counts[other_id] = self.coop_counts.get(other_id, 0) + 1
        else:
            # Third-party observation: update reputation of both actors
            # Suspicion makes us penalize defectors more heavily
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.update_rep(donor_id, 0.3)
                self.update_rep(recipient_id, 0.3)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.update_rep(donor_id, 0.2)
                self.update_rep(recipient_id, 0.2)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.update_rep(donor_id, -0.3)
                # Defecting against cooperator is bad, suspicion amplifies it
                self.update_rep(recipient_id, -0.1 * (1 + self.suspicion))
            else:  # donor defect, recipient cooperate
                self.update_rep(donor_id, -0.1 * (1 + self.suspicion))
                self.update_rep(recipient_id, 0.3)
            for pid in (donor_id, recipient_id):
                if pid not in self.observed_recent:
                    self.observed_recent[pid] = []
                self.observed_recent[pid].append(donor_action if pid == donor_id else recipient_action)
                if len(self.observed_recent[pid]) > 10:
                    self.observed_recent[pid].pop(0)

    def get_rep(self, agent_id):
        rep = self.reputation if agent_id == self.agent_id else 0
        if agent_id in self.observed_recent:
            recent = self.observed_recent[agent_id]
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                # Suspicion reduces the positive effect of cooperation rate
                rep += (coop_rate - 0.5) * 2 * (1 - self.suspicion * 0.3)
        if agent_id in self.total_interactions and self.total_interactions[agent_id] > 0:
            coop_ratio = self.coop_counts.get(agent_id, 0) / self.total_interactions[agent_id]
            rep += (coop_ratio - 0.5) * 1
        # Suspicion increases negative penalty for past defections
        if agent_id in self.last_action_against and self.last_action_against[agent_id] == 'defect':
            rep -= self.suspicion * 0.5
        return rep

    def update_rep(self, agent_id, delta):
        if not hasattr(self, 'reps'):
            self.reps = {}
        self.reps[agent_id] = self.reps.get(agent_id, 0) + delta
        self.reps[agent_id] = max(-10, min(10, self.reps[agent_id]))

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.my_scores = []
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.partner_coop_count = 0
        self.partner_defect_count = 0
        self.total_interactions = 0
        self.partner_reputation = {}
        self.defect_penalty = 0.5
        self.coop_bonus = 0.3
        self.initial_trust = 0.5
        self.forgiveness = 0.2
        self.retaliation = 0.3
        self.memory = 10
        self.rep_weight = 0.9
        self.trust_weight = 0.1
        self.rep_decay = 0.95
        self.observation_trust_update = 0.05
        self.defect_penalty_obs = 0.12
        self.rep_uncertainty = {}
        self.uncertainty_decay = 0.9
        self.uncertainty_increase = 0.1
        # New: reciprocity memory to track how often we cooperate with each opponent
        self.reciprocity = {}
        self.reciprocity_threshold = 0.6
        # New: decay factor for reciprocity to make it more recent-focused
        self.reciprocity_decay = 0.9
        # Mutation: replace global bias with a per-opponent behavioral consistency score
        self.consistency = {}
        self.consistency_decay = 0.95
        self.consistency_alpha = 0.2
        # New: track a personal reputation (self-image) that influences decisions
        self.self_reputation = 0.5
        self.self_rep_inertia = 0.9
        # Mutation: add a forgiveness cap to limit how much forgiveness can be applied
        self.forgiveness_cap = 0.15
        # Mutation: add a threshold for when to use forgiveness based on partner's cooperation count
        self.forgiveness_coop_threshold = 3
        # New: track emotional state that influences decisions
        self.emotional_state = 0.5  # 0 = very distrustful, 1 = very trusting
        self.emotional_decay = 0.98  # decay towards neutral
        self.emotional_update_positive = 0.1
        self.emotional_update_negative = 0.2
        self.emotional_threshold = 0.55  # threshold for cooperation decision, adjusted by emotion
        # Mutation: add a separate memory for third-party observations to focus on reputation
        self.obs_reputation = {}
        self.obs_rep_decay = 0.9
        self.obs_rep_weight = 0.7  # weight for observed reputation vs direct interactions
        # New mutation: replace static threshold with dynamic threshold based on recent partner behavior
        self.dynamic_threshold_base = 0.5
        self.dynamic_threshold_adapt = 0.1
        self.dynamic_threshold = 0.5
        # New mutation: add a suspicion counter for each opponent to track repeated defections
        self.suspicion = {}
        self.suspicion_increase = 0.15
        self.suspicion_decay = 0.9
        self.suspicion_threshold = 0.5

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        self.last_opponent = opponent

        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, self.initial_trust)

        # Mutation: Use a weighted harmonic mean instead of weighted average to be more conservative
        # when either reputation or trust is low
        combined = 2 * (self.rep_weight * opp_rep) * (self.trust_weight * trust) / (
            self.rep_weight * opp_rep + self.trust_weight * trust + 1e-9
        )
        if opp_rep <= 0 or trust <= 0:
            combined = 0.0

        uncertainty = self.rep_uncertainty.get(opponent, 0.5)
        combined = combined * (1.0 - uncertainty * 0.3)

        if opponent in self.interactions:
            recent = self.interactions[opponent][-self.memory:]
            if len(recent) > 0:
                coop_rate = sum(1 for a, b in recent if a == 'cooperate' and b == 'cooperate') / len(recent)
                combined = 0.2 * combined + 0.8 * coop_rate

        # Emotional state modifies the threshold: if we're in a positive emotional state, we're more likely to cooperate
        # Mutation: use dynamic threshold that adapts based on partner's cooperation rate
        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            if len(recent) > 0:
                partner_coop_rate = sum(1 for a, b in recent if b == 'cooperate') / len(recent)
                # Adapt threshold: if partner cooperates a lot, lower threshold (more likely to cooperate)
                # If partner defects a lot, raise threshold (less likely to cooperate)
                self.dynamic_threshold = self.dynamic_threshold_base - self.dynamic_threshold_adapt * (partner_coop_rate - 0.5)
                self.dynamic_threshold = max(0.2, min(0.8, self.dynamic_threshold))
            else:
                self.dynamic_threshold = self.dynamic_threshold_base
        else:
            self.dynamic_threshold = self.dynamic_threshold_base

        threshold = self.dynamic_threshold + (random.random() - 0.5) * 0.1 - (self.emotional_state - 0.5) * 0.2

        if opponent in self.interactions:
            recent = self.interactions[opponent][-3:]
            if any(b == 'defect' for a, b in recent):
                combined -= self.retaliation

        # Mutation: forgiveness is now capped and requires a minimum number of partner cooperations
        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            coop_count = sum(1 for a, b in recent if b == 'cooperate')
            if coop_count >= self.forgiveness_coop_threshold and combined > 0.4:
                combined += min(self.forgiveness, self.forgiveness_cap)

        # New: reciprocity mechanism - if we've cooperated with this opponent a lot, boost cooperation
        if opponent in self.reciprocity:
            if self.reciprocity[opponent] >= self.reciprocity_threshold:
                combined += 0.15

        # New: add a penalty for opponents who defect often in recent memory, but with a softer touch
        if opponent in self.interactions:
            recent = self.interactions[opponent][-5:]
            if len(recent) > 0:
                defect_rate = sum(1 for a, b in recent if b == 'defect') / len(recent)
                if defect_rate > 0.6:
                    combined -= 0.1

        # Mutation: incorporate consistency - if opponent's behavior is predictable, adjust confidence
        if opponent in self.consistency:
            consistency = self.consistency[opponent]
            # High consistency (near 1) means predictable; low means unpredictable
            if consistency > 0.7:
                combined += 0.05 * (combined - 0.5)  # Amplify existing tendency
            elif consistency < 0.3:
                combined -= 0.05 * (combined - 0.5)  # Dampen tendency

        # Mutation: incorporate self_reputation - if we see ourselves as cooperative, be more cooperative
        combined += (self.self_reputation - 0.5) * 0.1

        # Mutation: incorporate observed reputation more heavily when we have no direct interactions
        if opponent in self.obs_reputation:
            obs_rep = self.obs_reputation[opponent]
            # Blend observed reputation with direct estimates
            if opponent in self.interactions:
                # Direct interactions exist, blend with a weight
                combined = (1 - self.obs_rep_weight) * combined + self.obs_rep_weight * obs_rep
            else:
                # No direct interactions, rely more on observed reputation
                combined = 0.7 * obs_rep + 0.3 * combined

        # New mutation: incorporate suspicion - if opponent has repeatedly defected, reduce cooperation
        if opponent in self.suspicion:
            suspicion = self.suspicion[opponent]
            if suspicion > self.suspicion_threshold:
                combined -= 0.2 * (suspicion - self.suspicion_threshold) / (1 - self.suspicion_threshold)

        return combined > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Mutation: update separate observed reputation for third-party observations
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            self._update_obs_reputation(donor_id, donor_action)
            self._update_obs_reputation(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self._record_own_interaction(donor_id, donor_action, recipient_id, recipient_action)

        self._update_trust_observation(donor_id, donor_action, recipient_id, recipient_action)
        self._track_interactions(donor_id, donor_action, recipient_id, recipient_action)

        # Mutation: update consistency scores for the observed agents
        self._update_consistency(donor_id, donor_action)
        self._update_consistency(recipient_id, recipient_action)

        # Mutation: update self-reputation based on our own actions
        if donor_id == self.agent_id:
            self._update_self_reputation(donor_action)
        if recipient_id == self.agent_id:
            self._update_self_reputation(recipient_action)

        # New: update emotional state based on observed interactions
        self._update_emotional_state(donor_action, recipient_action)

        # New mutation: update suspicion based on observed defections
        self._update_suspicion(donor_id, donor_action)
        self._update_suspicion(recipient_id, recipient_action)

        for agent in list(self.reputation.keys()):
            self.reputation[agent] = self.reputation[agent] * self.rep_decay
        for agent in list(self.rep_uncertainty.keys()):
            self.rep_uncertainty[agent] = self.rep_uncertainty[agent] * self.uncertainty_decay
        # New: decay reciprocity values to emphasize recent interactions
        for agent in list(self.reciprocity.keys()):
            self.reciprocity[agent] = self.reciprocity[agent] * self.reciprocity_decay
        # Mutation: decay consistency scores
        for agent in list(self.consistency.keys()):
            self.consistency[agent] = self.consistency[agent] * self.consistency_decay
        # Decay emotional state towards neutral
        self.emotional_state = 0.5 + (self.emotional_state - 0.5) * self.emotional_decay
        # Mutation: decay observed reputation
        for agent in list(self.obs_reputation.keys()):
            self.obs_reputation[agent] = self.obs_reputation[agent] * self.obs_rep_decay
        # New mutation: decay suspicion
        for agent in list(self.suspicion.keys()):
            self.suspicion[agent] = self.suspicion[agent] * self.suspicion_decay

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
            self.rep_uncertainty[agent_id] = 0.5
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + self.coop_bonus)
            self.rep_uncertainty[agent_id] = max(0.0, self.rep_uncertainty[agent_id] - self.uncertainty_increase)
        else:
            self.reputation[agent_id] = max(0.0, self.reputation[agent_id] - self.defect_penalty)
            self.rep_uncertainty[agent_id] = min(1.0, self.rep_uncertainty[agent_id] + self.uncertainty_increase)

    def _update_obs_reputation(self, agent_id: int, action: str) -> None:
        # Separate reputation based on third-party observations
        if agent_id not in self.obs_reputation:
            self.obs_reputation[agent_id] = 0.5
        if action == 'cooperate':
            self.obs_reputation[agent_id] = min(1.0, self.obs_reputation[agent_id] + 0.15)
        else:
            self.obs_reputation[agent_id] = max(0.0, self.obs_reputation[agent_id] - 0.25)

    def _record_own_interaction(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            my_action = donor_action
            opp_action = recipient_action
            opp_id = recipient_id
        else:
            my_action = recipient_action
            opp_action = donor_action
            opp_id = donor_id

        if opp_id not in self.interactions:
            self.interactions[opp_id] = []
        self.interactions[opp_id].append((my_action, opp_action))

        # New: track reciprocity - count how many times we cooperated with this opponent
        if opp_id not in self.reciprocity:
            self.reciprocity[opp_id] = 0
        if my_action == 'cooperate':
            self.reciprocity[opp_id] += 1

        if my_action == 'cooperate':
            self.cooperation_count += 1
        else:
            self.defection_count += 1

        if opp_id not in self.trust:
            self.trust[opp_id] = self.initial_trust
        if opp_action == 'cooperate':
            self.trust[opp_id] = min(1.0, self.trust[opp_id] + 0.1)
        else:
            self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

        if opp_id not in self.rep_uncertainty:
            self.rep_uncertainty[opp_id] = 0.5
        self.rep_uncertainty[opp_id] = max(0.0, self.rep_uncertainty[opp_id] - 0.2)

        self.total_interactions += 1

    def _update_trust_observation(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.trust:
            self.trust[donor_id] = self.initial_trust
        if recipient_id not in self.trust:
            self.trust[recipient_id] = self.initial_trust

        if donor_action == 'defect':
            self.trust[donor_id] = max(0.0, self.trust[donor_id] - self.defect_penalty_obs)
        else:
            self.trust[donor_id] = min(1.0, self.trust[donor_id] + self.observation_trust_update)

        if recipient_action == 'defect':
            self.trust[recipient_id] = max(0.0, self.trust[recipient_id] - self.defect_penalty_obs)
        else:
            self.trust[recipient_id] = min(1.0, self.trust[recipient_id] + self.observation_trust_update)

    def _track_interactions(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.partner_reputation:
            self.partner_reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.partner_reputation:
            self.partner_reputation[recipient_id] = {'coop': 0, 'defect': 0}

        if donor_action == 'cooperate':
            self.partner_reputation[donor_id]['coop'] += 1
        else:
            self.partner_reputation[donor_id]['defect'] += 1

        if recipient_action == 'cooperate':
            self.partner_reputation[recipient_id]['coop'] += 1
        else:
            self.partner_reputation[recipient_id]['defect'] += 1

        if donor_action == 'cooperate':
            self.cooperation_count += 0.1
        else:
            self.defection_count += 0.1

