class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.cooperation_history = {}
        self.my_reputation = {}
        self.round_count = 0
        self.opponent_history = {}
        self.trust_scores = {}
        self.cooperation_count = 0
        self.total_rounds = 0
        self.recent_actions = deque(maxlen=10)  # Track last 10 own actions
        self.defection_count = 0
        self.punishment_impulse = 0.0  # Emotional state that decays

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # Initialize trust if unknown
        if opponent not in self.trust_scores:
            self.trust_scores[opponent] = 0.5

        # Get reputation of opponent (their cooperation rate in general)
        rep = self.my_reputation.get(opponent, 0.5)
        if isinstance(rep, list):
            rep = sum(rep) / len(rep) if rep else 0.5

        # Personal history with opponent
        hist = self.opponent_history.get(opponent, [])
        if len(hist) > 0:
            past_coop = sum(hist) / len(hist)
        else:
            past_coop = 0.5

        # Combine trust, reputation, and recent behavior
        trust = self.trust_scores[opponent]
        combined_score = 0.4 * trust + 0.3 * rep + 0.3 * past_coop

        # Adaptive threshold based on overall environment
        if self.total_rounds > 0 and self.cooperation_count / self.total_rounds > 0.7:
            threshold = 0.55
        else:
            threshold = 0.45

        # Add punishment impulse: if recently defected against, more likely to defect
        combined_score -= self.punishment_impulse * 0.2

        # Slight randomness to avoid being too predictable
        if random.random() < 0.05:
            return random.random() < 0.5

        return combined_score > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_coop = 1 if donor_action == 'cooperate' else 0
        recipient_coop = 1 if recipient_action == 'cooperate' else 0

        # Update own reputation tracking for both participants
        if donor_id not in self.my_reputation:
            self.my_reputation[donor_id] = []
        if recipient_id not in self.my_reputation:
            self.my_reputation[recipient_id] = []

        self.my_reputation[donor_id].append(donor_coop)
        self.my_reputation[recipient_id].append(recipient_coop)

        # Update trust based on observed interactions
        self._update_trust(donor_id, recipient_id, donor_coop, recipient_coop)
        self._update_trust(recipient_id, donor_id, recipient_coop, donor_coop)

        # If this is our own interaction, update personal history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_count += 1
            self.total_rounds += 1
            if donor_id == self.agent_id:
                my_action = donor_coop
                opp_action = recipient_coop
                opp = recipient_id
            else:
                my_action = recipient_coop
                opp_action = donor_coop
                opp = donor_id

            self.recent_actions.append(my_action)
            if my_action == 1:
                self.cooperation_count += 1
            else:
                self.defection_count += 1

            if opp not in self.opponent_history:
                self.opponent_history[opp] = []
            self.opponent_history[opp].append(opp_action)

            # Update trust based on outcome
            if my_action == 1 and opp_action == 1:
                self.trust_scores[opp] = min(1.0, self.trust_scores.get(opp, 0.5) + 0.1)
            elif my_action == 1 and opp_action == 0:
                self.trust_scores[opp] = max(0.0, self.trust_scores.get(opp, 0.5) - 0.2)
                # Increase punishment impulse when betrayed
                self.punishment_impulse = min(1.0, self.punishment_impulse + 0.3)
            elif my_action == 0 and opp_action == 1:
                self.trust_scores[opp] = min(1.0, self.trust_scores.get(opp, 0.5) + 0.05)
            else:
                self.trust_scores[opp] = max(0.0, self.trust_scores.get(opp, 0.5) - 0.05)

        # Decay punishment impulse slowly over time
        self.punishment_impulse *= 0.95

    def _update_trust(self, observer_id: int, target_id: int, observer_action: int, target_action: int) -> None:
        # This function updates trust based on third-party observations
        if target_id not in self.trust_scores:
            self.trust_scores[target_id] = 0.5

        # If target cooperated when observer cooperated, they are trustworthy
        if observer_action == 1 and target_action == 1:
            self.trust_scores[target_id] = min(1.0, self.trust_scores[target_id] + 0.02)
        elif observer_action == 1 and target_action == 0:
            self.trust_scores[target_id] = max(0.0, self.trust_scores[target_id] - 0.03)
            # Third-party observation of betrayal also slightly increases impulse
            self.punishment_impulse = min(1.0, self.punishment_impulse + 0.01)
        elif observer_action == 0 and target_action == 1:
            self.trust_scores[target_id] = min(1.0, self.trust_scores[target_id] + 0.01)
        else:
            self.trust_scores[target_id] = max(0.0, self.trust_scores[target_id] - 0.01)

