from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.trust = {}
        self.cooperation_count = 0
        self.defection_count = 0
        self.total_interactions = 0
        self.generation = 0
        self.round_in_generation = 0
        self.my_recent_actions = deque(maxlen=5)
        self.opponent_recent_actions = deque(maxlen=5)
        self._ctx_opponent_id = None
        self.last_decision = None
        self.memory = deque(maxlen=50)
        self.opponent_behavior_history = {}
        self.trust_decay = 0.95
        # New: social influence factor - how much third-party observations affect trust
        self.social_influence = 0.5
        # New: track frequency of observed interactions for each agent
        self.observed_interaction_count = {}
        # New: track recent pattern of own decisions for mood-based adjustment
        self.mood = 0.0  # positive = optimistic, negative = pessimistic

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        if opponent not in self.reputation:
            self.reputation[opponent] = 0.5
        if opponent not in self.trust:
            self.trust[opponent] = 0.5
        if opponent not in self.opponent_behavior_history:
            self.opponent_behavior_history[opponent] = deque(maxlen=10)

        history = self.interactions.get(opponent, [])

        coop_rate = 0.5
        if history:
            opponent_coops = sum(1 for _, opp_action, _ in history if opp_action)
            coop_rate = opponent_coops / len(history)

        recent = history[-5:] if history else []
        recent_coop_rate = 0.5
        if recent:
            recent_coops = sum(1 for _, opp_action, _ in recent if opp_action)
            recent_coop_rate = recent_coops / len(recent)

        opp_reputation = self.reputation.get(opponent, 0.5)

        observed_history = self.opponent_behavior_history.get(opponent, [])
        observed_coop_rate = 0.5
        if observed_history:
            observed_coops = sum(1 for action in observed_history if action)
            observed_coop_rate = observed_coops / len(observed_history)

        old_trust = self.trust.get(opponent, 0.5)
        decayed_trust = old_trust * self.trust_decay

        # Modified: stronger emphasis on observed behavior (social influence)
        trust_score = 0.2 * coop_rate + 0.2 * recent_coop_rate + 0.2 * opp_reputation + 0.4 * observed_coop_rate
        trust_score = max(0, min(1, trust_score))
        self.trust[opponent] = 0.7 * trust_score + 0.3 * decayed_trust

        # Mood adjustment: add a small bias based on recent personal outcomes
        mood_bias = 0.0
        if self.memory:
            # Count recent wins (mutual cooperation) vs losses (being exploited)
            wins = sum(1 for my_a, their_a in self.memory[-10:] if my_a and their_a)
            losses = sum(1 for my_a, their_a in self.memory[-10:] if my_a and not their_a)
            if len(self.memory) >= 5:
                mood_bias = (wins - losses) * 0.02
                self.mood = max(-0.2, min(0.2, self.mood * 0.9 + mood_bias))

        if not history:
            # First meeting: cooperate with high probability, adjusted by mood
            return random.random() < (0.8 + self.mood)

        if recent and recent_coop_rate < 0.4:
            return False

        if history and not history[-1][1]:
            forgiveness_rate = 0.2 + 0.3 * self.trust[opponent] + self.mood
            forgiveness_rate = max(0, min(1, forgiveness_rate))
            if random.random() < forgiveness_rate:
                return True
            return False

        if recent_coop_rate > 0.7:
            return True
        elif recent_coop_rate < 0.3:
            return False
        else:
            prob_cooperate = self.trust[opponent] + self.mood
            prob_cooperate = max(0, min(1, prob_cooperate))
            return random.random() < prob_cooperate

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_coop = donor_action == 'cooperate'
        recipient_coop = recipient_action == 'cooperate'

        # Track observed interaction counts for social influence
        for actor_id in [donor_id, recipient_id]:
            if actor_id not in self.observed_interaction_count:
                self.observed_interaction_count[actor_id] = 0
            self.observed_interaction_count[actor_id] += 1

        # Reputation updates - modified to be more sensitive to context
        for actor_id, action in [(donor_id, donor_coop), (recipient_id, recipient_coop)]:
            if actor_id not in self.reputation:
                self.reputation[actor_id] = 0.5

            partner_action = recipient_coop if actor_id == donor_id else donor_coop

            # More nuanced reputation updates
            if action and partner_action:
                delta = 0.15  # Stronger reward for mutual cooperation
            elif action and not partner_action:
                delta = -0.08  # More punishment for being exploited
            elif not action and partner_action:
                delta = -0.2  # Stronger punishment for defecting against cooperator
            else:
                delta = 0.0  # Neutral for mutual defection

            self.reputation[actor_id] = max(0, min(1, self.reputation[actor_id] + delta))

        # Track interactions involving self
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_coop if donor_id == self.agent_id else recipient_coop
            their_action = recipient_coop if donor_id == self.agent_id else donor_coop

            if other_id not in self.interactions:
                self.interactions[other_id] = []
            self.interactions[other_id].append((my_action, their_action, 0))

            if my_action:
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            self.total_interactions += 1

            if len(self.interactions[other_id]) > 20:
                self.interactions[other_id] = self.interactions[other_id][-20:]

            self.my_recent_actions.append(my_action)
            self.opponent_recent_actions.append(their_action)
            self.memory.append((my_action, their_action))
        else:
            # Third-party observation - stronger social influence
            if donor_id not in self.trust:
                self.trust[donor_id] = 0.5
            if recipient_id not in self.trust:
                self.trust[recipient_id] = 0.5

            # Weight updates by social influence factor
            influence = self.social_influence
            if donor_coop and recipient_coop:
                self.trust[donor_id] = max(0, min(1, self.trust[donor_id] + 0.03 * influence))
                self.trust[recipient_id] = max(0, min(1, self.trust[recipient_id] + 0.03 * influence))
            elif donor_coop and not recipient_coop:
                self.trust[donor_id] = max(0, min(1, self.trust[donor_id] - 0.02 * influence))
                self.trust[recipient_id] = max(0, min(1, self.trust[recipient_id] - 0.05 * influence))
            elif not donor_coop and recipient_coop:
                self.trust[donor_id] = max(0, min(1, self.trust[donor_id] - 0.05 * influence))
                self.trust[recipient_id] = max(0, min(1, self.trust[recipient_id] - 0.02 * influence))
            else:
                self.trust[donor_id] = max(0, min(1, self.trust[donor_id] - 0.03 * influence))
                self.trust[recipient_id] = max(0, min(1, self.trust[recipient_id] - 0.03 * influence))

            if donor_id not in self.opponent_behavior_history:
                self.opponent_behavior_history[donor_id] = deque(maxlen=10)
            if recipient_id not in self.opponent_behavior_history:
                self.opponent_behavior_history[recipient_id] = deque(maxlen=10)

            self.opponent_behavior_history[donor_id].append(donor_coop)
            self.opponent_behavior_history[recipient_id].append(recipient_coop)

