                              if self.action_history[other_id][i] == self.action_history[other_id][i-1])
                match_ratio = matches / (len(self.action_history[other_id]) - 1)
                # If they are consistent, we become more reciprocal
                if match_ratio > 0.7:
                    self.reciprocity = min(1.5, self.reciprocity + 0.05)
                elif match_ratio < 0.3:
                    self.reciprocity = max(0.5, self.reciprocity - 0.05)
        else:
            # Third-party observation: update reputation of both actors
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
