        # even with moderately negative reputation, especially if the opponent
        # has cooperated in the recent past
        self.generosity = 0.3
        # NEW: Track the last action taken against each opponent to weight
        # recent direct interactions more heavily
        self.last_direct_action = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        opp_rep = self.get_rep(opponent)
        # If we have direct experience, weigh it more, but with a bias toward
        # cooperation if the opponent has a decent reputation
        direct = self.last_action_against.get(opponent)
        if direct is not None:
            # If they defected last time, defect unless their reputation is very high
            if direct == 'defect' and opp_rep < 2 - self.forgiveness * 10:
                return False
            # If they cooperated last time, cooperate unless their reputation is very low
            if direct == 'cooperate' and opp_rep > -2 + self.forgiveness * 10:
                return True
        # Otherwise use reputation threshold, but add a generosity bonus
        # that makes us cooperate with slightly negative reputations
        suspicion_level = self.suspicion.get(opponent, 0)
        if suspicion_level > 0:
            # If we have observed them defecting a lot, be more cautious
            if opp_rep < suspicion_level * 0.5 - self.generosity:
                return False
        # Cooperate if reputation is above a lower threshold due to generosity
        return opp_rep >= -self.generosity

