                return False
            if direct == 'cooperate' and self.get_rep(opponent) > -2:
                return True

        # New: reciprocity check - if opponent has been generous recently, cooperate
        gen = self.generosity.get(opponent, 0.0)
        if gen > 0.5:
            return True
        if gen < -0.5:
            return False

        # Default to reputation-based decision
        return self.get_rep(opponent) >= threshold

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Update reputation based on actions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_action = recipient_action
                other_id = recipient_id
            else:
                my_action = recipient_action
                other_action = donor_action
                other_id = donor_id

            self.last_action_against[other_id] = other_action
            # Update generosity based on our action towards them
            if my_action == 'cooperate':
                self.generosity[other_id] = self.generosity.get(other_id, 0.0) + 0.3
            else:
                self.generosity[other_id] = self.generosity.get(other_id, 0.0) - 0.3
            # Clamp generosity
            self.generosity[other_id] = max(-1.0, min(1.0, self.generosity[other_id]))

            # Reputation update
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
                self.reputation += 0.5
            else:
                self.reputation -= 0.5
            self.reputation = max(-10, min(10, self.reputation))
            self.own_recent.append(my_action)
            self.recent_own_actions.append(my_action)
            self.rep_history.append(self.reputation)
            self.total_interactions[other_id] = self.total_interactions.get(other_id, 0) + 1
            if my_action == 'cooperate':
                self.coop_counts[other_id] = self.coop_counts.get(other_id, 0) + 1
        else:
            # Third-party observation
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.update_rep(donor_id, 0.3)
                self.update_rep(recipient_id, 0.3)
                # Update generosity: both were generous
                self.generosity[donor_id] = self.generosity.get(donor_id, 0.0) + 0.1
                self.generosity[recipient_id] = self.generosity.get(recipient_id, 0.0) + 0.1
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.update_rep(donor_id, 0.2)
                self.update_rep(recipient_id, 0.2)
                # Update generosity: both were stingy
                self.generosity[donor_id] = self.generosity.get(donor_id, 0.0) - 0.1
                self.generosity[recipient_id] = self.generosity.get(recipient_id, 0.0) - 0.1
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.update_rep(donor_id, -0.3)
                self.update_rep(recipient_id, -0.1)
                # Donor generous, recipient stingy
                self.generosity[donor_id] = self.generosity.get(donor_id, 0.0) + 0.2
                self.generosity[recipient_id] = self.generosity.get(recipient_id, 0.0) - 0.2
            else:  # donor defect, recipient cooperate
                self.update_rep(donor_id, -0.1)
                self.update_rep(recipient_id, 0.3)
                # Donor stingy, recipient generous
                self.generosity[donor_id] = self.generosity.get(donor_id, 0.0) - 0.2
                self.generosity[recipient_id] = self.generosity.get(recipient_id, 0.0) + 0.2

            # Clamp generosity values
            for pid in (donor_id, recipient_id):
                if pid in self.generosity:
                    self.generosity[pid] = max(-1.0, min(1.0, self.generosity[pid]))

            # Update observed recent
            for pid in (donor_id, recipient_id):
                if pid not in self.observed_recent:
                    self.observed_recent[pid] = deque(maxlen=10)
                    self.observation_counts[pid] = 0
                self.observed_recent[pid].append(donor_action if pid == donor_id else recipient_action)
                self.observation_counts[pid] += 1

        # Decay all stored reputations
        for pid in self.decayed_reps:
            self.decayed_reps[pid] *= self.rep_decay

        # Decay generosity values slightly to avoid permanent grudges
        for pid in list(self.generosity.keys()):
            self.generosity[pid] *= 0.95
            if abs(self.generosity[pid]) < 0.05:
                del self.generosity[pid]

    def get_rep(self, agent_id):
        rep = self.reputation if agent_id == self.agent_id else 0
        if agent_id in self.observed_recent:
            recent = self.observed_recent[agent_id]
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                weight = min(1.0, self.observation_counts.get(agent_id, 0) / 5.0)
                rep += (coop_rate - 0.5) * 2 * weight
        if agent_id in self.total_interactions and self.total_interactions[agent_id] > 0:
            coop_ratio = self.coop_counts.get(agent_id, 0) / self.total_interactions[agent_id]
            rep += (coop_ratio - 0.5) * 1
        if agent_id in self.decayed_reps:
            rep += self.decayed_reps[agent_id]
        return rep

    def update_rep(self, agent_id, delta):
        if not hasattr(self, 'reps'):
            self.reps = {}
        self.reps[agent_id] = self.reps.get(agent_id, 0) + delta
        self.reps[agent_id] = max(-10, min(10, self.reps[agent_id]))
        self.decayed_reps[agent_id] = self.decayed_reps.get(agent_id, 0) * self.rep_decay + delta

