        self.own_actions = []  # list of (opponent_id, my_action)
        self.recent_actions = {}  # agent_id -> list of recent actions (cooperate/defect)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.round_num += 1

        # If we have a history with this opponent, use reputation-based strategy
        if opponent in self.reputation:
            rep = self.reputation.get(opponent, 0)
            # Trust threshold: cooperate if reputation is positive enough
            if rep >= 0.2:
                return True
            elif rep <= -0.2:
                return False
            else:
                # For borderline, use tit-for-tat from last interaction
                if opponent in self.personal_coop or opponent in self.personal_defect:
                    # Check last personal interaction
                    last_interaction = None
                    for (d, r) in self.history:
                        if (d == self.agent_id and r == opponent) or (d == opponent and r == self.agent_id):
                            last_interaction = self.history[(d, r)][-1]
                    if last_interaction:
                        # If opponent cooperated last time, cooperate; if defected, defect
                        if opponent in self.personal_defect and self.personal_defect.get(opponent, 0) > self.personal_coop.get(opponent, 0):
                            return False
                        else:
                            return True
                    else:
                        return True
        else:
            # No reputation yet: default to cooperate
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        key = (donor_id, recipient_id)
        if key not in self.history:
            self.history[key] = []
        self.history[key].append((donor_action, recipient_action))
        self.observed_interactions += 1

        # Update reputation for both agents based on their actions
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0
            if action == 'cooperate':
