        # Track personal interactions
        if donor_id == self.agent_id:
            # We were the donor
            self.own_actions.append((recipient_id, donor_action))
            if donor_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            if recipient_id not in self.personal_defect:
                self.personal_defect[recipient_id] = 0
            if recipient_id not in self.personal_coop:
                self.personal_coop[recipient_id] = 0
            if recipient_action == 'cooperate':
                self.personal_coop[recipient_id] += 1
