        # Adjust threshold based on current generosity
        threshold = -self.generosity
        if direct is not None:
            if direct == 'defect' and opp_rep < 2 - self.forgiveness * 10:
                return False
            if direct == 'cooperate' and opp_rep > -2 + self.forgiveness * 10:
                return True
        suspicion_level = self.suspicion.get(opponent, 0)
        if suspicion_level > 0:
            if opp_rep < suspicion_level * 0.5:
