            self.trust[other_id] = max(-1.0, min(1.0, self.trust[other_id]))
            if other_action == 'defect':
                self.suspicion[other_id] = self.suspicion.get(other_id, 0) + 1
            else:
                self.suspicion[other_id] = max(0, self.suspicion.get(other_id, 0) - 0.5)
