            if my_action == 'cooperate':
                self.own_coop_count += 1
            # Generosity drifts toward average cooperation rate, but slowly
            if self.own_total_count > 0:
                current_coop_rate = self.own_coop_count / self.own_total_count
                # Update generosity with a small learning rate, clamped to [-1, 1]
                self.generosity += 0.05 * (current_coop_rate - 0.5 - self.generosity)
                self.generosity = max(-1.0, min(1.0, self.generosity))
        else:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
