                self.update_rep(recipient_id, 0.3)
            if donor_action == 'defect':
                self.suspicion[donor_id] = self.suspicion.get(donor_id, 0) + 0.3
            else:
                self.suspicion[donor_id] = max(0, self.suspicion.get(donor_id, 0) - 0.1)
            if recipient_action == 'defect':
                self.suspicion[recipient_id] = self.suspicion.get(recipient_id, 0) + 0.3
            else:
