        # Direct experience overrides if we have a strong signal
        if opponent in self.direct_history:
            recent = self.direct_history[opponent]
            if len(recent) >= 3:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                if coop_rate > 0.6:
