        self.round_in_generation = 0
        self.total_rounds = 0
        # NEW: Use a queue of recent reputation updates per agent instead of a single value
        self.rep_history = {}
        # NEW: Forgiveness factor - now dynamic, subject to own mood
        self.base_forgiveness = 0.1
        self.mood = 0.0  # positive if we've been treated well recently
        # NEW: Trust - now a decaying average of direct interaction outcomes
        self.trust = {}
        # NEW: Suspicion - now a decaying counter
        self.suspicion = {}
        # NEW: A memory of the last action taken by each opponent, to detect pattern changes
        self.last_actions = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Adjust forgiveness based on mood: good mood -> more forgiving, bad mood -> less
        forgiveness = self.base_forgiveness + self.mood * 0.05
        forgiveness = max(0.0, min(0.5, forgiveness))
        # Get a robust reputation estimate from the history queue
        opp_rep = self.get_rep(opponent)
        direct = self.last_action_against.get(opponent)
        if direct is not None:
            if direct == 'defect' and opp_rep < 2 - forgiveness * 10:
                return False
            if direct == 'cooperate' and opp_rep > -2 + forgiveness * 10:
                return True
        suspicion_level = self.suspicion.get(opponent, 0)
        if suspicion_level > 0:
            if opp_rep < suspicion_level * 0.5:
                return False
        return opp_rep >= 0

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_action = recipient_action
                other_id = recipient_id
            else:
                my_action = recipient_action
                other_action = donor_action
                other_id = donor_id
            self.last_action_against[other_id] = other_action
            # Update mood: cooperate with cooperator or defect vs defector improves mood
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
                self.mood = min(1.0, self.mood + 0.1)
            else:
                self.mood = max(-1.0, self.mood - 0.1)
            # Update own reputation with consistency bonus
            consistency_bonus = 0.0
            if self.own_recent:
                if my_action == 'cooperate' and sum(1 for a in self.own_recent if a == 'cooperate') > len(self.own_recent) * 0.7:
                    consistency_bonus = 0.1
                elif my_action == 'defect' and sum(1 for a in self.own_recent if a == 'defect') > len(self.own_recent) * 0.7:
                    consistency_bonus = 0.1
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
