            if my_action == 1:
                self.cooperation_count += 1
                self.forgiveness_bias = min(1.0, self.forgiveness_bias + 0.05)
            else:
                self.defection_count += 1
                self.forgiveness_bias = max(0.0, self.forgiveness_bias - 0.1)

            # New: Update opponent streak based on their action
            if opp not in self.opponent_streaks:
                self.opponent_streaks[opp] = 0
            if opp_action == 1:
                self.opponent_streaks[opp] = min(5, self.opponent_streaks[opp] + 1)
            else:
