        suspicion_level = self.suspicion.get(opponent, 0)
        if suspicion_level > 0:
            if opp_rep < suspicion_level * 0.5:
                return False
        return opp_rep >= 0

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_action = recipient_action
                other_id = recipient_id
            else:
                my_action = recipient_action
                other_action = donor_action
                other_id = donor_id
            self.last_action_against[other_id] = other_action
            # Update mood: cooperate with cooperator or defect vs defector improves mood
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
                self.mood = min(1.0, self.mood + 0.1)
            else:
                self.mood = max(-1.0, self.mood - 0.1)
            # Update own reputation with consistency bonus
            consistency_bonus = 0.0
            if self.own_recent:
                if my_action == 'cooperate' and sum(1 for a in self.own_recent if a == 'cooperate') > len(self.own_recent) * 0.7:
                    consistency_bonus = 0.1
                elif my_action == 'defect' and sum(1 for a in self.own_recent if a == 'defect') > len(self.own_recent) * 0.7:
                    consistency_bonus = 0.1
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
                self.reputation += 0.5 + consistency_bonus
            else:
                self.reputation -= 0.5
            self.reputation = max(-10, min(10, self.reputation))
            self.own_recent.append(my_action)
            self.total_interactions[other_id] = self.total_interactions.get(other_id, 0) + 1
            if my_action == 'cooperate':
                self.coop_counts[other_id] = self.coop_counts.get(other_id, 0) + 1

            # NEW: Update trust with a more responsive learning rate, bounded by mood
            # Positive mood -> trust increases faster, negative mood -> decreases faster
            if other_id not in self.trust:
                self.trust[other_id] = 0.0
            delta = 1.0 if other_action == 'cooperate' else -1.0
            alpha = 0.3 / (1 + self.total_interactions.get(other_id, 0) * 0.05)
            # Mood influences alpha: positive mood makes us more trusting, negative less
            alpha = alpha * (1.0 + self.mood * 0.2)
            alpha = max(0.0, min(1.0, alpha))
            self.trust[other_id] = (1 - alpha) * self.trust[other_id] + alpha * delta
            self.trust[other_id] = max(-1.0, min(1.0, self.trust[other_id]))

            # NEW: Suspicion now decays faster when mood is positive
            decay = 0.5 if self.mood > 0 else 1.0
            if other_action == 'defect':
                self.suspicion[other_id] = self.suspicion.get(other_id, 0) + decay
            else:
                self.suspicion[other_id] = max(0, self.suspicion.get(other_id, 0) - 0.5 * decay)

            # NEW: Track the last action to detect pattern changes (e.g., switching from cooperate to defect)
            if other_id not in self.last_actions:
                self.last_actions[other_id] = deque(maxlen=3)
            self.last_actions[other_id].append(other_action)

        else:
            # Third-party observation: update reputation with bounded update per observation
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.update_rep(donor_id, 0.3)
                self.update_rep(recipient_id, 0.3)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.update_rep(donor_id, 0.2)
                self.update_rep(recipient_id, 0.2)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.update_rep(donor_id, -0.3)
                self.update_rep(recipient_id, -0.1)
            else:
                self.update_rep(donor_id, -0.1)
                self.update_rep(recipient_id, 0.3)
            # Update suspicion with decay
            decay = 0.5 if self.mood > 0 else 1.0
            if donor_action == 'defect':
                self.suspicion[donor_id] = self.suspicion.get(donor_id, 0) + 0.3 * decay
            else:
                self.suspicion[donor_id] = max(0, self.suspicion.get(donor_id, 0) - 0.1 * decay)
            if recipient_action == 'defect':
                self.suspicion[recipient_id] = self.suspicion.get(recipient_id, 0) + 0.3 * decay
            else:
                self.suspicion[recipient_id] = max(0, self.suspicion.get(recipient_id, 0) - 0.1 * decay)
            for pid in (donor_id, recipient_id):
                if pid not in self.observed_recent:
                    self.observed_recent[pid] = deque(maxlen=10)
                self.observed_recent[pid].append(donor_action if pid == donor_id else recipient_action)

    def get_rep(self, agent_id):
        # Combine reputation with observed recent cooperation rate
        rep = self.reputation if agent_id == self.agent_id else 0
        if agent_id in self.rep_history:
            # Use a robust estimate: median of recent reputation updates, with decay
            # This makes us less susceptible to extreme single observations
            hist = list(self.rep_history[agent_id])
            if hist:
                # Sort and take median
                hist.sort()
                median = hist[len(hist) // 2]
                # Decay the median based on time
                rep += median * (1 - 0.1 * len(hist))
        if agent_id in self.observed_recent:
            recent = list(self.observed_recent[agent_id])
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                rep += (coop_rate - 0.5) * 2
        if agent_id in self.total_interactions and self.total_interactions[agent_id] > 0:
            coop_ratio = self.coop_counts.get(agent_id, 0) / self.total_interactions[agent_id]
            rep += (coop_ratio - 0.5) * 1

        # NEW: Trust weighting is now mood-dependent - we trust more when in good mood
        if agent_id in self.trust:
            rep += self.trust[agent_id] * (2 + self.mood)

        # NEW: Suspicion penalty now scales with mood - we punish more when in bad mood
        suspicion_level = self.suspicion.get(agent_id, 0)
        if suspicion_level > 0:
            rep -= suspicion_level * (0.5 + max(0, -self.mood) * 0.5)

        # NEW: Pattern detection - if the opponent has been cooperative recently but now defects, penalize more
        if agent_id in self.last_actions:
            recent_actions = list(self.last_actions[agent_id])
            if len(recent_actions) >= 2:
                last_action = recent_actions[-1]
                prev_action = recent_actions[-2]
                if prev_action == 'cooperate' and last_action == 'defect':
                    rep -= 0.5  # Extra penalty for betrayal
                elif prev_action == 'defect' and last_action == 'cooperate':
                    rep += 0.3  # Reward for switching to cooperation

        return rep

    def update_rep(self, agent_id, delta):
        # NEW: Store recent reputation updates in a queue, capped at 20
        if agent_id not in self.rep_history:
            self.rep_history[agent_id] = deque(maxlen=20)
        self.rep_history[agent_id].append(delta)
        # Also decay old updates implicitly by removing them when full

