            if recent_defections > 7:
                return False
            return True

        reputation = coop_count / total_obs

        # More nuanced reputation-based decision with tolerance parameter
        if reputation > self.tolerance:
            return True
        elif reputation < (1 - self.tolerance):
            return False

        # For intermediate reputation, use tit-for-tat with forgiveness
        if self.opponent_id in self.interactions:
            last_interaction = self.interactions[self.opponent_id][-1]
            if last_interaction[1] == 'defect':
                if random.random() < self.forgiveness:
                    return True
                return False
            else:
                return True
        else:
