            # We store a counter of positive interactions and negative interactions
            if other_id not in self.trust:
                self.trust[other_id] = {'coop': 0, 'defect': 0}
            if other_action == 'cooperate':
                self.trust[other_id]['coop'] += 1
            else:
                self.trust[other_id]['defect'] += 1
            # Trust value is the ratio of cooperations, but capped at 10 interactions
            total = self.trust[other_id]['coop'] + self.trust[other_id]['defect']
            if total > 10:
                # Decay: halve the counts when total exceeds 10
                self.trust[other_id]['coop'] = int(self.trust[other_id]['coop'] * 0.5)
                self.trust[other_id]['defect'] = int(self.trust[other_id]['defect'] * 0.5)
            # CHANGED: Suspicion is a simple count of defections, not decaying
            if other_action == 'defect':
                self.suspicion[other_id] = self.suspicion.get(other_id, 0) + 1
            else:
                # Keep suspicion, but don't decay it
                pass
        else:
            # Third-party observation: update reputation with bounded update per observation
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.update_rep(donor_id, 0.3)
                self.update_rep(recipient_id, 0.3)
