                self.update_rep(donor_id, -0.1)
                self.update_rep(recipient_id, 0.3)
            # CHANGED: Suspicion is a simple count, no decay
            if donor_action == 'defect':
                self.suspicion[donor_id] = self.suspicion.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.suspicion[recipient_id] = self.suspicion.get(recipient_id, 0) + 1
            for pid in (donor_id, recipient_id):
                if pid not in self.observed_recent:
                    self.observed_recent[pid] = deque(maxlen=10)
                self.observed_recent[pid].append(donor_action if pid == donor_id else recipient_action)

    def get_rep(self, agent_id):
        # Combine reputation with observed recent cooperation rate
        rep = self.reputation if agent_id == self.agent_id else 0
        if agent_id in self.rep_cache:
            # CHANGED: Use a single cached reputation with decay
            rep += self.rep_cache[agent_id] * 0.9
        if agent_id in self.observed_recent:
            recent = list(self.observed_recent[agent_id])
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                rep += (coop_rate - 0.5) * 2
        if agent_id in self.total_interactions and self.total_interactions[agent_id] > 0:
            coop_ratio = self.coop_counts.get(agent_id, 0) / self.total_interactions[agent_id]
            rep += (coop_ratio - 0.5) * 1

        # CHANGED: Trust is a ratio of cooperations, no mood influence
        if agent_id in self.trust:
            total = self.trust[agent_id]['coop'] + self.trust[agent_id]['defect']
            if total > 0:
                trust_ratio = self.trust[agent_id]['coop'] / total
                rep += (trust_ratio - 0.5) * 2

        # CHANGED: Suspicion penalty is linear with count, no mood influence
        suspicion_level = self.suspicion.get(agent_id, 0)
        if suspicion_level > 0:
            rep -= suspicion_level * 0.5

        return rep

    def update_rep(self, agent_id, delta):
        # CHANGED: Update a single reputation with decay
        if agent_id in self.rep_cache:
            self.rep_cache[agent_id] = self.rep_cache[agent_id] * 0.9 + delta
        else:
            self.rep_cache[agent_id] = delta
        # Clamp to reasonable range
        self.rep_cache[agent_id] = max(-5, min(5, self.rep_cache[agent_id]))

