import math
import random
from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.cooperation_history = {}
        self.my_reputation = {}
        self.round_count = 0
        self.opponent_history = {}
        self.trust_scores = {}
        self.cooperation_count = 0
        self.total_rounds = 0
        self.recent_actions = deque(maxlen=10)
        self.defection_count = 0
        self.punishment_impulse = 0.0
        self.recent_opponent_actions = {}
        self.forgiveness_bias = 0.0
        self.reputation_volatility = {}
        self.base_trust = 0.45
        # New: Track a short-term "grudge" factor that decays quickly
        self.grudges = {}
        # New: Track a long-term "loyalty" bonus for consistently cooperative agents
        self.loyalty_bonus = {}
        # New: Adaptively adjust base trust based on overall population behavior
        self.population_coop_rate = 0.5

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        if opponent not in self.trust_scores:
            self.trust_scores[opponent] = self.base_trust

        rep = self.my_reputation.get(opponent, 0.5)
        if isinstance(rep, list):
            rep = sum(rep) / len(rep) if rep else 0.5

        hist = self.opponent_history.get(opponent, [])
        if len(hist) > 0:
            past_coop = sum(hist) / len(hist)
        else:
            past_coop = 0.5

        trust = self.trust_scores[opponent]
        recent_opp = self.recent_opponent_actions.get(opponent, [])
        if len(recent_opp) > 0:
            recent_coop = sum(recent_opp) / len(recent_opp)
        else:
            recent_coop = 0.5

        vol = self.reputation_volatility.get(opponent, 0.0)
        if vol > 0.3:
            combined_score = 0.2 * trust + 0.1 * rep + 0.1 * past_coop + 0.6 * recent_coop
        else:
            combined_score = 0.4 * trust + 0.2 * rep + 0.3 * past_coop + 0.1 * recent_coop

        if self.total_rounds > 0 and self.cooperation_count / self.total_rounds > 0.6:
            threshold = 0.50
        else:
            threshold = 0.40

        combined_score -= self.punishment_impulse * 0.15
        combined_score += self.forgiveness_bias * 0.15

        # New: Incorporate grudge factor (strong penalty for recent defections)
        grudge = self.grudges.get(opponent, 0.0)
        combined_score -= grudge * 0.4

        # New: Add loyalty bonus for agents that have been consistently cooperative in long-term history
        loyalty = self.loyalty_bonus.get(opponent, 0.0)
        combined_score += loyalty * 0.1

        # New: Adaptive threshold based on population cooperation rate
        threshold += (0.5 - self.population_coop_rate) * 0.1

        if random.random() < 0.03:
            return random.random() < 0.5

        return combined_score > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_coop = 1 if donor_action == 'cooperate' else 0
        recipient_coop = 1 if recipient_action == 'cooperate' else 0

        if donor_id not in self.my_reputation:
            self.my_reputation[donor_id] = []
        if recipient_id not in self.my_reputation:
            self.my_reputation[recipient_id] = []

        self.my_reputation[donor_id].append(donor_coop)
        self.my_reputation[recipient_id].append(recipient_coop)

        self._update_volatility(donor_id, donor_coop)
        self._update_volatility(recipient_id, recipient_coop)

        self._update_trust(donor_id, recipient_id, donor_coop, recipient_coop)
        self._update_trust(recipient_id, donor_id, recipient_coop, donor_coop)

        if donor_id != self.agent_id:
            self._update_recent_opponent(donor_id, donor_coop)
        if recipient_id != self.agent_id:
            self._update_recent_opponent(recipient_id, recipient_coop)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_count += 1
            self.total_rounds += 1
            if donor_id == self.agent_id:
                my_action = donor_coop
                opp_action = recipient_coop
                opp = recipient_id
            else:
                my_action = recipient_coop
                opp_action = donor_coop
                opp = donor_id

            self.recent_actions.append(my_action)
            if my_action == 1:
                self.cooperation_count += 1
                self.forgiveness_bias = min(1.0, self.forgiveness_bias + 0.08)
            else:
                self.defection_count += 1
                self.forgiveness_bias = max(0.0, self.forgiveness_bias - 0.15)

