                self.opponent_history[opp] = []
            self.opponent_history[opp].append(opp_action)

            if my_action == 1 and opp_action == 1:
                self.trust_scores[opp] = min(1.0, self.trust_scores.get(opp, self.base_trust) + 0.12)
            elif my_action == 1 and opp_action == 0:
                self.trust_scores[opp] = max(0.0, self.trust_scores.get(opp, self.base_trust) - 0.25)
                self.punishment_impulse = min(1.0, self.punishment_impulse + 0.35)
                # New: Increase grudge on betrayal
                self.grudges[opp] = min(1.0, self.grudges.get(opp, 0.0) + 0.2)
            elif my_action == 0 and opp_action == 1:
