                variance = sum((r - avg) ** 2 for r in reps) / len(reps)
                # Smooth update to avoid rapid fluctuations
                self.reputation_variances[agent] = 0.7 * self.reputation_variances[agent] + 0.3 * variance

        self._update_trust(donor_id, recipient_id, donor_coop, recipient_coop)
