from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = 0.0
        self.coop_counts = {}
        self.total_interactions = {}
        self.own_recent = deque(maxlen=10)
        self.observed_recent = {}
        self.last_action_against = {}
        self.generation = 0
        self.round_in_generation = 0
        self.total_rounds = 0
        # CHANGED: Use a single reputation per agent instead of history, with decay
        self.rep_cache = {}
        # CHANGED: Forgiveness is now based on partner's reputation, not mood
        self.base_forgiveness = 0.2
        # REMOVED: mood
        # CHANGED: Trust is now binary (cooperated or not) with a long-term memory
        self.trust = {}
        # CHANGED: Suspicion is now a count of defections, not decaying
        self.suspicion = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Forgiveness based on opponent's reputation: good rep -> more forgiving
        opp_rep = self.get_rep(opponent)
        forgiveness = self.base_forgiveness + opp_rep * 0.02
        forgiveness = max(0.0, min(0.5, forgiveness))
        direct = self.last_action_against.get(opponent)
        if direct is not None:
            if direct == 'defect' and opp_rep < 2 - forgiveness * 10:
                return False
            if direct == 'cooperate' and opp_rep > -2 + forgiveness * 10:
                return True
        suspicion_level = self.suspicion.get(opponent, 0)
        if suspicion_level > 0:
            if opp_rep < suspicion_level * 0.5:
                return False
        return opp_rep >= 0

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_action = recipient_action
                other_id = recipient_id
            else:
                my_action = recipient_action
                other_action = donor_action
                other_id = donor_id
            self.last_action_against[other_id] = other_action
            # Update own reputation with consistency bonus
            consistency_bonus = 0.0
            if self.own_recent:
                if my_action == 'cooperate' and sum(1 for a in self.own_recent if a == 'cooperate') > len(self.own_recent) * 0.7:
                    consistency_bonus = 0.1
                elif my_action == 'defect' and sum(1 for a in self.own_recent if a == 'defect') > len(self.own_recent) * 0.7:
                    consistency_bonus = 0.1
            if (my_action == 'cooperate' and other_action == 'cooperate') or \
               (my_action == 'defect' and other_action == 'defect'):
                self.reputation += 0.5 + consistency_bonus
            else:
                self.reputation -= 0.5
            self.reputation = max(-10, min(10, self.reputation))
            self.own_recent.append(my_action)
            self.total_interactions[other_id] = self.total_interactions.get(other_id, 0) + 1
            if my_action == 'cooperate':
                self.coop_counts[other_id] = self.coop_counts.get(other_id, 0) + 1

            # CHANGED: Trust is binary: 1 if they cooperated, 0 if defected, but with memory
            # We store a counter of positive interactions and negative interactions
            if other_id not in self.trust:
                self.trust[other_id] = {'coop': 0, 'defect': 0}
            if other_action == 'cooperate':
                self.trust[other_id]['coop'] += 1
            else:
                self.trust[other_id]['defect'] += 1
            # Trust value is the ratio of cooperations, but capped at 10 interactions
            total = self.trust[other_id]['coop'] + self.trust[other_id]['defect']
            if total > 10:
                # Decay: halve the counts when total exceeds 10
                self.trust[other_id]['coop'] = int(self.trust[other_id]['coop'] * 0.5)
                self.trust[other_id]['defect'] = int(self.trust[other_id]['defect'] * 0.5)
            # CHANGED: Suspicion is a simple count of defections, not decaying
            if other_action == 'defect':
                self.suspicion[other_id] = self.suspicion.get(other_id, 0) + 1
            else:
                # Keep suspicion, but don't decay it
                pass
        else:
            # Third-party observation: update reputation with bounded update per observation
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.update_rep(donor_id, 0.3)
                self.update_rep(recipient_id, 0.3)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.update_rep(donor_id, 0.2)
                self.update_rep(recipient_id, 0.2)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.update_rep(donor_id, -0.3)
                self.update_rep(recipient_id, -0.1)
            else:
                self.update_rep(donor_id, -0.1)
                self.update_rep(recipient_id, 0.3)
            # CHANGED: Suspicion is a simple count, no decay
            if donor_action == 'defect':
                self.suspicion[donor_id] = self.suspicion.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.suspicion[recipient_id] = self.suspicion.get(recipient_id, 0) + 1
            for pid in (donor_id, recipient_id):
                if pid not in self.observed_recent:
                    self.observed_recent[pid] = deque(maxlen=10)
                self.observed_recent[pid].append(donor_action if pid == donor_id else recipient_action)

    def get_rep(self, agent_id):
        # Combine reputation with observed recent cooperation rate
        rep = self.reputation if agent_id == self.agent_id else 0
        if agent_id in self.rep_cache:
            # CHANGED: Use a single cached reputation with decay
            rep += self.rep_cache[agent_id] * 0.9
        if agent_id in self.observed_recent:
            recent = list(self.observed_recent[agent_id])
            if recent:
                coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
                rep += (coop_rate - 0.5) * 2
        if agent_id in self.total_interactions and self.total_interactions[agent_id] > 0:
            coop_ratio = self.coop_counts.get(agent_id, 0) / self.total_interactions[agent_id]
            rep += (coop_ratio - 0.5) * 1

        # CHANGED: Trust is a ratio of cooperations, no mood influence
        if agent_id in self.trust:
            total = self.trust[agent_id]['coop'] + self.trust[agent_id]['defect']
            if total > 0:
                trust_ratio = self.trust[agent_id]['coop'] / total
                rep += (trust_ratio - 0.5) * 2

        # CHANGED: Suspicion penalty is linear with count, no mood influence
        suspicion_level = self.suspicion.get(agent_id, 0)
        if suspicion_level > 0:
            rep -= suspicion_level * 0.5

        return rep

    def update_rep(self, agent_id, delta):
        # CHANGED: Update a single reputation with decay
        if agent_id in self.rep_cache:
            self.rep_cache[agent_id] = self.rep_cache[agent_id] * 0.9 + delta
        else:
            self.rep_cache[agent_id] = delta
        # Clamp to reasonable range
        self.rep_cache[agent_id] = max(-5, min(5, self.rep_cache[agent_id]))

