import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation/defection counts and outcomes for each opponent
        self.opponent_stats = {}  # opponent_id -> {'coop': int, 'defect': int, 'my_coop_reward': float}
        # Track global reputation: how often each agent cooperates (observed)
        self.reputation = {}  # agent_id -> {'coop': int, 'total': int}
        # Memory of recent outcomes to adapt
        self.recent_outcomes = []  # list of (opponent_id, my_action, opponent_action)
        # Remember if we are currently in a pair (set by framework)
        self._ctx_opponent_id = None
        # Personal cooperation propensity baseline
        self.base_coop = 0.5
        # Track rounds played
        self.rounds_played = 0
        # Track if we've been exploited recently
        self.exploited_count = 0

    def decide(self) -> bool:
        self.rounds_played += 1
        opp = self._ctx_opponent_id
        if opp is None:
            return True  # fallback

        # Get opponent's reputation
        opp_rep = self.reputation.get(opp, {'coop': 0, 'total': 0})
        total_obs = opp_rep['total']
        coop_rate = opp_rep['coop'] / total_obs if total_obs > 0 else 0.5

        # Get personal history with this opponent
        stats = self.opponent_stats.get(opp, {'coop': 0, 'defect': 0, 'my_coop_reward': 0.0})
        my_coop_count = stats['coop']
        my_defect_count = stats['defect']
        opp_coop_count = stats.get('opp_coop', 0)
        opp_defect_count = stats.get('opp_defect', 0)

        # Determine cooperation probability
        p = self.base_coop

        # Adjust based on opponent's general reputation
        p += (coop_rate - 0.5) * 0.4

        # Adjust based on personal history: if opponent cooperated with us, increase
        if my_coop_count + my_defect_count > 0:
            if opp_coop_count > opp_defect_count:
                p += 0.2
            elif opp_defect_count > opp_coop_count:
                p -= 0.3

        # If we've been exploited recently (they defected while we cooperated), lower p
        recent_exploit = False
        for _, my_a, opp_a in self.recent_outcomes[-5:]:
            if my_a == 'cooperate' and opp_a == 'defect':
                recent_exploit = True
                break
        if recent_exploit:
            p -= 0.2

        # If opponent has low reputation, defect more
        if total_obs > 5 and coop_rate < 0.3:
            p -= 0.3

        # Clamp
        p = max(0.05, min(0.95, p))

        # Deterministic decision based on threshold (use random only if needed)
        return random.random() < p

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both actors
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'total': 0}
            self.reputation[agent_id]['total'] += 1
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1

        # If we are one of the players, update personal history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Identify opponent and our action, opponent action
            if donor_id == self.agent_id:
                opp_id = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opp_id = donor_id
                my_action = recipient_action
                opp_action = donor_action

            # Initialize stats for opponent if needed
            if opp_id not in self.opponent_stats:
                self.opponent_stats[opp_id] = {'coop': 0, 'defect': 0, 'opp_coop': 0, 'opp_defect': 0}
            stats = self.opponent_stats[opp_id]
            if my_action == 'cooperate':
                stats['coop'] += 1
            else:
                stats['defect'] += 1
            if opp_action == 'cooperate':
                stats['opp_coop'] += 1
            else:
                stats['opp_defect'] += 1

            # Track recent outcome for adaptation
            self.recent_outcomes.append((opp_id, my_action, opp_action))
            if len(self.recent_outcomes) > 20:
                self.recent_outcomes.pop(0)

            # Track exploitation
            if my_action == 'cooperate' and opp_action == 'defect':
                self.exploited_count += 1
            else:
                # Decay exploited count over time
                self.exploited_count = max(0, self.exploited_count - 1)

