        self.total_rounds = 0
        self.recent_actions = deque(maxlen=10)
        self.defection_count = 0
        self.punishment_impulse = 0.0
        # New: Track recent opponent actions for a sliding window trust
        self.recent_opponent_actions = {}
        # New: A bias toward forgiveness after long cooperative streaks
        self.forgiveness_bias = 0.0
        # New: Track reputation volatility to adapt strategy
        self.reputation_volatility = {}
        # New: Baseline trust for unknown agents
        self.base_trust = 0.45
        # Child: Add a counter for times we were exploited (defected against)
        self.exploitation_count = 0
        # Child: Add a dynamic threshold that adapts based on exploitation
        self.dynamic_threshold = 0.40
        # Child: Add a memory of recent cooperation rates for adaptive behavior
        self.recent_cooperation_rates = deque(maxlen=10)
        # Child: Add a suspicion factor that increases with observed defections by others
        self.suspicion_factor = 0.0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        if opponent not in self.trust_scores:
            self.trust_scores[opponent] = self.base_trust

        rep = self.my_reputation.get(opponent, 0.5)
        if isinstance(rep, list):
            rep = sum(rep) / len(rep) if rep else 0.5

        hist = self.opponent_history.get(opponent, [])
        if len(hist) > 0:
            past_coop = sum(hist) / len(hist)
        else:
            past_coop = 0.5

        trust = self.trust_scores[opponent]
        # New: Use a more aggressive weight on recent behavior
        recent_opp = self.recent_opponent_actions.get(opponent, [])
        if len(recent_opp) > 0:
            recent_coop = sum(recent_opp) / len(recent_opp)
        else:
            recent_coop = 0.5

        # Child: Adjust weights based on suspicion factor - increase reliance on recent actions
        vol = self.reputation_volatility.get(opponent, 0.0)
        if vol > 0.3 or self.suspicion_factor > 0.5:
            combined_score = 0.1 * trust + 0.05 * rep + 0.1 * past_coop + 0.75 * recent_coop
        else:
            combined_score = 0.4 * trust + 0.2 * rep + 0.3 * past_coop + 0.1 * recent_coop

        # Child: Use a dynamic threshold that increases if we've been exploited
        if self.total_rounds > 0 and self.cooperation_count / self.total_rounds > 0.6:
            threshold = 0.50
        else:
            threshold = self.dynamic_threshold

        combined_score -= self.punishment_impulse * 0.15
        # Child: Add forgiveness bias that increases cooperation when we've been cooperative
        combined_score += self.forgiveness_bias * 0.15
        # Child: Subtract suspicion factor to be more cautious
        combined_score -= self.suspicion_factor * 0.2

        if random.random() < 0.03:
            return random.random() < 0.5

        return combined_score > threshold

