        if recipient_id != self.agent_id:
            self.last_opponent_action[recipient_id] = recipient_coop

        # Update generation actions
        if donor_id not in self.generation_actions:
            self.generation_actions[donor_id] = []
        if recipient_id not in self.generation_actions:
            self.generation_actions[recipient_id] = []
        self.generation_actions[donor_id].append(donor_coop)
        self.generation_actions[recipient_id].append(recipient_coop)

        # Update long-term cooperation rates for both agents
        if donor_id not in self.long_term_coop:
            self.long_term_coop[donor_id] = 0.5
        if recipient_id not in self.long_term_coop:
            self.long_term_coop[recipient_id] = 0.5
        alpha = 0.05
        self.long_term_coop[donor_id] = self.long_term_coop[donor_id] * (1 - alpha) + (1.0 if donor_coop else 0.0) * alpha
        self.long_term_coop[recipient_id] = self.long_term_coop[recipient_id] * (1 - alpha) + (1.0 if recipient_coop else 0.0) * alpha

        # NEW: Update recency-weighted cooperation rate - more responsive to recent actions
        if donor_id not in self.recency_weighted_coop:
            self.recency_weighted_coop[donor_id] = 0.5
        if recipient_id not in self.recency_weighted_coop:
            self.recency_weighted_coop[recipient_id] = 0.5
        # Higher weight for recent observations
        self.recency_weighted_coop[donor_id] = self.recency_weighted_coop[donor_id] * self.recency_decay + (1.0 if donor_coop else 0.0) * (1 - self.recency_decay)
        self.recency_weighted_coop[recipient_id] = self.recency_weighted_coop[recipient_id] * self.recency_decay + (1.0 if recipient_coop else 0.0) * (1 - self.recency_decay)

        # Adaptive threshold
        if len(self.generation_actions) > 0:
            all_actions = [a for actions in self.generation_actions.values() for a in actions]
            if len(all_actions) > 50:
                coop_rate = sum(all_actions) / len(all_actions)
                self.trust_threshold = 0.5 + (0.5 - coop_rate) * 0.3
                self.sensitivity = 1.0 + (coop_rate - 0.5) * 0.5

    def _update_reputation(self, agent_id: int, cooperated: bool) -> None:
        alpha = 0.1
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        current = self.reputation[agent_id]
        target = 1.0 if cooperated else 0.0
        if cooperated and current > 0.5:
            alpha += self.momentum
        elif not cooperated and current < 0.5:
            alpha += self.momentum
        self.reputation[agent_id] = current * (1 - alpha) + target * alpha

    def _reset_generation(self):
        if self.rounds_in_generation >= 30:
            self.generation_actions = {}
            self.rounds_in_generation = 0

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.interactions = {}
        self.recent_actions = {}
        self.generation_actions = {}
        self.self_coop_count = 0
        self.self_defect_count = 0
        self.trust_threshold = 0.5
        self.sensitivity = 1.0
        for i in range(15):
            self.reputation[i] = 0.5
            self.history[i] = []
            self.interactions[i] = [0, 0]
            self.recent_actions[i] = deque(maxlen=10)
            self.generation_actions[i] = []
        self._ctx_opponent_id = None
        self.rounds_in_generation = 0
        self.base_coop_prob = 0.5
        self.forgiveness = 0.2
        self.retaliation_threshold = 0.3
        self.momentum = 0.2
        self.last_opponent_action = {}
        # New: track consistency of opponent's recent behavior
        self.consistency_window = {}
        self.consistency_threshold = 0.7
        # New: track whether opponent has ever cooperated with us directly
        self.direct_coop_history = {}

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True

        opp_id = self._ctx_opponent_id
        self.rounds_in_generation += 1

        opp_rep = self.reputation.get(opp_id, 0.5)
        opp_history = self.history.get(opp_id, [])
        opp_recent = list(self.recent_actions.get(opp_id, []))

        coop_prob = 0.5 + (opp_rep - 0.5) * self.sensitivity

        coop_count, defect_count = self.interactions.get(opp_id, [0, 0])
        total_interactions = coop_count + defect_count
        if total_interactions > 0:
            opponent_coop_rate = coop_count / total_interactions
            coop_prob += (opponent_coop_rate - 0.5) * 0.3
            if opponent_coop_rate < self.retaliation_threshold:
                coop_prob -= 0.2

        if len(opp_recent) >= 4:
            last_four = opp_recent[-4:]
            if last_four == [True, False, True, False] or last_four == [False, True, False, True]:
                coop_prob -= 0.15

        if opp_recent and all(opp_recent[-3:]):
            coop_prob += self.forgiveness

        if opp_id in self.last_opponent_action:
            if self.last_opponent_action[opp_id]:
                coop_prob += 0.1
            else:
                coop_prob -= 0.05

        # New: consistency-based adjustment
        if opp_id in self.consistency_window and len(self.consistency_window[opp_id]) >= 5:
            window = list(self.consistency_window[opp_id])
            consistent_coop = sum(1 for a in window if a) / len(window)
            if consistent_coop >= self.consistency_threshold:
                coop_prob += 0.1  # Reward consistent cooperators
            elif consistent_coop <= 1 - self.consistency_threshold:
                coop_prob -= 0.1  # Penalize consistent defectors

        # New: direct cooperation bonus - if opponent has cooperated with us at least once, boost cooperation
        if opp_id in self.direct_coop_history and self.direct_coop_history[opp_id]:
            coop_prob += 0.15  # Trust those who cooperated directly with us

        coop_prob = max(0.1, min(0.9, coop_prob))
        return random.random() < coop_prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_coop = donor_action == 'cooperate'
        recipient_coop = recipient_action == 'cooperate'

        if donor_id not in self.history:
            self.history[donor_id] = []
        if recipient_id not in self.history:
            self.history[recipient_id] = []
        self.history[donor_id].append(donor_coop)
        self.history[recipient_id].append(recipient_coop)

        if donor_id not in self.recent_actions:
            self.recent_actions[donor_id] = deque(maxlen=10)
        if recipient_id not in self.recent_actions:
            self.recent_actions[recipient_id] = deque(maxlen=10)
        self.recent_actions[donor_id].append(donor_coop)
        self.recent_actions[recipient_id].append(recipient_coop)

        # New: update consistency tracking
        if donor_id not in self.consistency_window:
            self.consistency_window[donor_id] = deque(maxlen=10)
        if recipient_id not in self.consistency_window:
            self.consistency_window[recipient_id] = deque(maxlen=10)
        self.consistency_window[donor_id].append(donor_coop)
        self.consistency_window[recipient_id].append(recipient_coop)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # New: track direct cooperation with us
            if donor_id != self.agent_id and donor_coop and recipient_id == self.agent_id:
                self.direct_coop_history[donor_id] = True
            if recipient_id != self.agent_id and recipient_coop and donor_id == self.agent_id:
                self.direct_coop_history[recipient_id] = True

            if donor_id != self.agent_id and donor_id in self.interactions:
                if donor_coop:
                    self.interactions[donor_id][0] += 1
                else:
                    self.interactions[donor_id][1] += 1
            if recipient_id != self.agent_id and recipient_id in self.interactions:
                if recipient_coop:
                    self.interactions[recipient_id][0] += 1
                else:
                    self.interactions[recipient_id][1] += 1

        if donor_id == self.agent_id:
            if donor_coop:
                self.self_coop_count += 1
            else:
                self.self_defect_count += 1
        if recipient_id == self.agent_id:
            if recipient_coop:
                self.self_coop_count += 1
            else:
                self.self_defect_count += 1

        self._update_reputation(donor_id, donor_coop)
        self._update_reputation(recipient_id, recipient_coop)

        if donor_id != self.agent_id:
            self.last_opponent_action[donor_id] = donor_coop
        if recipient_id != self.agent_id:
            self.last_opponent_action[recipient_id] = recipient_coop

        if donor_id not in self.generation_actions:
            self.generation_actions[donor_id] = []
        if recipient_id not in self.generation_actions:
            self.generation_actions[recipient_id] = []
        self.generation_actions[donor_id].append(donor_coop)
        self.generation_actions[recipient_id].append(recipient_coop)

        if len(self.generation_actions) > 0:
            all_actions = [a for actions in self.generation_actions.values() for a in actions]
            if len(all_actions) > 50:
                coop_rate = sum(all_actions) / len(all_actions)
                self.trust_threshold = 0.5 + (0.5 - coop_rate) * 0.3
                self.sensitivity = 1.0 + (coop_rate - 0.5) * 0.5

    def _update_reputation(self, agent_id: int, cooperated: bool) -> None:
        alpha = 0.1
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.5
        current = self.reputation[agent_id]
        target = 1.0 if cooperated else 0.0
        if cooperated and current > 0.5:
            alpha += self.momentum
        elif not cooperated and current < 0.5:
            alpha += self.momentum
        self.reputation[agent_id] = current * (1 - alpha) + target * alpha

    def _reset_generation(self):
        if self.rounds_in_generation >= 30:
            self.generation_actions = {}
